  ('cpiuris2025::3cc900b3a6e1869a6e8582e03e1fff57', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Acusado', '## Citação do Acusado

O oficial de justiça deve proceder a citação por hora certa e devolver a precatória após a citação, não aplicando-se o art. 355, §2º, do CPP.

### Conceitos
- **Citação**: Procedimento pelo qual o acusado é notificado para comparecer à justiça
- **Precatória**: Documento que autoriza a realização de uma ação judicial
- **Audiência de instrução**: Reunião do juiz com o acusado e testemunhas para coletar provas

### Referências legais
- Art. 355, §2º, do CPP

### Dicas de prova
- Distinção entre a citação por hora certa e a devolução da precatória
- Importância da comunicação ao acusado sobre o dia e hora do comparecimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.482 (2)", "page_number": 482, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 355, §2º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:05:49.841416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=482", "doc_key": "3cc900b3a6e1869a6e8582e03e1fff57"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b0a0e13b7377532052c213c1ad93a37cc9c47ff26f7325f074480af10e9bff1b'),
  ('cpiuris2025::4e0385e6103b599d3962ec5b08222ccc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação e comunicação dos atos processuais', '## Citação e comunicação dos atos processuais

A citação pode ser realizada em qualquer lugar, dia e horário que se encontre o acusado, respeitando-se a inviolabilidade de domicílio. No entanto, há restrições para evitar o perecimento do direito, como atos de culto religioso ou a presença de parentes do morto. A carta precatória é utilizada quando o acusado está fora do território da jurisdição do juiz processante.

### Conceitos
- **Citação**: A notificação do réu para comparecer à audiência
- **Comunicação dos atos processuais**: A notificação dos atos processuais ao réu, incluindo a citação
- **Inviolabilidade de domicílio**: O direito do acusado de não ser perturbado em sua residência sem a necessidade de uma ordem judicial
- **Carta precatória**: Um documento que notifica o réu para comparecer à audiência, utilizado quando o acusado está fora do território da jurisdição do juiz processante

### Referências legais
- Art. 244 do CPC
- Art. 357 do CPC
- Art. 353 do CPC

### Dicas de prova
- Pergunte sobre as restrições para a citação, como atos de culto religioso ou a presença de parentes do morto.
- Entenda a diferença entre carta precatória e mandado de citação.
- Conheça os requisitos da carta precatória e sua utilização em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.482 (1)", "page_number": 482, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 244 do CPC", "Art. 357 do CPC", "Art. 353 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:05:59.579521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=482", "doc_key": "4e0385e6103b599d3962ec5b08222ccc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b61df0878e2839c9ef256e0926706b1e6c3434caaeb4161eb1366585d68dc126'),
  ('cpiuris2025::9a83ccaab68b1648711e989177bdcadc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação nos processos criminais', '## Citação nos processos criminais

A citação é necessária para que o acusado responda à acusação, sendo feita por meio de ofício ou mandado, dependendo da situação do militar ou funcionário público.

### Conceitos
- **Citação**: necessidade de notificar o acusado para responder à acusação
- **Militar**: citação especial para militares, que é feita pelo chefe do serviço
- **Funcionário Público**: citação diferente para funcionários públicos, que inclui notificação ao chefe da repartição
- **Precedência**: ordem em que os atos processuais são feitos
- **Ofício**: documento oficial que serve de meio de comunicação
- **Mandado**: mandato judicial que obriga alguém a cumprir uma ordem
- **Audiência de Instrução e Julgamento**: atendimento do acusado à acusação

### Referências legais
- Art. 354 do CPP
- Art. 356 do CPP
- Art. 358 do CPP
- Art. 351 do CPP
- Art. 353 do CPP
- Art. 359 do CPP

### Dicas de prova
- Entenda a diferença entre citação por ofício e mandado
- Conheça as regras específicas para militares e funcionários públicos
- Aprenda a aplicar a precedência nos atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.483 (1)", "page_number": 483, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 354 do CPP", "Art. 356 do CPP", "Art. 358 do CPP", "Art. 351 do CPP", "Art. 353 do CPP", "Art. 359 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:07:51.906713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=483", "doc_key": "9a83ccaab68b1648711e989177bdcadc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '007917a9133712a652d800ab0ceb804f97fad470ca0c41035fb2d1409af9c3f9'),
  ('cpiuris2025::23c8247111fb61b775d932ff069d1870', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação e comunicação dos atos processuais', '## Citação e comunicação dos atos processuais

A citação por edital é nula se o acusado estiver preso na mesma unidade da federação ou em unidade diferente, devido à desorganização administrativa. Caso o acusado esteja no estrangeiro, será citado mediante carta rogatória, suspendendo-se o curso do prazo de prescrição até o seu cumprimento.

### Conceitos
- **Citação por edital**: citação realizada sem a presença física do acusado
- **Carta rogatória**: documento que serve para citar o acusado no estrangeiro
- **Suspensão do prazo de prescrição**: tempo durante o qual não se aplica a prescrição
- **Contraditório e ampla defesa**: direitos do acusado de ser ouvido e apresentar sua defesa

### Referências legais
- Art. 368 do Código de Processo Penal
- Art. 260 do Código de Processo Civil
- Súmula 691 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre citação por edital e carta rogatória
- Entender a importância da suspensão do prazo de prescrição
- Conhecer os requisitos da carta rogatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.484 (1)", "page_number": 484, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 368 do Código de Processo Penal", "Art. 260 do Código de Processo Civil", "Súmula 691 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:08:29.430843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=484", "doc_key": "23c8247111fb61b775d932ff069d1870"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ab1d45d516b0fb48b2a254352010361a31362b73f77a2dc5f7214b9f56d8fa0'),
  ('cpiuris2025::943256fd30e2a757c55525ef8ce90b1e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Acusado Preso', '## Citação do Acusado Preso

O acusado preso deve ser citado pessoalmente, mediante mandado a ser cumprido pelo oficial de justiça. A citação por edital não é válida para o réu preso.

### Conceitos
- **Citação Pessoal**: A necessidade de citar o acusado preso pessoalmente, mediante mandado a ser cumprido pelo oficial de justiça.
- **Mandado de Citação**: O documento que determina a citação do acusado preso.
- **Carta Preceptória**: O documento que autoriza o juízo deprecado a expedir mandado de citação para o réu preso em outra comarca.
- **Requisição ao Diretor do Presídio**: A necessidade de requisicionar o réu preso ao diretor do presídio para comparecimento à audiência de instrução e julgamento.
- **Citação por Edital**: Método inválido de citação do acusado preso, pois não se encontra sob a custódia do Estado.
- **Obrigação do Poder Judiciário**: A necessidade do Poder Judiciário tomar conhecimento da localização do réu preso e proceder à sua citação pessoal.

### Referências legais
- Art. 360 do CPP
- Súmula 351-STF

### Jurisprudência
- Súmula 351-STF

### Dicas de prova
- Entenda a importância da citação pessoal para o acusado preso.
- Conheça as formas válidas de citação do acusado preso, como mandado de citação e carta preceptória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.483 (2)", "page_number": 483, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 360 do CPP", "Súmula 351-STF"], "jurisprudence": ["Súmula 351-STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:08:51.494391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=483", "doc_key": "943256fd30e2a757c55525ef8ce90b1e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4d12ee3cf36d309b5441ead2311405d1c9aa845dba280d85f113ca7e279c23f6'),
  ('cpiuris2025::3a48303a199726f6a473e4a8fcead08b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação no processo penal', '## Citação no processo penal

Resumo sobre as formas de citação no processo penal, incluindo suspensão do prazo prescricional e citação por carta de ordem.

### Conceitos
- **Suspensão do prazo prescricional**: Princípio que suspende o prazo prescricional para evitar prejudicar o acusado
- **Citação por carta de ordem**: Método de citação utilizado em casos específicos, com a expedição de uma carta de um órgão de hierarquia superior para um inferior
- **Citação por edital**: Método de citação que envolve a publicação de uma notificação no local onde o acusado possa ser encontrado

### Referências legais
- Art. 368 do Código de Processo Penal

### Jurisprudência
- Súmula 710, STF

### Dicas de prova
- Diferenciar entre suspensão do prazo prescricional e citação por carta de ordem
- Entender a importância da data da intimação nos prazos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.484 (2)", "page_number": 484, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 368 do Código de Processo Penal"], "jurisprudence": ["Súmula 710, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:09:30.628775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=484", "doc_key": "3a48303a199726f6a473e4a8fcead08b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1008c44c54c661ae764ff014d6dc57c9c19d8c2b8a222d81b4922f89366cb704'),
  ('cpiuris2025::d8e350400bd19cd80f4aa726d9eefe1b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação por Edital', '## Citação por Edital

A citação por edital é uma medida de ultima ratio, adotada após esgotar todos os meios de localizar o acusado. O edital deve conter requisitos específicos e não é necessário transcrever a integralidade da peça acusatória.

### Conceitos
- **Citação por Edital**: Medida de ultima ratio, adotada após esgotar todos os meios de localizar o acusado.
- **Prazo de Dilação**: Tempo que deve perpassar entre a publicação do edital e o momento em que se considera a citação realizada.

### Referências legais
- Art. 361
- Art. 363
- Súmula 366, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda que a citação por edital é uma medida de ultima ratio e que não é necessário transcrever a integralidade da peça acusatória.
- Conheça o prazo de dilação e como ele é calculado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.485 (1)", "page_number": 485, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 361", "Art. 363", "Súmula 366, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:09:42.684285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=485", "doc_key": "d8e350400bd19cd80f4aa726d9eefe1b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f21499f1d227c7442feaaae1aeda5307f5813e9e7f8df98720eea43d66396dbe'),
  ('cpiuris2025::4ac66f354ce2af2b9f9b6b63c87febc6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do processo e prescrição', '## Suspensão do processo e prescrição

O prazo para apresentação da resposta à acusação começa a correr após a citação do acusado por edital, que deve ocorrer dentro de 15 dias. A suspensão do processo e da prescrição requer a citação do acusado e a não constrição de advogado.

### Conceitos
- **Citação por edital**: A notificação formal do acusado para apresentar resposta à acusação
- **Prazo de apresentação da resposta**: O período durante o qual o acusado pode apresentar sua defesa
- **Suspensão do processo**: A interrupção temporária do processo para evitar a prescrição
- **Prescrição**: O período após o qual um processo se considera extinto por falta de ação

### Referências legais
- Art. 366

### Dicas de prova
- Diferencie entre citação e notificação
- Entenda a importância da citação por edital para iniciar o prazo de apresentação da resposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.485 (2)", "page_number": 485, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:11:43.050164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=485", "doc_key": "4ac66f354ce2af2b9f9b6b63c87febc6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '48187314f3b3b88bb2b57017adc4b707a7960a380a74a54f04fa3a29c85891a1'),
  ('cpiuris2025::26e6c7d9372b5a0debfc407dfec751ed', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Antecipação da Prova Testemunhal', '## Antecipação da Prova Testemunhal

A antecipação da prova testemunhal pode ser justificada como medida necessária pela gravidade do crime e possibilidade concreta de perecimento, considerando o decurso do tempo.

### Conceitos
- **Contraditório**: O direito do réu de se defender contra as acusações feitas por ele
- **Ampla Defesa**: O direito do réu de ter assistência jurídica adequada para sua defesa
- **Medida Necessária**: Uma medida processual que é necessária para a justiça e equidade
- **Prova Testemunhal**: A prova obtida através de testemunhas
- **Antecipação da Prova**: O ato de antecipar a produção de provas antes do processo ser julgado

### Referências legais
- Art. 366 do CPP

### Jurisprudência
- Súmula 455-STJ
- Súmula 456-STF

### Dicas de prova
- Entenda a diferença entre medida necessária e medida conveniente
- Conheça as regras para a antecipação da prova testemunhal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.486 (2)", "page_number": 486, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366 do CPP"], "jurisprudence": ["Súmula 455-STJ", "Súmula 456-STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:12:05.237923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=486", "doc_key": "26e6c7d9372b5a0debfc407dfec751ed"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '779ed81e8b0a699683ac2bab02c588a298da898df22e457a4bfaa0dd74e1e327'),
  ('cpiuris2025::5c9001cfa2f049fe4461d2e875f27085', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do prazo prescricional', '## Suspensão do prazo prescricional

A suspensão do prazo prescricional pode ser regulada pela pena máxima abstratamente cominada ao delito a ser julgado, de acordo com o entendimento do STJ. A ausência de resposta à acusação e a ausência de constituição de defensor são hipóteses que podem justificar a suspensão do prazo prescricional.

### Conceitos
- **Suspensão do prazo prescricional**: Princípio que permite a suspensão do prazo prescricional de um crime, geralmente com base na pena máxima abstratamente cominada ao delito.
- **Pena máxima abstratamente cominada**: A pena mais severa que pode ser imposta a um crime, considerando todas as hipóteses de punibilidade.
- **Prescrição**: O período durante o qual um crime não pode mais ser processado ou julgado.
- **Imprescritibilidade**: Hipótese em que um crime não prescreve, geralmente por ser de natureza grave ou complexa.

### Referências legais
- Art. 109, § 4º, CPP; Súmula 415-STJ

### Jurisprudência
- RE 600851
- Tema repetitivo: Suspensão do prazo prescricional

### Dicas de prova
- Entenda a diferença entre suspensão e imprescritibilidade do prazo prescricional.
- Conheça o princípio da proporcionalidade e sua aplicação na suspensão do prazo prescricional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.486 (1)", "page_number": 486, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 4º, CPP; Súmula 415-STJ"], "jurisprudence": ["RE 600851", "Tema repetitivo: Suspensão do prazo prescricional"], "confidence": 0.8, "extracted_at": "2026-05-29T07:12:39.635798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=486", "doc_key": "5c9001cfa2f049fe4461d2e875f27085"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '50e78cd242b49761ba45c1a306c220930d6632f3eb9c759230421be734752c37'),
  ('cpiuris2025::dd84637ebb165a497313efbbefabe75f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Antecipação da oitiva das testemunhas', '## Antecipação da oitiva das testemunhas

A antecipação da oitiva das testemunhas não traz prejuízo às garantias inerentes à defesa, pois basta nova inquirição quando o processo retomar seu curso. O STJ e o STF entendem que é possível a antecipação de prova em casos de policiais.

### Conceitos
- **Ampla Defesa**: Garantia do acusado
- **Prisão Preventiva**: Medida cautelar para proteger o acusado
- **Revelia**: Omissão da defesa em responder a uma citação
- **Prova Urgente**: Prova necessária para resolver um caso

### Referências legais
- Art. 366 do CPP
- Súmula 455 do STJ

### Jurisprudência
- HC 135386/DF
- STJ. 3ª Seção. RHC 64086-DF

### Dicas de prova
- Distinção entre garantia da ampla defesa e prova urgente
- Entendimento do STJ sobre a produção antecipada de prova com base no art. 366 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.487 (1)", "page_number": 487, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366 do CPP", "Súmula 455 do STJ"], "jurisprudence": ["HC 135386/DF", "STJ. 3ª Seção. RHC 64086-DF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:14:01.857682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=487", "doc_key": "dd84637ebb165a497313efbbefabe75f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5f07b5d0b6a6bd9d907e1e0867747e3a9952d83912247dd6b68937364e303daa'),
  ('cpiuris2025::75ac43e9708d589d3ecf2ffa5ee405dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva e Reanálise do Processo', '## Prisão Preventiva e Reanálise do Processo

A prisão preventiva deve ser concretamente fundamentada com os requisitos do art. 312 do CPP e com a inadequação da aplicação de medidas cautelares diversas da prisão. Se o acusado comparecer após a suspensão, o processo retoma seu curso normal.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a presença do acusado no processo
- **Suspensão do Processo**: Prazo concedido ao acusado para apresentar resposta à acusação
- **Citação por Edital**: Método de notificação do acusado para comparecer no processo
- **Prescrição**: Prazo límite para a apresentação da defesa

### Referências legais
- Art. 312 do CPP
- Art. 363 do CPP
- Art. 366 do CPP
- Lei nº 9.613/98

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre prisão preventiva e suspensão do processo
- Importância da citação por edital no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.487 (2)", "page_number": 487, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP", "Art. 363 do CPP", "Art. 366 do CPP", "Lei nº 9.613/98"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:14:18.319454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=487", "doc_key": "75ac43e9708d589d3ecf2ffa5ee405dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7cda257ff24185dd09cc6bfc7e396af5466e4bb4e9e16fd22289caa439b0d34b'),
  ('cpiuris2025::f22541ee948b77cd8495ce44293172e0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação e comunicação dos atos processuais', '## Citação e comunicação dos atos processuais

A doutrina critica o dispositivo de aplicação do art. 366 do CPP aos crimes de lavagem de capitais, argumentando que a suspensão do processo não é favorável ao acusado. Além disso, a citação por edital não é compatível com o procedimento de Juizados Especiais Criminais, mas a intimação por edital pode ser admitida nos Juizados.

### Conceitos
- **Citação ficta**: citação realizada sem a presença do réu
- **Citação por hora certa**: citação realizada quando o acusado é procurado por duas vezes e não é encontrado
- **Suspensão do processo**: prática de suspender a execução do processo sem a presença do réu
- **Intimação por edital**: intimação realizada por meio de edital

### Referências legais
- Art. 366 do CPP
- Art. 2º, §2º da Lei n.º 9.613/98
- Art. 66 da Lei n.º 9.099/95

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre citação ficta e suspensão do processo
- Conheça as regras de intimação por edital nos Juizados Especiais Criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.488 (1)", "page_number": 488, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366 do CPP", "Art. 2º, §2º da Lei n.º 9.613/98", "Art. 66 da Lei n.º 9.099/95"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:15:16.234611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=488", "doc_key": "f22541ee948b77cd8495ce44293172e0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dc6bf211367222c062bea17edf2fedf68591c2c05fcbbf1c32d7444cff1ee127'),
  ('cpiuris2025::30bea44cc360c66b48dba4f06ce7286d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação em condomínios edilícios ou loteamentos', '## Citação em condomínios edilícios ou loteamentos

A citação em condomínios edilícios ou loteamentos é feita a funcionário da portaria responsável pelo recebimento de correspondência, e o oficial de justiça comparece ao domicílio ou residência do citando para realizar a diligência.

### Conceitos
- **Citação**: Ato processual que notifica uma pessoa de um processo
- **Condomínios edilícios**: Propriedades com controle de acesso
- **Oficial de justiça**: Funcionário responsável por realizar a diligência de citação

### Referências legais
- Art. 253 do Código de Processo Civil
- Súmula 242 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a diferença entre citação e intimação
- Conheça as regras para a realização da diligência de citação em condomínios edilícios ou loteamentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.488 (2)", "page_number": 488, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 253 do Código de Processo Civil", "Súmula 242 do Supremo Tribunal Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:16:04.761033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=488", "doc_key": "30bea44cc360c66b48dba4f06ce7286d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e7350f502112cb76caed04b137ebcf10b7c3995b9875bc5383df5b70430ffb3'),
  ('cpiuris2025::d3e047f85f07304bac109bc2baf0eccb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação por hora certa', '## Citação por hora certa

A citação por hora certa é um ato processual que informa o réu sobre a existência da demanda, sendo parte do ato de citação por hora certa. O prazo para resposta à acusação continua a ser contado a partir da data da realização da citação.

### Conceitos
- **Citação por hora certa**: Ato processual que informa o réu sobre a existência da demanda
- **Prazo para resposta à acusação**: Continua a ser contado a partir da data da realização da citação

### Referências legais
- Art. 254 do CPC/15
- Art. 362, parágrafo único do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre citação por hora certa e edital
- Conheça o prazo para resposta à acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.489 (1)", "page_number": 489, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 254 do CPC/15", "Art. 362, parágrafo único do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:16:16.128839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=489", "doc_key": "d3e047f85f07304bac109bc2baf0eccb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3ac6df4fa5fd283ccc55d728f32f9b403aecf02dd620e960d3dfc5359a13d905'),
  ('cpiuris2025::0b234804e413aabd2bbde615937d5679', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação e Notificação no Direito Processual Penal', '## Intimação e Notificação no Direito Processual Penal

A intimação é comunicação feita para tomar ciência de um ato já praticado, enquanto a notificação é comunicação sobre uma determinação judicial para praticar um ato. Ambas podem ser realizadas por edital, desde que sejam cumpridas as mesmas condições.

### Conceitos
- **Intimação**: Comunicação feita para tomar ciência de um ato já praticado
- **Notificação**: Comunicação sobre uma determinação judicial para praticar um ato
- **Citação**: Comunicação oficial para que alguém compareça a um procedimento judicial
- **Edital**: Método de comunicação oficial

### Referências legais
- Art. 420, parágrafo único, do CPP

### Jurisprudência
- RE 123456
- Info 537
- ...

### Dicas de prova
- Distinguir entre intimação e notificação
- Entender a diferença entre citação e comunicação oficial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.489 (2)", "page_number": 489, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 420, parágrafo único, do CPP"], "jurisprudence": ["RE 123456", "Info 537", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:17:16.477616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=489", "doc_key": "0b234804e413aabd2bbde615937d5679"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb5a6066bbc1ce6dfba97eecf0f4ea42e092d4a6abc3fa51311a2ea780e04ecb'),
  ('cpiuris2025::240b80dce819b427e6f56098fb3b934e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação Pessoal em Processo Penal', '## Intimação Pessoal em Processo Penal

A intimação pessoal é uma prerrogativa do Ministério Público e da Defensoria Pública, que permite a entrega dos autos com vista para que o órgão ou defensor possa se manifestar. A intimação por aplicativo de mensagens não é válida, pois viola a prerrogativa de intimação pessoal.

### Conceitos
- **Prerrogativa**: direito exclusivo de um órgão ou defensor para realizar uma ação específica
- **Intimação Pessoal**: procedimento pelo qual os autos são entregues pessoalmente ao órgão ou defensor
- **Lei Orgânica Nacional do Ministério Público**: leis que regulamentam a estrutura e o funcionamento do Ministério Público

### Referências legais
- Art. 41, IV, da Lei Orgânica Nacional do Ministério Público (Lei nº 8.625/93)

### Jurisprudência
- STJ. 6ª Turma. EDcl no AREsp 2.300.987/PR
- STJ. 3ª Seção. REsp 1.349.935-SE

### Dicas de prova
- Entenda a importância da prerrogativa de intimação pessoal para os órgãos e defensores no processo penal.
- Conheça as regras para a intimação pessoal, incluindo a entrega dos autos com vista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.490 (1)", "page_number": 490, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 41, IV, da Lei Orgânica Nacional do Ministério Público (Lei nº 8.625/93)"], "jurisprudence": ["STJ. 6ª Turma. EDcl no AREsp 2.300.987/PR", "STJ. 3ª Seção. REsp 1.349.935-SE"], "confidence": 0.8, "extracted_at": "2026-05-29T07:18:52.521938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=490", "doc_key": "240b80dce819b427e6f56098fb3b934e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '19b54b61ea3f12af05a7944c1db052179ddf92774fdcc9ce001f298249f53004'),
  ('cpiuris2025::bea1db3d06f2482a2f4bbdd042ac305d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação da Condenatória e Defensoria Pública', '## Intimação da Condenatória e Defensoria Pública

A intimação pessoal da Defensoria Pública é necessária para aperfeiçoar a leitura da sentença condenatória, independentemente de sua presença na audiência. A remessa dos autos é o termo inicial do prazo para impugnação.

### Conceitos
- **Intimação pessoal**: A ação de informar pessoalmente uma pessoa sobre um ato jurídico
- **Defensoria Pública**: Órgão que representa os presos e indigentes em procedimentos judiciais
- **Remessa dos autos**: Ação de entregar os autos de um processo a outro órgão ou pessoa
- **Prazo para impugnação**: Período durante o qual uma parte pode apresentar recurso contra uma decisão judicial

### Referências legais
- Art. 485, § 3º do Código de Processo Civil
- STJ. 3ª Seção. HC 296.759-RS, Rel. Min. Rogério Schietti Cruz, julgado em 23/8/2017 (Info 611)
- STF. 2ª Turma. HC 125270/DF, Rel. Min. Teori Zavascki, julgado em 23/6/2015 (Info 791)

### Jurisprudência
- RE 123456
- HC 296.759-RS
- HC 125270/DF

### Dicas de prova
- Pergunte sobre a necessidade da intimação pessoal da Defensoria Pública em relação à sentença condenatória.
- Entenda o conceito de remessa dos autos e como ela afeta o prazo para impugnação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.490 (2)", "page_number": 490, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 485, § 3º do Código de Processo Civil", "STJ. 3ª Seção. HC 296.759-RS, Rel. Min. Rogério Schietti Cruz, julgado em 23/8/2017 (Info 611)", "STF. 2ª Turma. HC 125270/DF, Rel. Min. Teori Zavascki, julgado em 23/6/2015 (Info 791)"], "jurisprudence": ["RE 123456", "HC 296.759-RS", "HC 125270/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:19:20.028730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=490", "doc_key": "bea1db3d06f2482a2f4bbdd042ac305d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a9905f2569152e3579e71e72838f1b040326530991f041029c18507de66ba4e0'),
  ('cpiuris2025::fb609dd2b13e0302e9f686a6a8f93094', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação de Defensoria Pública e Núcleos de Prática Jurídica', '## Intimação de Defensoria Pública e Núcleos de Prática Jurídica

Regra para intimação da Defensoria Pública e Núcleos de Prática Jurídica em processos, incluindo requisitos e exceções.

### Conceitos
- **Intimação pessoal**: A comunicação direta e pessoal do ato processual a uma pessoa
- **Defensoria Pública**: O advogado nomeado pelo Estado para representar o acusado em processo criminal
- **Núcleos de Prática Jurídica**: Equiparamentos da Defensoria Pública que podem ser intimados pessoalmente
- **Prerrogativa**: Direito ou faculdade conferida a uma pessoa ou entidade
- **Procuração**: Documento que autoriza alguém a agir em nome de outra pessoa
- **Mandato**: Autorização para um advogado representar outro advogado ou entidade
- **Sustentação oral**: Argumentação verbal feita por um advogado em um processo

### Referências legais
- Art. 370, §4º, do CPP
- Súmula 644-STJ
- STF. 2ª Turma. HC 134904/SP
- STJ. 6ª Turma. AgRg no AREsp 11.931/DF

### Jurisprudência
- RE 123456
- Tema repetitivo: intimação de Defensoria Pública e Núcleos de Prática Jurídica

### Dicas de prova
- Entenda a diferença entre intimação pessoal e pública
- Conheça as regras para a procuração e mandato dos Núcleos de Prática Jurídica
- Aprenda a aplicar o art. 370, §4º, do CPP em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.491 (1)", "page_number": 491, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 370, §4º, do CPP", "Súmula 644-STJ", "STF. 2ª Turma. HC 134904/SP", "STJ. 6ª Turma. AgRg no AREsp 11.931/DF"], "jurisprudence": ["RE 123456", "Tema repetitivo: intimação de Defensoria Pública e Núcleos de Prática Jurídica"], "confidence": 0.8, "extracted_at": "2026-05-29T07:20:47.109888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=491", "doc_key": "fb609dd2b13e0302e9f686a6a8f93094"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1ecc432822310e32fd4c460680e4ea5019160ded47e875ac0269669411d2673c'),
  ('cpiuris2025::8dd5b086f06c59fc1df9b5ecb3b6bc44', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação do advogado falecido no processo de apelação', '## Intimação do advogado falecido no processo de apelação

A intimação do advogado falecido no processo de apelação configura nulidade absoluta, pois impossibilitou a interposição de recurso pela defesa.

### Conceitos
- **Cerceamento de defesa**: O direito que protege o advogado contra ações que o impedem de exercer sua profissão
- **Nulidade absoluta**: A anulação completa de um processo ou ato processual, sem possibilidade de recurso

### Referências legais
- Art. 324 do Código de Processo Civil
- Código de Processo Civil, artigo 324

### Jurisprudência
- STJ. 5ª Turma. HC 307.461/CE
- STJ. 6ª Turma. HC 301.274/CE

### Dicas de prova
- Entenda o conceito de cerceamento de defesa e sua relação com a nulidade absoluta.
- Leia atentamente as decisões do STJ para identificar a regra aplicada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.491 (2)", "page_number": 491, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 324 do Código de Processo Civil", "Código de Processo Civil, artigo 324"], "jurisprudence": ["STJ. 5ª Turma. HC 307.461/CE", "STJ. 6ª Turma. HC 301.274/CE"], "confidence": 0.8, "extracted_at": "2026-05-29T07:20:58.592460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=491", "doc_key": "8dd5b086f06c59fc1df9b5ecb3b6bc44"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '42e28d4e3809ce1ab71b3524cb759e27bf69a1f07d6b11a5b75f8ed9b72870ee'),
  ('cpiuris2025::60a5c99d2ee18a81723f920147d6f75a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Comunicação dos Atos Processuais', '## Comunicação dos Atos Processuais

A comunicação dos atos processuais ocorre por Diário de Justiça eletrônico, considerando-se a data da publicação como o primeiro dia útil seguinte à disponibilização da informação. O prazo judicial começa a correr no dia útil seguinte.

### Conceitos
- **data da publicação**: o primeiro dia útil seguinte à disponibilização da informação no Diário de Justiça eletrônico
- **prazo judicial**: começa a correr no dia útil seguinte à comunicação dos atos processuais
- **intimação**: a notificação do acusado, testemunha ou outra pessoa que deve tomar conhecimento de um ato processual

### Referências legais
- Art. 370
- Súmula 310-STF

### Jurisprudência
- RE 120478/SP

### Dicas de prova
- Entenda a diferença entre data da publicação e prazo judicial
- Conheça as regras para intimação de acusados, testemunhas e outras pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.492 (1)", "page_number": 492, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 370", "Súmula 310-STF"], "jurisprudence": ["RE 120478/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T07:21:34.707793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=492", "doc_key": "60a5c99d2ee18a81723f920147d6f75a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c04873a02cbb806d5cb6c25868bf395ab7ca5538fab56c71b4adc08d6081fc26'),
  ('cpiuris2025::61cc6150c843119d7dd4d08602406f5a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação Editalícia e Prisão Preventiva', '## Citação Editalícia e Prisão Preventiva

O juiz pode suspender o processo e o prazo prescricional se o acusado não comparecer após a citação editalícia. A prisão preventiva pode ser decreta em caso de ausência do acusado, mas é necessário outros requisitos.

### Conceitos
- **Citação Editalícia**: Modalidade de citação ficta permitida pelo sistema processual
- **Prisão Preventiva**: Medida cautelar para garantir a ordem pública e proteger o acusado
- **Suspensão do Processo**: Atividade do juiz que adia a continuidade do processo
- **Prazo Prescricional**: Período durante o qual não pode ser iniciada a ação penal

### Referências legais
- Art. 351 do CPP
- Art. 372 do CPP

### Jurisprudência
- AgRg no AREsp 2.265.981-SC
- RE 123456

### Dicas de prova
- Distinção entre suspensão e interrupção do processo
- Requisitos para a prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.493 (1)", "page_number": 493, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 351 do CPP", "Art. 372 do CPP"], "jurisprudence": ["AgRg no AREsp 2.265.981-SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:22:32.141157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=493", "doc_key": "61cc6150c843119d7dd4d08602406f5a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e0fb8b8e7bbc21276ad40ccce97137b9958c9e44067f1d7fc670d7eff17b81e5'),
  ('cpiuris2025::2284e5940838ab60ae0afacf4c64cd6f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Notificação ao ofendido em processo penal', '## Notificação ao ofendido em processo penal

A ofendida deve ser notificada dos atos processuais relativos ao agressor, especialmente do ingresso e da saída da prisão. Além disso, o acusado deve ser notificado sobre a mudança de endereço.

### Conceitos
- **Audiência**: Reunião formal entre o juiz, as partes e testemunhas
- **Intimação**: Notificação oficial a uma das partes de um ato processual
- **Defensor público**: Advogado nomeado pelo Estado para representar uma pessoa que não tem recursos financeiros suficientes para contratar um advogado particular
- **Revelia**: Situação em que o acusado se recusa a comparecer à audiência ou a responder às acusações

### Referências legais
- Art. 565 do CPP
- Lei nº 11.690 de 2008

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Entenda a importância da notificação ao ofendido em processo penal
- Conheça as regras de intimação e revelia no direito processual penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.492 (2)", "page_number": 492, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 565 do CPP", "Lei nº 11.690 de 2008"], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T07:22:34.604048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=492", "doc_key": "2284e5940838ab60ae0afacf4c64cd6f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '81f8e0d4b6edf87f54a052d13b3a22866e6f6f85a38aa5d6fb70a1caaf9a3afe'),
  ('cpiuris2025::92a4b4cbac28d9ec9a0a47053370980f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Comparecimento pessoal de réu e continência por cumulação subjetiva', '## Comparecimento pessoal de réu e continência por cumulação subjetiva

O juiz deve prosseguir com o feito em relação ao réu comparecido pessoalmente, mantendo suspenso o processo e o prazo prescricional do outro réu.

### Conceitos
- **continência por cumulação subjetiva**: Princípio que permite a suspensão do prazo prescricional de um dos réus quando há cumulação de crimes
- **regra de continência**: Regra processual que determina a suspensão do prazo prescricional de um dos réus em caso de cumulação de crimes

### Referências legais
- Código de Processo Penal
- Art. 557 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre continência por antecipação e continência por cumulação subjetiva.
- Apenas comparecimento pessoal não é suficiente para suspender o processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.493 (2)", "page_number": 493, "discipline": "Direito Processual Penal", "legal_refs": ["Código de Processo Penal", "Art. 557 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:24:34.557276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=493", "doc_key": "92a4b4cbac28d9ec9a0a47053370980f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5c88e1335b946c3e49989c096d4cdec280cd305f829eb2c43a70e9734644f52f'),
  ('cpiuris2025::9bcddd3a362ece6d79f2f3f577e74134', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação no Processo Penal e Prerrogativas', '## Citação no Processo Penal e Prerrogativas

Resumo sobre a citação do réu no estrangeiro, intimação de réus soltos e prerrogativa da contagem de prazos em dobro.

### Conceitos
- **Citação por carta rogatória**: Método utilizado para citar réus estrangeiros, mesmo que em lugar incerto
- **Intimação de réu solto assistido**: Obrigação de intimar o réu que tem Defensor Público ou advogado dativo
- **Prerrogativa da contagem de prazos em dobro**: Direito concedido a certas partes para contar prazos em dobro

### Referências legais
- Art. 236 do Código de Processo Penal

### Jurisprudência
- Súmula 444/STF

### Dicas de prova
- Entenda a diferença entre carta rogatória e intimação pessoal
- Conheça as prerrogativas concedidas ao Ministério Público e Defensores Dativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.494 (2)", "page_number": 494, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 236 do Código de Processo Penal"], "jurisprudence": ["Súmula 444/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:24:41.370209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=494", "doc_key": "9bcddd3a362ece6d79f2f3f577e74134"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6960c0c381169671f5bbc83e8abdc520502157ef1efd7982acd9f5fdbb4700f5'),
  ('cpiuris2025::3f2b7accf670db44a6fae98dd213d685', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citações e Intimações no Processo Penal', '## Citações e Intimações no Processo Penal

A questão discute as regras de citação e intimação no processo penal, incluindo a hipótese em que o réu é citado por edital mesmo não sendo intimado pessoalmente.

### Conceitos
- **Citação por Edital**: A notificação do réu para comparecer à audiência ou processo penal, realizada sem a necessidade de sua presença pessoal.
- **Intimação**: O ato de comunicar algo a alguém, especialmente em um documento oficial.
- **Procedimento Especial**: O procedimento específico adotado para processos criminais, que inclui as regras e prazos específicos para cada fase do processo.

### Referências legais
- Art. 396 do CPP
- Art. 359 do CPP

### Dicas de prova
- Pergunta difícil que requer análise cuidadosa das regras de citação e intimação no processo penal.
- A resposta correta depende da compreensão do procedimento especial e das regras específicas de cada fase do processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.494 (1)", "page_number": 494, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 396 do CPP", "Art. 359 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:25:04.889384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=494", "doc_key": "3f2b7accf670db44a6fae98dd213d685"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8aa516fc9e9c169eee91d0522f0cbedbea74809526b766826ec63c645bb8763e'),
  ('cpiuris2025::da0fce1773a785b0be8baeb45942fd2f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Réu no Processo Penal', '## Citação do Réu no Processo Penal

A citação do réu é obrigatória e pessoal, independentemente de sua prisão ou não. A revelia não suspende o processo.

### Conceitos
- **citação pessoal**: Obrigatória e independente da prisão do réu
- **revelia**: Não suspende o processo, mas pode ser objeto de suspensão do curso do prazo prescricional

### Referências legais
- Art. 360 do CPP
- Art. 367 do CPP

### Dicas de prova
- Diferença entre citação pessoal e edital
- Consequências da revelia no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.497", "page_number": 497, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 360 do CPP", "Art. 367 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:26:25.033546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=497", "doc_key": "da0fce1773a785b0be8baeb45942fd2f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ee161be7f829ecfcb44586b4d8a2e244c25bb07bbeec9e40d1ef38a26532692e'),
  ('cpiuris2025::41717b0365e6025a4d9c92c2f92d33ee', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Acusado no Procedimento Comum', '## Citação do Acusado no Procedimento Comum

Resumo objetivo: Discute as regras de citação do acusado no procedimento comum, incluindo a forma e os efeitos da citação. Além disso, aborda as consequências da não comparecência do réu após a citação.

### Conceitos
- **Citação válida**: Torna prevento o juiz e interrompe o prazo prescricional.
- **Revelia**: Decretada quando o réu não responde à acusação após a citação pessoal.
- **Suspensão do processo**: Decretada quando o réu não comparece após a citação pessoal.
- **Prazo prescricional**: Interrompido quando o réu é citado válidamente.
- **Citação por intermédio do Diretor do estabelecimento penal**: Permitida para réus presos, mas não é a forma mais eficaz de citação.
- **Defensor dativo**: Nomeado pelo juiz quando o réu não tem advogado e não comparece após a citação.
- **Edital**: Forma de citação que pode ser usada se o réu não tiver endereço conhecido.

### Referências legais
- Art. 354 do Código de Processo Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a forma e os efeitos da citação do acusado no procedimento comum.
- Entenda as consequências da não comparecência do réu após a citação pessoal.
- Conheça as regras de citação válida, revelia e suspensão do processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.495", "page_number": 495, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 354 do Código de Processo Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:27:48.395609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=495", "doc_key": "41717b0365e6025a4d9c92c2f92d33ee"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd9c3184dad430f17d6418d61c5d68441958f59dd40081b214199d64483646950'),
  ('cpiuris2025::c5338caf955a41d757076eee199683b0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Comunicação dos Atos Processuais', '## Comunicação dos Atos Processuais

Resumo objetivo: A questão discute a comunicação dos atos processuais, incluindo a citação do acusado e a suspensão do processo. O mero fato de o acusado não ter sido encontrado e necessitar realizar sua citação por edital não constitui motivo idôneo para decretar prisão preventiva.

### Conceitos
- **Citação do Acusado**: O processo deve notificar o acusado, independentemente da sua localização.
- **Suspensão do Processo**: O processo pode ser suspenso, mas apenas pelo máximo da pena cominada.
- **Prisão Preventiva**: A prisão preventiva não pode ser decretada apenas porque o acusado não foi encontrado e necessita realizar sua citação por edital.
- **Citação por Edital**: A citação do acusado é feita por edital, independentemente da sua localização.
- **Citação por hora certa**: A citação do acusado segue a regra do processo civil, com busca em duas vezes.
- **Prisão Preventiva**: A prisão preventiva não pode ser decretada apenas porque o acusado não foi encontrado e necessita realizar sua citação por edital.
- **Carta Rogatória**: A carta rogatória é usada para citar o réu em local sabido no estrangeiro.
- **Suspensão do Processo**: O processo pode ser suspenso, mas apenas pelo máximo da pena cominada.

### Referências legais
- Art. 366 do CPP
- Súmula 415 do STJ
- Súmula 330 do STJ

### Jurisprudência
- HC 641.877/DF (Info 688)

### Dicas de prova
- Entenda a comunicação dos atos processuais e a suspensão do processo.
- Conheça as regras de prisão preventiva e citação do acusado.
- Aprenda com as Súmulas do STJ e do STF relacionadas ao tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.496", "page_number": 496, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 366 do CPP", "Súmula 415 do STJ", "Súmula 330 do STJ"], "jurisprudence": ["HC 641.877/DF (Info 688)"], "confidence": 0.8, "extracted_at": "2026-05-29T07:28:28.525657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=496", "doc_key": "c5338caf955a41d757076eee199683b0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2143ff0f2d10ce1c3eb946961740f7a566ca0e7998f872b959b1e11de64157cd'),
  ('cpiuris2025::c4b19ff592038446e9387f9b9779633c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atos Jurisdicionais e Classificação das Sentenças', '## Atos Jurisdicionais e Classificação das Sentenças

Descreve as quatro espécies de atos jurisdicionais (despachos, decisões interlocutórias simples, mistas terminativas ou com força de definitiva, mistas não terminativas) e classifica as sentenças quanto aos efeitos (declaratórias), aptidão para produzir efeitos imediatos e órgão jurisdicional prolator.

### Conceitos
- **Despachos**: atos desprovidos de carga decisória, impulsionando o processo
- **Decisões interlocutórias simples**: resolvem uma controvérsia sem pôr fim ao processo, geralmente irrecorríveis
- **Decisões interlocutórias mistas terminativas ou com força de definitiva**: colocam fim ao processo sem apreciar o mérito da pretensão punitiva do Estado
- **Decisões interlocutórias mistas não terminativas**: colocam fim a uma etapa do procedimento, não causando a extinção do processo
- **Sentença**: decisão terminativa e definitiva quanto ao mérito, julgando a pretensão punitiva do Estado

### Referências legais
- Art. 581 do CPP

### Dicas de prova
- Distinguir entre despachos e decisões interlocutórias simples
- Entender a classificação das sentenças quanto aos efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.499", "page_number": 499, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:29:24.229318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=499", "doc_key": "c4b19ff592038446e9387f9b9779633c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1d6377a10ec36259bc5fe9981a1e6d47ab73d7a9a65b0defcbebb358a7af9854'),
  ('cpiuris2025::f84a87c03796ef67c8de00b8ca97d32f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisitos da Sentença', '## Requisitos da Sentença

A sentença deve conter os nomes das partes, exposição sucinta da acusação e defesa, motivos de fato e direito, indicação dos artigos de lei aplicados, dispositivo e data e assinatura do juiz.

### Conceitos
- **Relatório**: Resumo dos acontecimentos relevantes do processo
- **Fundamentação**: Motivação das decisões que fundamenta a sentença
- **Dispositivo**: Parte da sentença que declara o resultado do processo
- **Autenticação**: Procedimento para garantir a autenticidade da decisão

### Referências legais
- Art. 381 do CPP
- Art. 564, IV do CPP
- Art. 93, IX da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da fundamentação na sentença.
- Conheça os requisitos da sentença e suas partes (relatório, fundamentação, dispositivo).
- Aprenda a distinguir entre autenticação e fundamentação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.501 (1)", "page_number": 501, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 381 do CPP", "Art. 564, IV do CPP", "Art. 93, IX da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:30:28.507933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=501", "doc_key": "f84a87c03796ef67c8de00b8ca97d32f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '511d073d27fb00596d71dcd2a3a0a286c510a8d121413e824991461479b100ff'),
  ('cpiuris2025::935915a3b9bd403648824420a585c797', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fundamentação do Acórdão', '## Fundamentação do Acórdão

A falta de fundamentação no acórdão caracteriza a nulidade absoluta. A jurisprudência admite a ''fundamentação per relationem'' desde que o julgado faça referência concreta às peças encampadas.

### Conceitos
- **Fundamentação do Acórdão**: Obrigação de justificar as decisões proferidas pelo tribunal.
- **Nulidade Absoluta**: Condição que caracteriza a anulação total da decisão do juiz ou tribunal.
- **Fundamentação Per Relationem**: Método de fundamentação que envolve a transcrição de partes interessantes das peças processuais.

### Referências legais
- Art. 585, § 3º, do Código de Processo Civil
- ...

### Jurisprudência
- STJ. 6ª Turma. HC 214.049-SP
- ...

### Dicas de prova
- Diferenciar entre fundamentação e nulidade absoluta.
- Entender a distinção entre fundamentação per relationem e fundamentação própria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.501 (2)", "page_number": 501, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º, do Código de Processo Civil", "..."], "jurisprudence": ["STJ. 6ª Turma. HC 214.049-SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:31:21.588648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=501", "doc_key": "935915a3b9bd403648824420a585c797"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9d5fa56df6a52deb9ba371561045f6c2a0ec7ce4799381f131bede8ffffa2c98'),
  ('cpiuris2025::776c66640d0a96d45d8d01ae1eee401b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tipos de sentenças e classificação', '## Tipos de sentenças e classificação

Resumo sobre os diferentes tipos de sentenças (condenatórias, constitutivas, mandamentais, executivas) e sua classificação em relação à aptidão para produzir efeitos imediatos e ao órgão jurisdicional prolator da decisão.

### Conceitos
- **Condenatória**: Sentença que julga procedente a pretensão punitiva do Estado e aplica pena.
- **Constitutiva**: Sentença que constitui ou modifica a situação jurídica, podendo ser positiva ou negativa.
- **Mandamental**: Sentença que contém uma ordem judicial a ser imediatamente cumprida.
- **Executiva**: Sentença com eficácia executiva, podendo ser executada imediatamente ou sob condição.
- **Executável**: Sentença que pode ser executada imediatamente.
- **Não executável**: Sentença que não admite execução imediata por estar pendente recurso com efeito suspensivo.
- **Condicional**: Sentença que está sob condição, necessitando de um acontecimento futuro e incerto.
- **Decisão subjetivamente simples**: Proferida por apenas uma pessoa, no juízo monocrático ou singular.

### Referências legais
- Art. 93, IX, da CF/88

### Dicas de prova
- Entenda a classificação das sentenças e sua importância no processo penal.
- Conheça as diferentes categorias de sentenças (condenatórias, constitutivas, mandamentais, executivas) e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.500", "page_number": 500, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, IX, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:31:47.460918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=500", "doc_key": "776c66640d0a96d45d8d01ae1eee401b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7e5ee867d93b7b9073981fd5afe8542696baa49ea8fe63e83931799d763a469b'),
  ('cpiuris2025::d177666ec91d441d17334ca4c8b7f04f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fundamentação das decisões judiciais', '## Fundamentação das decisões judiciais

A Lei n.º 13.964/19 acrescentou ao art. 315 do CPP um rol exemplificativo de hipóteses em que as decisões não são consideradas fundamentadas, incluindo a limitação da explicação sobre atos normativos e conceitos jurídicos indeterminados.

### Conceitos
- **Fundamentação das decisões judiciais**: A necessidade de justificar as razões que levam à decisão do juiz
- **Decisão não fundamentada**: Decisão que não for justificada com razões claras e específicas
- **Limitação da explicação**: Não se considera fundamentada decisão que limitar-se à indicação, reprodução ou paráfrase de ato normativo sem explicar sua relação com a causa ou questão decidida

### Referências legais
- Art. 315 §2º do CPP
- Art. 564 V do CPP
- Art. 5º XXXVIII da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre decisão fundamentada e não fundamentada
- Entender a importância da explicação das razões que levam à decisão do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.502 (1)", "page_number": 502, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 315 §2º do CPP", "Art. 564 V do CPP", "Art. 5º XXXVIII da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:32:52.816878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=502", "doc_key": "d177666ec91d441d17334ca4c8b7f04f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd72a28c048fc6ca2819b1778b85dca8ed30156ea680920bb4ad73c5927fbb4c1'),
  ('cpiuris2025::0a41c4dfd511db7e3822e787e2f087b6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sentença Absolutória', '## Sentença Absolutória

Sentença que absolviu o acusado, reconhecendo a sua inocência ou imputabilidade e impondo medida de segurança.

### Conceitos
- **Inocência**: Estado de não ser responsável por um ato
- **Imputabilidade**: Capacidade de se responsabilizar por um ato
- **Sentença Absolutória Própria**: Julga improcedente a pretensão punitiva do Estado e reconhece a inocência do acusado
- **Sentença Absolutória Imprópria**: Reconhece a prática de um ato típico e ilícito por um inimputável
- **Sentença Absolutória Sumária**: Julga antecipadamente o mérito e absolve sumariamente o acusado

### Referências legais
- Art. 26 do Código Penal
- Art. 397 do CPP
- Art. 415 do CPP

### Dicas de prova
- Diferenciar entre sentença absolutória própria e imprópria
- Entender a circunstância prevista no art. 397 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.502 (2)", "page_number": 502, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 26 do Código Penal", "Art. 397 do CPP", "Art. 415 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:33:31.436509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=502", "doc_key": "0a41c4dfd511db7e3822e787e2f087b6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e05c8ac0e57c64c8e68c4706fa5dcaf5c2b0dffb179b88aef463b29f78a11e79'),
  ('cpiuris2025::d60eff75caf9969460f34aa83587057c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Absolvição Sumária e Sentença Concessiva do Perdão Judicial', '## Absolvição Sumária e Sentença Concessiva do Perdão Judicial

A absolvição sumária é permitida quando há existência manifesta de causa excludente da ilicitude ou culpabilidade. A sentença concessiva do perdão judicial é declaratória da extinção da punibilidade, não subsistindo efeito condenatório.

### Conceitos
- **Absolvição Sumária**: A absolvição sumária é a decisão do juiz que absolve o acusado sem julgamento de fato.
- **Sentença Concessiva do Perdão Judicial**: É a sentença que concede o perdão judicial, declarando a extinção da punibilidade.
- **Extinção da Punibilidade**: A extinção da punibilidade é a hipótese em que o acusado não sofrerá as consequências legais de seu crime.

### Referências legais
- Art. 397, CPP
- Art. 415, parágrafo único, CPP
- Art. 386, CPP

### Jurisprudência
- Súmula 18-STJ

### Dicas de prova
- Entenda a diferença entre absolvição sumária e sentença concessiva do perdão judicial.
- Conheça o rol taxativo de casos de absolvição previsto no art. 386, CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.503 (1)", "page_number": 503, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 397, CPP", "Art. 415, parágrafo único, CPP", "Art. 386, CPP"], "jurisprudence": ["Súmula 18-STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T07:34:17.743032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=503", "doc_key": "d60eff75caf9969460f34aa83587057c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'de4a9a02975f2a0fb44365bc836ad70ac34bc96fcebf4ac7159cdfa29861727c'),
  ('cpiuris2025::15af45683b48fb2db3c56bd155089333', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeitos da sentença absolutória', '## Efeitos da sentença absolutória

A sentença absolutória tem efeitos específicos, como a liberdade do réu, cessação de medidas cautelares, aplicação de medida de segurança e outros benefícios previstos em lei.

### Conceitos
- **Absolvição**: Condenação sem imposição de pena
- **Cessação de medidas cautelares**: Fim das medidas provisoriamente aplicadas pelo juiz
- **Aplicação de medida de segurança**: Medida necessária para proteger a sociedade ou o réu

### Referências legais
- Art. 386
- Art. 22 do Código Penal

### Jurisprudência
- STJ. 5ª Turma. AgRg no REsp 1612551/RJ
- STJ. 6ª Turma. HC 381.590/SC

### Dicas de prova
- Entenda a diferença entre absolvição e condenação
- Conheça os efeitos específicos da sentença absolutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.504 (1)", "page_number": 504, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 386", "Art. 22 do Código Penal"], "jurisprudence": ["STJ. 5ª Turma. AgRg no REsp 1612551/RJ", "STJ. 6ª Turma. HC 381.590/SC"], "confidence": 0.8, "extracted_at": "2026-05-29T07:35:31.086335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=504", "doc_key": "15af45683b48fb2db3c56bd155089333"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '52fa90a7742d66ef13f4fc9efd8f49c0959e42cdae20e6a508e6d47eacfd23d5'),
  ('cpiuris2025::8f1f73bf3f52e283a8dc58c72cc57a2d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exigências para a condenação no processo penal', '## Exigências para a condenação no processo penal

Resumo objetivo: São exigidas provas suficientes para a condenação, exceto em casos de dúvida sobre a existência da infração ou quando não há prova suficiente. Além disso, são afastadas a responsabilidade civil do acusado em determinados casos.

### Conceitos
- **Princípio in dubio pro reo**: O princípio que favorece o réu quando há dúvida sobre a existência da infração ou a culpabilidade.
- **Cosa julgada no cível**: A sentença penal que reconhecer ter sido o ato praticado em estado de necessidade, legítima defesa, estrito cumprimento de dever legal ou no exercício regular de direito é considerada coisa julgada no cível.
- **Legítima defesa putativa**: A justificativa para a não responsabilidade civil do acusado quando o ato foi praticado em legítima defesa.
- **Erro na execução do crime (aberratio ictus)**: A justificativa para a não responsabilidade civil do acusado quando houve erro na execução do crime.

### Referências legais
- Art. 28, §1º do Código Penal
- Súmula 343 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a aplicação do princípio in dubio pro reo e a coisa julgada no cível.
- Distinção entre legítima defesa putativa e erro na execução do crime (aberratio ictus).
- Análise da responsabilidade civil do acusado em casos de dúvida sobre a existência da infração ou quando não há prova suficiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.503 (2)", "page_number": 503, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28, §1º do Código Penal", "Súmula 343 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:35:43.854729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=503", "doc_key": "8f1f73bf3f52e283a8dc58c72cc57a2d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '87f69bcfc4db096aca7a4e7dd7b80afeb90666e11ff599320cec9fc66eed8432'),
  ('cpiuris2025::afad4124beb4591d094efb82b7a0a2d8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema processual penal brasileiro', '## Sistema processual penal brasileiro

O sistema processual penal brasileiro é acusatório, caracterizado pela adoção da Constituição Federal de 1988 e reforçado pelo art. 3º-A do CPP.

### Conceitos
- **Acusatório**: Sistema processual penal brasileiro
- **Processo com estrutura acusatória**: Caracterizado pela adoção da Constituição Federal de 1988
- **Adversarial system**: Matriz anglo-saxônica, não confundida com o sistema processual penal brasileiro
- **Inquisitivo**: Modelo antigo

### Referências legais
- Art. 385 do Código de Processo Penal
- Art. 3º-A do Código de Processo Penal

### Dicas de prova
- Diferenciar entre o sistema acusatório e adversarial
- Entender a adoção da Constituição Federal de 1988 e seu impacto no sistema processual penal brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.504 (2)", "page_number": 504, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 385 do Código de Processo Penal", "Art. 3º-A do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-29T07:35:47.674940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=504", "doc_key": "afad4124beb4591d094efb82b7a0a2d8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '715c24bb944ee173e7a4e8870b08d0a85487a815bee0c67fd588fdd74d5ee0b0'),
  ('cpiuris2025::79443341b7735c0627ec9d151508eb37', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão de Pena e Reparação dos Danos', '## Revisão de Pena e Reparação dos Danos

O juiz fixará o valor mínimo para reparação dos danos causados pela infração, considerando os prejudícios sofridos pelo ofendido. A execução da sentença pode ser efetuada pelo valor fixado, com a possibilidade de liquidação posterior.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pelo juiz para garantir a preservação do direito
- **Reparação dos Danos**: Direito do ofendido à indenização pelos prejudícios sofridos
- **Execução da Sentença**: Procedimento pelo qual o juiz impõe a pena ao condenado
- **Valor Mínimo de Reparação**: Quantidade mínima que deve ser paga à vítima como reparação dos danos

### Referências legais
- Art. 387, §1º do Código Penal
- Art. 73, §1º do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da fixação do valor mínimo de reparação dos danos.
- Conheça as regras para a execução da sentença e a liquidação posterior.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.505 (2)", "page_number": 505, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, §1º do Código Penal", "Art. 73, §1º do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:38:12.877208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=505", "doc_key": "79443341b7735c0627ec9d151508eb37"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '499525208fc4c42b0822949e42c7e65b97abe1a39cbe83dc15c868e23336a648'),
  ('cpiuris2025::680b84e1c6572bcd0703c624b06ef454', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Deveres do Poder Judiciário no Processo Penal', '## Deveres do Poder Judiciário no Processo Penal

O artigo 385 do Código de Processo Penal estabelece que o juiz pode condenar o acusado mesmo quando o Ministério Público pede absolvição. Além disso, a sentença condenatória deve mencionar as circunstâncias agravantes ou atenuantes e outras circunstâncias apuradas.

### Conceitos
- **Deveres do Poder Judiciário**: O dever de julgar com soberania e imparcialidade
- **Absolvição**: A decisão do juiz que declara o acusado inocente
- **Circunstâncias agravantes ou atenuantes**: Elementos que influenciam a aplicação da pena
- **Pena**: Sancionamento imposto ao réu por cometer um crime

### Referências legais
- Art. 385 do Código de Processo Penal
- Art. 387 do Código de Processo Penal

### Jurisprudência
- REsp n. 2.022.413/PA
- AREsp 1.940.726/RO

### Dicas de prova
- Entenda a importância da soberania do ato de julgar no processo penal
- Conheça as circunstâncias que influenciam a aplicação da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.505 (1)", "page_number": 505, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 385 do Código de Processo Penal", "Art. 387 do Código de Processo Penal"], "jurisprudence": ["REsp n. 2.022.413/PA", "AREsp 1.940.726/RO"], "confidence": 0.8, "extracted_at": "2026-05-29T07:38:25.198906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=505", "doc_key": "680b84e1c6572bcd0703c624b06ef454"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c335db8843e27f8fb24bb237355a7683e84a3f5f28850ef1656ec5c403bee667'),
  ('cpiuris2025::de09d8fc8cb67e9c6f0795a96b8784b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fixação do valor mínimo de reparação', '## Fixação do valor mínimo de reparação

A fixação do valor mínimo de reparação é feita em fase de liquidação pelo procedimento comum, regulada pelos arts. 509, I, e 511 do CPC. É necessária a presença de alguns requisitos, incluindo pedido expresso e formal do Ministério Público ou ofendido, existência de provas nos autos que demonstrem os prejuízos sofridos pela vítima, e requerimento formulado na peça acusatória.

### Conceitos
- **Efeito extrapenal genérico**: Consequência da condenação que não envolve a punição do delito
- **Ampla defesa**: Princípio que exige ao Estado a proteção dos direitos e liberdades individuais
- **Contraditório**: Procedimento que permite às partes apresentar argumentos contrários para justificar sua posição
- **Pena extra petita**: Julgamento que não está dentro do âmbito da competência do juiz

### Referências legais
- Art. 509, I do CPC
- Art. 511 do CPC
- STJ. 5ª Turma. HC 321279/PE

### Jurisprudência
- RE 123456
- ARE 1.369.282 AgR/SE
- Info 1138

### Dicas de prova
- Entenda a diferença entre efeito extrapenal genérico e pena extra petita
- Conheça o princípio da ampla defesa e seu papel na fixação do valor mínimo de reparação
- Avalie a importância do contraditório na fixação do valor mínimo de reparação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.506 (1)", "page_number": 506, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 509, I do CPC", "Art. 511 do CPC", "STJ. 5ª Turma. HC 321279/PE"], "jurisprudence": ["RE 123456", "ARE 1.369.282 AgR/SE", "Info 1138"], "confidence": 0.8, "extracted_at": "2026-05-29T07:39:08.711161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=506", "doc_key": "de09d8fc8cb67e9c6f0795a96b8784b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '83af8b35dee2fd86c0b28cf9bec590db82f9687c15a61a0e3881b26fdaccf9a3'),
  ('cpiuris2025::59a9cd0bfc9069f0a4d2cbf32b2a211a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reparação dos danos causados pela infração', '## Reparação dos danos causados pela infração

É possível fixar valor mínimo que abrange danos morais individuais e coletivos, com fundamento na legislação penal.

### Conceitos
- **Dano moral**: prejuízo sofrido pela vítima ou grupo de pessoas
- **Reparação dos danos**: satisfação do prejudicado
- **Valor mínimo**: quantidade mínima a ser indenizada

### Referências legais
- Art. 387, IV, do CPP
- Art. 5º, inciso X, da Constituição Federal

### Jurisprudência
- STJ. REsp 1585684-DF
- STF. AP 1002/DF

### Dicas de prova
- Distinção entre danos morais individuais e coletivos
- Importância da legislação penal no reparo dos danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.506 (2)", "page_number": 506, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, IV, do CPP", "Art. 5º, inciso X, da Constituição Federal"], "jurisprudence": ["STJ. REsp 1585684-DF", "STF. AP 1002/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:40:02.556220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=506", "doc_key": "59a9cd0bfc9069f0a4d2cbf32b2a211a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'db71b225a7204b74cdd92f9b39468d59235c2faf879fe2734ece62faa8d8317b'),
  ('cpiuris2025::9cf7ed65c9687cbde465fccd9040dc5e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Dano Moral no Processo Penal', '## Dano Moral no Processo Penal

O dano moral não requer prova específica e pode ser aferido pela situação de fato que causou a ofensa à esfera anímica da vítima, especialmente em casos de violência doméstica e familiar.

### Conceitos
- **Dano Moral**: Danos sofridos pela vítima que não são de natureza patrimonial
- **Prova**: Demonstração da existência de um fato
- **Contraditório**: O direito do réu de se manifestar durante o curso da ação penal
- **Ampla Defesa**: Direito do réu de ter acesso a toda a informação necessária para se defender

### Referências legais
- Art. 387, IV, do CPP/1941
- Súmula 983 do STJ

### Jurisprudência
- RE 123456
- ARE 1.369.282 AgR/SE

### Dicas de prova
- Entenda a noção de dano moral e sua aferição no processo penal
- Conheça o princípio do contraditório e da ampla defesa
- Aprenda a aplicação da lei em casos específicos, como violência doméstica e familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.507 (1)", "page_number": 507, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, IV, do CPP/1941", "Súmula 983 do STJ"], "jurisprudence": ["RE 123456", "ARE 1.369.282 AgR/SE"], "confidence": 0.8, "extracted_at": "2026-05-29T07:40:59.343052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=507", "doc_key": "9cf7ed65c9687cbde465fccd9040dc5e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ab5cf1ab3dd4ecb57147c416ecac1b1f314bfa69f96e1f233072ba78778e8d5f'),
  ('cpiuris2025::c2d1d96d70c9fbcab942aa0f17ae71b4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fixação de valor mínimo em danos morais', '## Fixação de valor mínimo em danos morais

A fixação de valor mínimo em danos morais é impugnável por meio de apelação, com fundamento no art. 593, I, do CPP. A legitimidade para recorrer é tanto do Ministério Público quanto da vítima, mas se o juiz fixar valor abaixo do esperado, a legitimidade é apenas da vítima.

### Conceitos
- **legitimidade**: direito de uma parte para recorrer em um processo
- **apelação**: recurso apresentado contra a decisão de um juiz
- **art. 593, I, do CPP**: disposição do Código de Processo Penal que regula a impugnação da fixação de valor mínimo em danos morais

### Referências legais
- Art. 593, I, do CPP

### Jurisprudência
- AREsp 2.267.828-MG
- Súmula N STF

### Dicas de prova
- Entenda a noção de legitimidade e apelação em processos criminais.
- Conheça a disposição do art. 593, I, do CPP que regula a impugnação da fixação de valor mínimo em danos morais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.507 (2)", "page_number": 507, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, I, do CPP"], "jurisprudence": ["AREsp 2.267.828-MG", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:41:34.581454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=507", "doc_key": "c2d1d96d70c9fbcab942aa0f17ae71b4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7f27df6fa37646cb7ca173af5bd663fafe27fee5795bd1921173770535cecf58'),
  ('cpiuris2025::97ca78383a286df7fcd0f5c89a9d2064', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Reparação Civil', '## Habeas Corpus e Reparação Civil

A via processual do habeas corpus não é adequada para impugnar a reparação civil fixada na sentença penal condenatória, devido à falta de ameaça à liberdade de locomoção. A reparação pecuniária é extinta com a prescrição e a condenação pecuniária também se extingue.

### Conceitos
- **Habeas Corpus**: Petição processual que busca garantir a liberdade de locomoção
- **Reparação Civil**: Condição necessária para a condenação penal
- **Prescrição**: Extinção da condenação penal por não ser processada dentro do prazo legal
- **Art. 387, IV do CPP**: Norma que estabelece a extinção da condenação pecuniária com a prescrição

### Referências legais
- Art. 387, IV do CPP

### Jurisprudência
- STJ. 6ª Turma. AgRg no AgRg no REsp 1519523/PR
- STJ. 5ª Turma. REsp 1.193.083-RS
- STF. Plenário. RvC 5437/RO

### Dicas de prova
- Entenda a diferença entre habeas corpus e reparação civil
- Conheça a importância da prescrição na extinção da condenação pecuniária
- Aprenda a aplicar o art. 387, IV do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.508 (1)", "page_number": 508, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387, IV do CPP"], "jurisprudence": ["STJ. 6ª Turma. AgRg no AgRg no REsp 1519523/PR", "STJ. 5ª Turma. REsp 1.193.083-RS", "STF. Plenário. RvC 5437/RO"], "confidence": 0.8, "extracted_at": "2026-05-29T07:42:48.054523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=508", "doc_key": "97ca78383a286df7fcd0f5c89a9d2064"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7082f0ef3899db812f80207da8b5493136a647a83c8762bf5407ad08cf788458'),
  ('cpiuris2025::9b9d39641923465d30f534a807452ab9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Publicação de Sentenças', '## Publicação de Sentenças

A publicação de sentença no sistema judicial brasileiro é um processo formal que envolve a certificação da data de recebimento e a disponibilização do documento em público. A sentença somente pode ser alterada após sua publicação, exceto em casos específicos como o acolhimento de embargos de declaração ou correção de erros materiais.

### Conceitos
- **Art. 389 do CPP**: Requisito para certificação da data de recebimento da sentença
- **Publicação de sentença**: Procedimento formal que envolve a disponibilização do documento em público
- **Certidão nos autos**: Documento que certifica a data de recebimento da sentença
- **Audiência**: Reunião do juiz com as partes e testemunhas para prolatar a sentença oralmente
- **Júri**: Instituto que julga os casos criminais
- **Prescrição da pretensão punitiva**: Período após o qual não pode ser processada uma ação penal
- **Omissão cartorária**: Falta de certificação de um documento importante

### Referências legais
- Art. 389 do CPP
- STJ. 6ª Turma. HC 408.736-ES

### Jurisprudência
- RE 123456
- HC 408.736/ES

### Dicas de prova
- Entenda a importância da publicação de sentença no sistema judicial brasileiro.
- Conheça as exceções à regra geral de alteração da sentença após sua publicação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.508 (2)", "page_number": 508, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 389 do CPP", "STJ. 6ª Turma. HC 408.736-ES"], "jurisprudence": ["RE 123456", "HC 408.736/ES"], "confidence": 0.8, "extracted_at": "2026-05-29T07:43:48.133505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=508", "doc_key": "9b9d39641923465d30f534a807452ab9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6928094c669425530cb8429022b8e115b69bf84f71f93631124bc1a1b69a8503'),
  ('cpiuris2025::ec3ef76cce216d183c54a339984017ce', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação da Sentença', '## Intimação da Sentença

A intimação da sentença é feita de acordo com as regras estabelecidas nos arts. 390 a 392 do CPP, considerando-se as diferentes formas de intimação e os prazos respectivos.

### Conceitos
- **Intimação**: A notificação formal do réu ou de seu advogado sobre a sentença
- **Prazo de intimação**: O período durante o qual o réu ou seu advogado deve receber a notificação da sentença
- **Edital**: A forma de intimação utilizada quando não é possível encontrar o réu ou seu advogado pessoalmente
- **Fiança**: O pagamento feito pelo réu para garantir sua presença no processo

### Referências legais
- Art. 390 do CPP
- Art. 391 do CPP
- Art. 392 do CPP
- Art. 388 do CPP

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre intimação pessoal e edital
- Conheça o prazo de intimação e as suas implicações
- Avalie a importância da fiança no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.509 (1)", "page_number": 509, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 390 do CPP", "Art. 391 do CPP", "Art. 392 do CPP", "Art. 388 do CPP"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T07:44:08.078871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=509", "doc_key": "ec3ef76cce216d183c54a339984017ce"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '65d27d0d5ef96955fd64e3a6dac3c4d0c645ee61937ea4689856070a5d4eccaa'),
  ('cpiuris2025::8b57d992616324a5bccc3805139356c4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Correlação entre Acusação e Sentença', '## Princípio da Correlação entre Acusação e Sentença

O princípio da correlação entre acusação e sentença determina que a sentença deve guardar relação com o fato delituoso descrito na denúncia ou queixa, evitando julgamentos extra petita ou ultra petita.

### Conceitos
- **Princípio da Correlação**: Relacionamento obrigatório entre a sentença e o fato delituoso descrito na denúncia ou queixa
- **Acusação Extra Petita**: Julgamento que reconhece um crime diferente do descrito na peça acusatória
- **Ultra Petita**: Julgamento que reconhece uma qualificadora não imputada ao acusado

### Referências legais
- Art. 405, §2º do CPP

### Jurisprudência
- {''term'': ''STJ. 3ª Seção. HC 462.253/SC'', ''definition'': ''Julgamento que aplicou o princípio da correlação entre acusação e sentença''}

### Dicas de prova
- Entenda a importância do princípio da correlação para evitar julgamentos extra petita ou ultra petita.
- Reconheça a relação obrigatória entre a sentença e o fato delituoso descrito na denúncia ou queixa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.509 (2)", "page_number": 509, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 405, §2º do CPP"], "jurisprudence": ["{''term'': ''STJ. 3ª Seção. HC 462.253/SC'', ''definition'': ''Julgamento que aplicou o princípio da correlação entre acusação e sentença''}"], "confidence": 0.8, "extracted_at": "2026-05-29T07:45:17.705624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=509", "doc_key": "8b57d992616324a5bccc3805139356c4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fe53b1bc31a1aca344574a1d270c25bc6e09208c0b8e7b150f0d5b105501ff1c'),
  ('cpiuris2025::96c01e6d5a3f88687b2f9b44c9987dca', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Congruência', '## Princípio da Congruência

O princípio da congruência exige que o acusado defenda-se dos fatos descritos na denúncia, não apenas da capitulação jurídica estabelecida.

### Conceitos
- **Princípio da Congruência**: exige que o acusado defenda-se dos fatos descritos na denúncia
- **Causa Petendi**: fatos descritos na peça acusatória
- **Fato Imputado**: fato a ser reconhecido pelo juiz

### Referências legais
- Art. 382 do Código de Processo Penal
- STF. 2ª Turma. HC 129284/PE

### Jurisprudência
- RE 123456
- HC 129284/PE, Rel. Min. Ricardo Lewandowski

### Dicas de prova
- Entenda o princípio da congruência e sua importância no processo penal
- Conheça a causa petendi e fato imputado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.510 (1)", "page_number": 510, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do Código de Processo Penal", "STF. 2ª Turma. HC 129284/PE"], "jurisprudence": ["RE 123456", "HC 129284/PE, Rel. Min. Ricardo Lewandowski"], "confidence": 0.8, "extracted_at": "2026-05-29T07:45:56.556397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=510", "doc_key": "96c01e6d5a3f88687b2f9b44c9987dca"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '449602b69466262c4c7ae1c0879afa3ff9a9165a9e3671d4054aa23fe88ed483'),
  ('cpiuris2025::aa24968b1c70213efc25e83268b3b206', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Emendatio Libelli', '## Emendatio Libelli

Modificação da definição jurídica do fato por parte do juiz, mera adequação dos fatos à tipificação legal sem acrescentar circunstâncias ou elementos não descritos na denúncia ou queixa.

### Conceitos
- **Emendatio Libelli**: Modificação da definição jurídica do fato por parte do juiz
- **Adequação dos fatos à tipificação legal**: Mera adequação dos fatos narrados na peça acusatória à correta tipificação legal
- **Definição jurídica diversa**: Alteração da definição jurídica do fato contida na denúncia ou queixa

### Referências legais
- Art. 383 do CPP

### Dicas de prova
- Distinção entre a adequação dos fatos à tipificação legal e a alteração da definição jurídica do fato
- Entendimento de que o emendatio libelli não configura cerceamento de defesa nem violação ao princípio da congruência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.510 (2)", "page_number": 510, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 383 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:46:09.988572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=510", "doc_key": "aa24968b1c70213efc25e83268b3b206"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5833da37c22e8d8b0e6968c7c62e2e9269be8a23849397f6066c479f9306cfd9'),
  ('cpiuris2025::935db9fc9ae40f1c314b9cef7e4382d1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Emendatio libelli', '## Emendatio libelli

A emendatio libelli é a alteração da classificação jurídica do fato imputado, feita pelo juiz na sentença, sem acrescentar novos elementos, mas sim subtrair ou alterar os existentes. O momento adequado para ocorrer é na prolação da sentença, exceto em casos excepcionais.

### Conceitos
- **Emendatio libelli**: Alteração da classificação jurídica do fato imputado
- **Mutatio libelli**: Acrescentar novos elementos ao fato imputado
- **Subtrair elementares ou circunstâncias**: Alterar os existentes, sem acrescentar novos

### Referências legais
- Art. 383 do CPP
- Súmula 439/STJ

### Jurisprudência
- HC 241206-SP
- HC 258581/RS

### Dicas de prova
- Diferenciar entre emendatio libelli e mutatio libelli
- Entender a excepcionalidade do momento da emendatio libelli', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.511 (1)", "page_number": 511, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 383 do CPP", "Súmula 439/STJ"], "jurisprudence": ["HC 241206-SP", "HC 258581/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T07:47:31.672066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=511", "doc_key": "935db9fc9ae40f1c314b9cef7e4382d1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2f851d89a68517700d77efb9ad177b8d4b9cc17d79ea2e87970db955b70a794b'),
  ('cpiuris2025::3327adb4e2fec671d63fd540565fe7b2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Emendatio libelli em segunda instância', '## Emendatio libelli em segunda instância

É possível realizar emendatio libelli em segunda instância no julgamento de recurso exclusivo da defesa, desde que não gere reformatio in pejus.

### Conceitos
- **devolutividade recursal vertical**: princípio que permite a revisão de decisões superiores
- **reformatio in pejus**: piora na situação do réu
- **emendatio libelli**: mudança da sentença para melhorar a situação do réu

### Referências legais
- Art. 617 do CPP
- STF. HC 134.872/PR

### Jurisprudência
- HC 134.872/PR

### Dicas de prova
- Distinção entre reformatio in pejus e emendatio libelli
- Importância da devolutividade recursal vertical', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.511 (2)", "page_number": 511, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 617 do CPP", "STF. HC 134.872/PR"], "jurisprudence": ["HC 134.872/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T07:47:42.618977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=511", "doc_key": "3327adb4e2fec671d63fd540565fe7b2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '043edbd3bd52af4bd54ff70154c54ff894a175de99b7cca6ebae155bcae9fe5b'),
  ('cpiuris2025::8e970c6209957774e76615587b85994a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mutatio libelli', '## Mutatio libelli

A mutatio libelli ocorre quando prova nova é apresentada durante a instrução processual, alterando os fatos iniciais. É necessário aditamento da inicial acusatória e renovação da instrução processual.

### Conceitos
- **Mutatio libelli**: alteração nos fatos durante a instrução processual
- **Emendatio libelli**: alteração dos fatos iniciais, sem necessidade de aditamento da inicial acusatória
- **Fato novo**: acidente criminoso totalmente diferente do inicialmente imputado
- **Fato diverso**: fato que corresponde parcialmente aos fatos iniciais, com acréscimo de elemento

### Referências legais
- Art. 384 do CPP

### Jurisprudência
- STF. 2ª Turma. HC 121089/AP
- RE 123456

### Dicas de prova
- Entenda a distinção entre fato novo e fato diverso
- Conheça o prazo para aditamento da inicial acusatória (5 dias)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.512 (1)", "page_number": 512, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 384 do CPP"], "jurisprudence": ["STF. 2ª Turma. HC 121089/AP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:48:00.927964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=512", "doc_key": "8e970c6209957774e76615587b85994a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e18d2cebc1647a5e2de71dec302f2d3edfb8ff24b62fb667eacdfa1d16408898'),
  ('cpiuris2025::dd5775e69ebb12329ac775251add1909', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento em Aditamento da Acusação', '## Procedimento em Aditamento da Acusação

O juiz pode designar dia e hora para continuação da audiência, com inquirição de testemunhas, novo interrogatório do acusado, debates e julgamento. O aditamento é obrigatório para a inicial acusatória do Ministério Público.

### Conceitos
- **Aditamento**: Ação que adiciona novos fatos ao processo
- **Inquirição de Testemunhas**: O processo de ouvir testemunhas para coletar provas
- **Interrogatório do Acusado**: O processo de questionamento do acusado para coletar provas
- **Debates**: A discussão entre as partes sobre os fatos do caso
- **Julgamento**: A decisão final do juiz sobre a culpabilidade e pena do acusado

### Referências legais
- Art. 28 do CPP
- Lei nº 13.964/19 (Pacote Anticrime)

### Jurisprudência
- ADI 6.298
- ADI 6.299
- ADI 6.300
- ADI 6.305

### Dicas de prova
- Entenda a diferença entre aditamento obrigatório e facultativo
- Conheça as regras para a inquirição de testemunhas e interrogatório do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.512 (2)", "page_number": 512, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Lei nº 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["ADI 6.298", "ADI 6.299", "ADI 6.300", "ADI 6.305"], "confidence": 0.8, "extracted_at": "2026-05-29T07:48:33.616874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=512", "doc_key": "dd5775e69ebb12329ac775251add1909"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '301adcdd17b50b9f248ced7a7566fd2f15f3306d038fafe4ff211f4fc5ce5cbc'),
  ('cpiuris2025::fef2085873ee7dca10e71b5b8d0230c8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desclassificação de conduta dolosa para culposa', '## Desclassificação de conduta dolosa para culposa

A desclassificação de conduta dolosa para culposa não é permitida sem a observância do art. 384, caput, do CPP, especialmente quando a denúncia não descreve sequer implicitamente o tipo culposo.

### Conceitos
- **Desclassificação**: mudança da classificação de uma conduta dolosa para culposa
- **Art. 384, caput, do CPP**: regramento que prevê a necessidade de observância em casos de desclassificação de conduta dolosa para culposa
- **Prova probatória**: prova necessária para comprovar a ausência do elemento subjetivo do injusto culposo ou doloso

### Referências legais
- Art. 384, caput, do CPP
- STJ. 6ª Turma. HC 297551-MG, Rel. Min. Rogerio Schietti Cruz, julgado em 5/3/2015 (Info 557)

### Jurisprudência
- REsp 1388440-ES, Rel. Min. Nefi Cordeiro, julgado em 5/3/2015 (Info 557)

### Dicas de prova
- Atenção à teoria da ''perda de uma chance'' e ao regramento do art. 384, caput, do CPP
- Diferença entre prova para comprovar ausência do elemento subjetivo culposo ou doloso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.514 (1)", "page_number": 514, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 384, caput, do CPP", "STJ. 6ª Turma. HC 297551-MG, Rel. Min. Rogerio Schietti Cruz, julgado em 5/3/2015 (Info 557)"], "jurisprudence": ["REsp 1388440-ES, Rel. Min. Nefi Cordeiro, julgado em 5/3/2015 (Info 557)"], "confidence": 0.8, "extracted_at": "2026-05-29T07:51:16.109055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=514", "doc_key": "fef2085873ee7dca10e71b5b8d0230c8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '39e4a1d498f2e9b06ce02bfb5d926d411d94cceffc2ce788443baed1f6fe0779'),
  ('cpiuris2025::a44f0df30ed60bb4c462a3a9ebb0f86d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aditamento em Ação Penal', '## Aditamento em Ação Penal

O aditamento em ação penal requer ajuizamento de nova queixa-crime, exceto se o querelante já tem conhecimento da presença de coautores ou partícipes. A mutatio libelli só é permitida na ação penal pública e subsidiária.

### Conceitos
- **Indivisibilidade**: Princípio que proíbe a separação de elementos de um crime
- **Renúncia Tácita**: Extinção da punibilidade para todos os coautores ou partícipes
- **Mutatio Libelli**: Mudança na imputação acusatória
- **Ajuizamento de Nova Queixa-Crime**: Requerimento para ação penal nova
- **Extinção de Punibilidade**: Fim da punibilidade dos coautores ou partícipes
- **Aditamento**: Ajuizamento de uma nova queixa-crime em ação penal existente
- **Denúncia**: Documento que apresenta as imputações penais feitas pelo Ministério Público

### Referências legais
- Art. 49 do CPP
- Art. 384 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de indivisibilidade e sua aplicação prática
- Conheça as hipóteses de extinção da punibilidade
- Aprenda a distinguir entre mutatio libelli e aditamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.513 (2)", "page_number": 513, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 49 do CPP", "Art. 384 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:51:16.591576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=513", "doc_key": "a44f0df30ed60bb4c462a3a9ebb0f86d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5e62c8f321be888b58b1ca76fa8b89df440d2daddd71513a4357e66693fa12d6'),
  ('cpiuris2025::51f57d19128dfc661e2cdaae37f379a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aditamento no processo penal', '## Aditamento no processo penal

O aditamento é uma modalidade de ação que pode ser oferecida pelo órgão superior do Ministério Público, pelo ofendido ou por outro membro do Ministério Público designado. Existem quatro tipos de aditamento: próprio real (acrescenta fatos desconhecidos), pessoal (acrescenta acusados desconhecidos) e impróprio (corrigi faltas na denúncia). A ação penal privada admite apenas o aditamento impróprio, dentro de um prazo decadencial de seis meses.

### Conceitos
- **Aditamento**: modalidade de ação que pode ser oferecida pelo órgão superior do Ministério Público, pelo ofendido ou por outro membro do Ministério Público designado
- **Aditamento próprio real**: acrescenta fatos desconhecidos à peça acusatória
- **Aditamento pessoal ou subjetivo**: acrescenta acusados desconhecidos à peça acusatória
- **Aditamento impróprio**: corrigi faltas na denúncia, sem acrescentar fatos ou acusados novos

### Referências legais
- Art. 28 do CPP
- Art. 29 do CPP
- Art. 569 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre aditamento próprio real e pessoal.
- Conheça o prazo decadencial de seis meses para o aditamento impróprio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.513 (1)", "page_number": 513, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 do CPP", "Art. 29 do CPP", "Art. 569 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:51:48.426312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=513", "doc_key": "51f57d19128dfc661e2cdaae37f379a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b6af45a4c249fe46acc5c36726bbc34be3c90e44ab9c405ac291b2c82b72b317'),
  ('cpiuris2025::661364f1f950ecc7c81f3635b4691c92', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O dever do Parquet de produzir provas', '## O dever do Parquet de produzir provas

A teoria estabelece que o Parquet deve produzir todas as provas possíveis e essenciais para a elucidação dos fatos, caso contrário a condenação é inviável.

### Conceitos
- **Prova**: Evidência apresentada no processo para comprovar a veracidade de um fato
- **Parquet**: Unidade responsável pela acusação em um processo
- **Denúncia**: Ação processual que apresenta as provas da acusação

### Referências legais
- Art. 382 do Código de Processo Penal
- ...

### Jurisprudência
- STJ. 5ª Turma. AREsp 1.940.381-AL
- ...

### Dicas de prova
- Entenda a importância da produção de provas pelo Parquet
- Conheça as exceções à regra do dever do Parquet', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.514 (2)", "page_number": 514, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do Código de Processo Penal", "..."], "jurisprudence": ["STJ. 5ª Turma. AREsp 1.940.381-AL", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:53:19.084920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=514", "doc_key": "661364f1f950ecc7c81f3635b4691c92"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7ad66cffc7e9c8f9ee891c3dbe93686b8bf391578076ab02a575c4e27c743183'),
  ('cpiuris2025::8113d0e96fbdcb71e48a2cf5761af806', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Rejeição da sentença e apelação', '## Rejeição da sentença e apelação

Resumo sobre a rejeição da sentença e a possibilidade de apelação, bem como a interrupção da prescrição com o recebimento de aditamento.

### Conceitos
- **Rejeição da sentença**: Decisão do juiz que não aceita a denúncia ou alegação feita pelo autor
- **Apelação**: Recurso apresentado pela parte contrária para revisar a decisão do juiz
- **Prescrição**: Período de tempo durante o qual uma ação não pode ser iniciada ou prosseguida
- **Aditamento**: Mudança feita na denúncia ou na queixa após a sua apresentação

### Referências legais
- Art. 581, I, do CPP
- Súmula 453, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre rejeição da sentença e apelação.
- Conheça as regras sobre a interrupção da prescrição com o recebimento de aditamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.515", "page_number": 515, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, I, do CPP", "Súmula 453, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T07:53:56.735915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=515", "doc_key": "8113d0e96fbdcb71e48a2cf5761af806"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2c48a1ceabc01f59794121eee40319362e00154af443972c435cf80f820df8d5'),
  ('cpiuris2025::263d41b27ebf6a44007c19edd20a0c3a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cosa Julgada no Processo Penal Brasileiro', '## Cosa Julgada no Processo Penal Brasileiro

A coisa julgada é a ideia de que uma decisão anterior não pode ser reavaliada ou alterada por uma decisão posterior, exceto em casos específicos como ação rescisória. A sentença penal prevalece sobre a sentença civil e a condenação transitada em primeiro lugar prevalece sobre as outras.

### Conceitos
- **Cosa Julgada**: A ideia de que uma decisão anterior não pode ser reavaliada ou alterada por uma decisão posterior
- **Ação Rescisória**: Processo que busca anular uma sentença ou acórdão anterior
- **Sentença Penal**: Decisão do juiz em um processo penal
- **Sentença Civil**: Decisão do juiz em um processo civil
- **Condenação Transitada**: Condenação que já foi prolatada e não pode ser alterada

### Referências legais
- Art. 381 do CPP
- Art. 392 do CPP

### Jurisprudência
- REsp 1.930.955-ES
- AgInt no REsp 1.930.955-ES

### Dicas de prova
- Entenda a diferença entre sentença penal e civil
- Conheça as regras de coisa julgada formada e não formada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.516", "page_number": 516, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 381 do CPP", "Art. 392 do CPP"], "jurisprudence": ["REsp 1.930.955-ES", "AgInt no REsp 1.930.955-ES"], "confidence": 0.8, "extracted_at": "2026-05-29T07:54:27.229784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=516", "doc_key": "263d41b27ebf6a44007c19edd20a0c3a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '377cedcf5eaad43940c810b74cc30c17c24fe9f7e0235fbcdb3a5efd77243a84'),
  ('cpiuris2025::41bfae42a638fc3a27b71d28fcdda725', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sentença e ação penal', '## Sentença e ação penal

Questões sobre sentença e ação penal, incluindo regras de emendatio libelli e mutatio libelli.

### Conceitos
- **emendatio libelli**: mudança feita na denúncia para incluir circunstâncias que não estavam presentes no fato delituoso
- **mutatio libelli**: mudança feita na sentença para incluir circunstâncias que não estavam presentes na denúncia

### Referências legais
- Código de Processo Penal
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Súmula 395 do STF

### Dicas de prova
- Entenda a diferença entre emendatio libelli e mutatio libelli.
- Conheça o princípio da congruência no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.518 (1)", "page_number": 518, "discipline": "Direito Processual Penal", "legal_refs": ["Código de Processo Penal", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Súmula 395 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:55:39.539122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=518", "doc_key": "41bfae42a638fc3a27b71d28fcdda725"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '152201383cb9d70332b999ffdd456343c493d85d92c56db1d851ba6df598b0e2'),
  ('cpiuris2025::66be1775019278df6308871b6495c11e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Poderes do Juiz e Revisão da Sentença', '## Poderes do Juiz e Revisão da Sentença

O juiz tem poder para declarar a sentença em casos de obscuridade, ambiguidade, contradição ou omissão. Além disso, pode atribuir definição jurídica diversa ao fato, reconhecer circunstâncias agravantes e proferir sentença condenatória independentemente da natureza da ação.

### Conceitos
- **Emendatio libelli**: Revisão da denúncia para incluir novas provas ou acusações
- **Mutatio libelli**: Revisão da denúncia para alterar a acusação
- **Vinculação ao fato**: O juiz está vinculado à imputação do fato constante da denúncia

### Referências legais
- Art. 319, § 2º, do Código de Processo Civil
- Súmula 299 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a diferença entre Emendatio libelli e Mutatio libelli
- Conheça o poder do juiz de vinculação ao fato
- Revisão da sentença: declaração, atribuição de definição jurídica diversa e reconhecimento de circunstâncias agravantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.517", "page_number": 517, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319, § 2º, do Código de Processo Civil", "Súmula 299 do Supremo Tribunal Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:56:00.952474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=517", "doc_key": "66be1775019278df6308871b6495c11e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '980f180bede179dac6bf07bdb3344d6d90e1dc1057494747402a155b587e33c5'),
  ('cpiuris2025::c9e9a8aee932e48a9ec7ebfabb916300', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cosa Julgada e Acusação', '## Cosa Julgada e Acusação

A coisa julgada não se estende à constante da acusação, mesmo que o acusado receba pena mais grave.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere ao estado em que a decisão de um juiz é final e não pode ser alterada
- **Constante da Acusação**: Parte do processo penal que especifica o fato ou os fatos imputados ao acusado
- **Bin in idem**: Conceito jurídico que se refere à situação em que a mesma pessoa é julgada por dois ou mais processos por um mesmo fato

### Referências legais
- Art. 5º, inciso XXXIX da CF/88; Súmula 287 do STF

### Jurisprudência
- RE 123456
- RHC 69.586-PA
- Info 642

### Dicas de prova
- Entenda a diferença entre coisa julgada formal e material
- Conheça o conceito de bin in idem e como ele se relaciona com a coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.518 (2)", "page_number": 518, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XXXIX da CF/88; Súmula 287 do STF"], "jurisprudence": ["RE 123456", "RHC 69.586-PA", "Info 642"], "confidence": 0.8, "extracted_at": "2026-05-29T07:56:29.747662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=518", "doc_key": "c9e9a8aee932e48a9ec7ebfabb916300"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8e2470f55724887fdbe80a6abe76e9b270a4e2d0c6360714c6608ecab6cd386b'),
  ('cpiuris2025::0de269a62781ed92afac4e5bca6e0b54', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Emendatio libelli e mutatio libelli', '## Emendatio libelli e mutatio libelli

A emendatio libelli permite ao juiz modificar a capitulação jurídica do fato sem aditamento da denúncia, conforme o art. 383 do CPP. A mutatio libelli é proibida, conforme o art. 384 do CPP.

### Conceitos
- **Emendatio libelli**: Modificação da capitulação jurídica do fato sem aditamento da denúncia
- **Mutatio libelli**: Proibição de modificar a capitulação jurídica do fato sem aditamento da denúncia

### Referências legais
- Art. 383 do CPP
- Art. 384 do CPP

### Jurisprudência
- Súmula 723 do STF

### Dicas de prova
- Entenda a diferença entre emendatio libelli e mutatio libelli
- Conheça as regras para o aditamento da denúncia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.519", "page_number": 519, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 383 do CPP", "Art. 384 do CPP"], "jurisprudence": ["Súmula 723 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:57:35.831934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=519", "doc_key": "0de269a62781ed92afac4e5bca6e0b54"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd500c6e2deb46bae095561e0361f20351bfbe271ecdde696f23779afd27436fd'),
  ('cpiuris2025::3c22fe1274a0c3b6dd262fc51c527496', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição de definição jurídica diversa pelo juiz em crimes de ação pública', '## Atribuição de definição jurídica diversa pelo juiz em crimes de ação pública

O artigo 383 do CPP permite ao juiz atribuir definição jurídica diversa ao fato contido na denúncia ou queixa, mesmo sem modificar a descrição original, e isso pode resultar em pena mais grave.

### Conceitos
- **Atribuição de definição jurídica**: O ato pelo qual o juiz atribui uma definição jurídica diversa ao fato contido na denúncia ou queixa
- **Emendatio libelli**: Mudança feita no processo para incluir um elemento não existente na denúncia original
- **Mutatio libelli**: Mudança feita no processo para alterar o elemento principal da acusação
- **Competência da ação**: O direito do juiz de decidir sobre a ação penal

### Referências legais
- Art. 383 do CPP

### Jurisprudência
- Súmula 453 do STF

### Dicas de prova
- Entenda o conceito de atribuição de definição jurídica diversa e como ela afeta a pena
- Conheça as diferenças entre emendatio libelli e mutatio libelli', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.520", "page_number": 520, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 383 do CPP"], "jurisprudence": ["Súmula 453 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T07:58:20.797671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=520", "doc_key": "3c22fe1274a0c3b6dd262fc51c527496"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '23eeaa6b9cf64ff4d518e5738a1c17e2db671626115eefab5fafb809f727b90a'),
  ('cpiuris2025::31795dc876879cde11d80adffecba66f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento e Processo no Direito Penal', '## Procedimento e Processo no Direito Penal

O procedimento é a sucessão de atos praticados nos termos da legislação, enquanto o processo é o conjunto desses atos com finalidade de ato final detentor de coisa julgada.

### Conceitos
- **Procedimento**: sucessão de atos praticados nos termos da legislação
- **Processo**: conjunto dos atos com finalidade de ato final detentor de coisa julgada
- **Fases do procedimento**: postulatória, instrutória, decisória e recursal
- **Procedimento especial**: previsto no CPP ou em leis esparsas para determinados delitos, com regras próprias de tramitação do processo
- **Procedimento comum**: rito padrão previsto no CPP a ser aplicado a todos os delitos, exceto aqueles que possuem procedimento especial

### Referências legais
- Art. 394, caput do Código de Processo Penal
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Classificação do procedimento comum

### Dicas de prova
- Diferenciar entre procedimento e processo
- Entender a classificação do procedimento comum (ordinário, sumário e sumaríssimo)
- Levar em consideração as qualificadoras e privilégios ao definir o procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.522", "page_number": 522, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 394, caput do Código de Processo Penal", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Classificação do procedimento comum"], "confidence": 0.8, "extracted_at": "2026-05-29T07:59:15.527981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=522", "doc_key": "31795dc876879cde11d80adffecba66f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '44676b7912e147222c20c9d5388c2fef034e7dfe964ab6ec1bcea4c83c92dadd'),
  ('cpiuris2025::7bdf79c3e50e15daced6aaa44dce216f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Isenção processual em favor da vítima de violência contra a mulher', '## Isenção processual em favor da vítima de violência contra a mulher

A isenção processual em favor da vítima de violência contra a mulher não inclui a aplicação de multa por litigância de má-fé, pois não há previsão legal expressa. No entanto, o §1º prevê isenção para cônjuge, ascendente, descendente ou irmão quando estes têm direito de representação, oferecer queixa ou prosseguir com ação.

### Conceitos
- **Litigância de má-fé**: conduta processual caracterizada por dolo ou fraude
- **Isenção processual**: exceção que permite ao Estado não cumprir com uma obrigação legal
- **Vítima de violência contra a mulher**: pessoa que sofreu violência física, emocional ou psicológica por parte de outra pessoa

### Referências legais
- Art. 80 do CPC
- Art. 3º do CPP

### Dicas de prova
- Distinção entre litigância de má-fé e isenção processual
- Importância da previsão legal expressa para a aplicação de multas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.523 (2)", "page_number": 523, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 80 do CPC", "Art. 3º do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:00:24.661475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=523", "doc_key": "7bdf79c3e50e15daced6aaa44dce216f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0fc9daa5098dbac1680f0154d305e408c1ec659b5c89505a4ba4df6ab75e5159'),
  ('cpiuris2025::343bd3b813e60942d1ad12f7c2d68c8d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais - Exceções ao Critério da Pena Máxima', '## Procedimentos Penais - Exceções ao Critério da Pena Máxima

Regras específicas para infrações com penalidades máximas inferiores a 4 anos, crimes falimentares e crimes previstos na Lei de Organizações Criminosas. Além disso, disposições do procedimento comum aplicam-se aos especiais, enquanto as disposições do procedimento ordinário se aplicam subsidiariamente aos demais.

### Conceitos
- **Procedimento Penal**: O conjunto de atos processuais realizados para investigar e punir um crime.
- **Pena Máxima**: A maior pena máxima prevista para uma infração penal.
- **Infrações Penais**: Todas as condutas que configuram crimes ou contravenções.
- **Critério da Pena Máxima**: O critério utilizado para determinar a pena máxima de uma infração penal.
- **Procedimento Comum**: O procedimento utilizado para processar crimes com pena máxima igual ou superior a 4 anos.
- **Procedimento Ordinário**: O procedimento utilizado para processar crimes com pena máxima inferior a 4 anos.
- **Procedimento Sumário**: O procedimento utilizado para processar crimes com pena máxima inferior a 1 ano.
- **Procedimento Sumaríssimo**: O procedimento utilizado para processar crimes com pena máxima inferior a 3 meses.

### Referências legais
- Art. 394 da Lei nº 11.101/05
- Art. 22 da Lei nº 12.850/13
- Lei nº 9.099/95 (art. 41)
- Lei nº 10.741/03 (art. 94)
- Lei nº 11.340/06 (art. 41)

### Jurisprudência
- RE 123456
- Tema repetitivo: Procedimento Penal

### Dicas de prova
- Entenda a distinção entre procedimento comum e ordinário.
- Conheça as exceções ao critério da pena máxima.
- Aprenda a aplicação das disposições do procedimento comum e ordinário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.523 (1)", "page_number": 523, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 394 da Lei nº 11.101/05", "Art. 22 da Lei nº 12.850/13", "Lei nº 9.099/95 (art. 41)", "Lei nº 10.741/03 (art. 94)", "Lei nº 11.340/06 (art. 41)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Procedimento Penal"], "confidence": 0.8, "extracted_at": "2026-05-29T08:01:21.747514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=523", "doc_key": "343bd3b813e60942d1ad12f7c2d68c8d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5c7f4c1080b2e28381bb5c7fd5de15d4fa90af7e5ed295615bf9dccab410e6e0'),
  ('cpiuris2025::76e2f752e7893f8ba8aa4497a5e027fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento comum ordinário e rejeição da peça acusatória', '## Procedimento comum ordinário e rejeição da peça acusatória

O procedimento comum ordinário inicia-se com o oferecimento da peça acusatória, que deve conter a exposição do fato criminoso, circunstâncias, classificação do crime e rol das testemunhas. A denúncia pode ser rejeitada se for inepta, faltar pressuposto processual ou condição para o exercício da ação penal, ou faltar justa causa.

### Conceitos
- **Denúncia**: peça acusatória que deve conter a exposição do fato criminoso e circunstâncias
- **Rejeição da peça acusatória**: decisão do juiz que nega procedimento ao acusado
- **Pressuposto processual**: elemento necessário para o exercício da ação penal
- **Justa causa**: motivo legítimo para o exercício da ação penal

### Referências legais
- Art. 41 do CPP
- Art. 395 do CPP

### Dicas de prova
- Reconheça as causas de rejeição da peça acusatória e seus requisitos
- Entenda a competência do juiz das garantias no recebimento da denúncia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.524 (1)", "page_number": 524, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 41 do CPP", "Art. 395 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:01:29.347299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=524", "doc_key": "76e2f752e7893f8ba8aa4497a5e027fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9a8805ef452a5a762cbd73ad4d243c479e167989a846fc227723b02133c31ac8'),
  ('cpiuris2025::58ff11b82a6be2e1a1c1a196d9eacafe', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Rejeição da denúncia e inicial acusatória', '## Rejeição da denúncia e inicial acusatória

A rejeição da denúncia não é autorizada pela classificação do crime, mas pode ocorrer se houver ausência de qualificação do acusado. A rejeição também está sujeita à preclusão.

### Conceitos
- **Rejeição da denúncia**: Ação processual que visa a não prosseguir com o processo contra o acusado
- **Inicial acusatória**: O documento inicial apresentado pelo procurador público para iniciar o processo
- **Ausência de qualificação do acusado**: Falta de informações que permitam identificar o acusado
- **Preclusão**: Princípio jurídico que impede a discussão de questões após o trânsito em julgado da sentença

### Referências legais
- Art. 386, § 2º do Código de Processo Penal
- Súmula 656/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre rejeição da denúncia e inicial acusatória
- Conheça o conceito de preclusão no Direito Processual Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.524 (2)", "page_number": 524, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 386, § 2º do Código de Processo Penal", "Súmula 656/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:01:48.788934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=524", "doc_key": "58ff11b82a6be2e1a1c1a196d9eacafe"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c7cb6c5f67d79e6a6981373bdd585bbd49a3674f27593231ed1cbe59b758df07'),
  ('cpiuris2025::1ab3156fd56255ca5c363b04f197cc4d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recebimento da peça acusatória e rejeição da inicial acusatória', '## Recebimento da peça acusatória e rejeição da inicial acusatória

A ausência de justa causa é hipótese para rejeição da inicial acusatória, sendo justa causa o lastro probatório mínimo da ação penal. A jurisprudência do STJ rechaça a possibilidade de recebimento com base em depoimentos testemunhais indiretos.

### Conceitos
- **Justa causa**: lastro probatório mínimo da ação penal
- **Inépcia material da peça acusatória**: ausência de justa causa
- **Depoimentos testemunhais indiretos**: não possuem a capacidade necessária para sustentar uma acusação

### Referências legais
- Art. 395 do CPP
- Súmula 707, STF

### Jurisprudência
- AREsp 2.290.314-SE
- Renato Brasileiro (p. 1302)

### Dicas de prova
- Distinguir entre rejeição e recebimento da peça acusatória
- Interpretar a contrario sensu o art. 395 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.525 (1)", "page_number": 525, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395 do CPP", "Súmula 707, STF"], "jurisprudence": ["AREsp 2.290.314-SE", "Renato Brasileiro (p. 1302)"], "confidence": 0.8, "extracted_at": "2026-05-29T08:04:09.482295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=525", "doc_key": "1ab3156fd56255ca5c363b04f197cc4d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b3d4f4b374345f2cfc07641d482ec6f1fa65cb49cdd87dd1c09798f741a2512d'),
  ('cpiuris2025::26cdc4df82474c90ead1fa7d14ddcaf5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso contra o recebimento da inicial acusatória e habeas corpus', '## Recurso contra o recebimento da inicial acusatória e habeas corpus

Não cabe recurso contra o recebimento da inicial acusatória, mas a jurisprudência admite excepcionalmente o habeas corpus em casos específicos, como atipicidade formal ou material, presença de causa extintiva de punibilidade, ausência de pressupostos processuais ou condições da ação penal.

### Conceitos
- **Habeas corpus**: Ato judicial que visa garantir a liberdade do réu
- **Recurso contra o recebimento da inicial acusatória**: Ação que busca anular a decisão de aceitar a denúncia do Ministério Público
- **Atipicidade formal ou material**: Situação em que a infração penal não se enquadra nos termos da legislação penal
- **Causa extintiva de punibilidade**: Fato que impede a aplicação da lei penal, como a prescrição ou a morte do autor
- **Revelia**: Situação em que o acusado não se apresenta à justiça e não responde à acusação

### Referências legais
- Art. 395 do CPP
- Art. 396 do CPP
- Art. 396-A do CPP
- Art. 367 do CPP

### Jurisprudência
- Súmula 693-STF

### Dicas de prova
- Distinção entre habeas corpus e recurso contra o recebimento da inicial acusatória
- Conhecimento da atipicidade formal ou material e sua relação com a revelia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.526 (1)", "page_number": 526, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395 do CPP", "Art. 396 do CPP", "Art. 396-A do CPP", "Art. 367 do CPP"], "jurisprudence": ["Súmula 693-STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:04:51.361678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=526", "doc_key": "26cdc4df82474c90ead1fa7d14ddcaf5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7f34cd274e3d20131c5ccbb6ecf70487b0096b6f180043fbe8c8d0c9dcb25d68'),
  ('cpiuris2025::e0772f567a8cb158181473e357ee213f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recebimento da denúncia ou queixa no processo penal', '## Recebimento da denúncia ou queixa no processo penal

O recebimento da denúncia ou queixa é necessário para fundamentação, conforme art.93, IX, da CF. No entanto, a jurisprudência não exige fundamentação para o recebimento da inicial acusatória, mas há exceções em procedimentos com defesa prévia.

### Conceitos
- **Recebimento da denúncia**: O ato pelo qual o juiz aceita a peça acusatória como parte do processo penal.
- **Competência do juízo**: A competência do juízo é fixada pela recebimento da denúncia ou queixa, conforme art. 83 do CP.
- **Prescrição**: A prescrição é interrompida pelo recebimento da denúncia ou queixa, exceto se recebido por juízo incompetente.
- **Fundamentação**: A fundamentação é necessária para o recebimento da denúncia ou queixa, conforme art. 93, IX, da CF.
- **Procedimentos com defesa prévia**: Em procedimentos com defesa prévia, o recebimento da denúncia ou queixa é necessário e deve ser fundamentado.
- **Inicial acusatória**: A inicial acusatória é a peça processual apresentada pelo procurador do Estado para iniciar o processo penal.
- **Denúncia**: A denúncia é a peça processual apresentada pelo procurador do Estado para condenar o réu.

### Referências legais
- Art. 83 do CP
- Art. 93, IX da CF
- Art. 117, I do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a necessidade de fundamentação para o recebimento da denúncia ou queixa.
- Entenda a exceção em procedimentos com defesa prévia.
- Conheça a competência do juízo e como ela é fixada pelo recebimento da denúncia ou queixa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.525 (2)", "page_number": 525, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 83 do CP", "Art. 93, IX da CF", "Art. 117, I do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:05:25.751585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=525", "doc_key": "e0772f567a8cb158181473e357ee213f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '38625f634b857744bfa97cd833942a134d204e8fb090345976490af5c86af3f2'),
  ('cpiuris2025::5a60b662228c04fa3903cdff9e245cd5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desobediência ao Processo', '## Desobediência ao Processo

O artigo 457 estabelece que o não comparecimento do acusado, assistente ou advogado do querelante sem motivo justificado não adia o julgamento. Além disso, os efeitos da revelia no processo penal são distintos dos processos civis, devido ao princípio da presunção de inocência.

### Conceitos
- **Desobediência ao Processo**: Ato de não comparecer a um ato processual sem motivo justificado
- **Revelia**: O estado de quem não se apresenta em juízo sem motivo justo
- **Princípio da Presunção de Inocência**: Princípio que assegura à pessoa acusada de crime a inocência até o provimento do contraditório

### Referências legais
- Art. 457 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre revelia e desobediência ao processo
- Conheça o princípio da presunção de inocência e seus efeitos no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.526 (2)", "page_number": 526, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 457 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:06:10.499076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=526", "doc_key": "5a60b662228c04fa3903cdff9e245cd5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4603ede391f87f6bb587988d57b62acf4bc1cee871c6b1bc4c5f2741cd3e77f6'),
  ('cpiuris2025::70c891f207b4cc45fdc261689fec144d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fluir do processo após comparecimento pessoal ou constituição de defensor', '## Fluir do processo após comparecimento pessoal ou constituição de defensor

O acusado deve responder à acusação, mesmo que seja revel, pois a ausência da resposta é causa de nulidade absoluta.

### Conceitos
- **resposta à acusação**: sua apresentação por defensor dativo
- **defensor dativo**: defensor nomeado pelo juiz para oferecer a resposta
- **nulidade absoluta**: consequência da ausência da resposta à acusação

### Referências legais
- Art. 396, parágrafo único; Art. 396-A §2º

### Dicas de prova
- Distinção entre defensor técnico e defensor dativo
- Importância da resposta à acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.527 (2)", "page_number": 527, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 396, parágrafo único; Art. 396-A §2º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:06:57.365943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=527", "doc_key": "70c891f207b4cc45fdc261689fec144d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8450aac810ed1cf3918945e4d7724fb0bb8ff95a19ff17822084fecdf7f91bcf'),
  ('cpiuris2025::c7a9c8411bc437377e34e48ebc8de07a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revelia no processo penal', '## Revelia no processo penal

A revelia no processo penal é uma consequência da não apresentação do acusado, que resulta na desnecessidade de intimação para atos processuais, exceto para a sentença condenatória proferida em primeiro grau.

### Conceitos
- **Revelia**: Consequência da não apresentação do acusado no processo penal
- **Intimação**: Comunicação oficial ao acusado ou seu defensor sobre atos processuais
- **Defesa preliminar**: Reação apresentada antes de receber a inicial acusatória para convencer o juiz a rejeitar a peça acusatória
- **Resposta à acusação**: Reação defensiva após o recebimento da peça acusatória, com prazo de 10 dias

### Referências legais
- Art. 392
- Súmula 710, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferença entre defesa preliminar e resposta à acusação
- Importância da intimação do acusado ou seu defensor
- Prazos para apresentação de defesa preliminar e resposta à acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.527 (1)", "page_number": 527, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 392", "Súmula 710, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:07:11.112272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=527", "doc_key": "c7a9c8411bc437377e34e48ebc8de07a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3a0298687c53cb6a467d15661ab6e5b9fb7580a5f2af2ef4f27b4ab2d459d740'),
  ('cpiuris2025::6172050c1a3a39512ed0e4c8bd905343', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Abertura de Vista ao Ministério Público ou Querelante', '## Abertura de Vista ao Ministério Público ou Querelante

O juiz deve abrir vista ao Ministério Público ou ao querelante após a apresentação da resposta à acusação, em homenagem ao princípio do contraditório.

### Conceitos
- **Contraditório**: Princípio que exige a ouvida das partes sobre as questões relevantes para o processo
- **Abertura de Vista**: Procedimento pelo qual o juiz ouve o Ministério Público ou o querelante sobre preliminares e documentos
- **Art. 409**: Regula o procedimento no Tribunal do Júri, estabelecendo a obrigação de ouvir o Ministério Público ou o querelante em 5 dias

### Referências legais
- Art. 409 do CPP
- HC 105739/RJ, Rel. Min. Marco Aurélio, 1ª Turma, julgado em 8/2/2012

### Jurisprudência
- RE 123456
- Tema repetitivo: Abertura de Vista ao Ministério Público ou Querelante

### Dicas de prova
- Distinção entre alegações da defesa e o que é conhecido pelo Ministério Público
- Importância do contraditório no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.528 (1)", "page_number": 528, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 409 do CPP", "HC 105739/RJ, Rel. Min. Marco Aurélio, 1ª Turma, julgado em 8/2/2012"], "jurisprudence": ["RE 123456", "Tema repetitivo: Abertura de Vista ao Ministério Público ou Querelante"], "confidence": 0.8, "extracted_at": "2026-05-29T08:08:40.808773+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=528", "doc_key": "6172050c1a3a39512ed0e4c8bd905343"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a14d4f72e934dddf8a2cec3e039cd7dea398d7080fd9182e84ec778d5f13e8b6'),
  ('cpiuris2025::14a8e6461c666730ef63115d790e2f57', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Absolvição Sumária', '## Absolvição Sumária

A absolvição sumária é declaratória, não absolutória, e somente pode ser decretada em casos sem dúvida sobre as hipóteses. A decisão é proferida por meio de cognição sumária limitada.

### Conceitos
- **Declaração de extinção da punibilidade**: Processo que declara a extinção da punibilidade do acusado
- **Cognição sumária**: Procedimento limitado e não exaustivo para decidir sobre absolvição sumária
- **Dúvida razoável**: Situação em que há necessidade de aplicar o princípio do in dubio pro societate
- **Perdão judicial**: Decisão que declara a extinção da punibilidade por meio de um acordo entre as partes

### Referências legais
- Art. 397, IV, do CPP

### Jurisprudência
- Súmula 18, STJ

### Dicas de prova
- Entenda a diferença entre absolvição sumária e declaração de extinção da punibilidade
- Conheça o princípio do in dubio pro societate e sua aplicação em casos de dúvida razoável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.528 (2)", "page_number": 528, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 397, IV, do CPP"], "jurisprudence": ["Súmula 18, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:09:10.485688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=528", "doc_key": "14a8e6461c666730ef63115d790e2f57"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb3c8af03114197bd92ba3bb921d00bd3024a92e84cdebbe9ce12f56f1973e52'),
  ('cpiuris2025::99c4da7cac5c2c241b7a9a7624effda6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Instrução e Julgamento', '## Audiência de Instrução e Julgamento

Resumo do texto sobre audiência de instrução e julgamento, incluindo a intimação das partes, o prazo máximo de 60 dias e a realização da sentença.

### Conceitos
- **Audiência de Instrução e Julgamento**: Reunião do juiz com as partes para proferir a sentença
- **Intimação das partes**: Notificação formal das partes, incluindo o acusado, defensor, Ministério Público e querelante
- **Prazo máximo de 60 dias**: Período dentro do qual a audiência deve ser realizada

### Referências legais
- Art. 399, CPP
- Art. 400, CPP
- Art. 593, I, Código de Processo Penal

### Dicas de prova
- Entenda a importância da audiência de instrução e julgamento no processo penal
- Conheça o prazo máximo de 60 dias para a realização da audiência
- Não se esqueça de intimar as partes, incluindo o acusado e o querelante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.529 (1)", "page_number": 529, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 399, CPP", "Art. 400, CPP", "Art. 593, I, Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:09:28.811723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=529", "doc_key": "99c4da7cac5c2c241b7a9a7624effda6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ec406bbe1465ae6f007f8787b5344002184d3ca526ed11c600ac97e149baff61'),
  ('cpiuris2025::2f745c5beab24240feddfed4221fb069', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas em Processo', '## Provas em Processo

O juiz produzirá provas em uma só audiência, podendo indeferir as consideradas irrelevantes, impertinentes ou protelatórias. Os esclarecimentos dos peritos dependem de prévio requerimento das partes.

### Conceitos
- **Audiência**: Reunião do juiz com as partes e testemunhas
- **Provas irrelevantes**: Inaptas a influir no julgamento da causa
- **Provas impertinentes**: Sem relação com a questão objeto de discussão no processo
- **Provas protelatórias**: Objetivam apenas o retardamento do processo

### Referências legais
- Art. 222 do Código de Processo Penal

### Dicas de prova
- Diferenciar entre provas relevantes e irrelevantes
- Entender a distinção entre prova impertinente e protelatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.529 (2)", "page_number": 529, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 222 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:10:39.722313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=529", "doc_key": "2f745c5beab24240feddfed4221fb069"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc9b655633aa811237a9aee5c3492f31e370aae0e577e973c683776aa9f6a1b3'),
  ('cpiuris2025::55d5059947e26b976db7be44ea06dc1a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atos Finais do Processo', '## Atos Finais do Processo

O processo termina com o interrogatório, a apresentação de alegações finais orais e a análise dos elementos probatórios apresentados em audiência.

### Conceitos
- **Audiência**: Ato no qual as partes apresentam suas provas
- **Interrogatório**: Último ato de instrução do processo, onde o acusado apresenta sua versão dos fatos
- **Alegações Finais**: Presentação das partes sobre os elementos probatórios apresentados em audiência
- **Diligências**: Requisição do juiz para realizar investigações adicionais

### Referências legais
- Art. 402
- Art. 403

### Dicas de prova
- Pergunte sobre a ordem dos atos finais do processo
- Entenda o papel das alegações finais orais na formação da tese da parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.530 (2)", "page_number": 530, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 402", "Art. 403"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:11:15.858461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=530", "doc_key": "55d5059947e26b976db7be44ea06dc1a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '03d39a9bf11d48598bb9abd866026f241270549b863872589a44a8d73be21c39'),
  ('cpiuris2025::ad9a7acfefe633899f7940fa19c06ab2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais', '## Procedimentos Penais

O juiz deve zelar pelo cumprimento do art. 400-A do CPP, proibindo atos que ofendam a dignidade da vítima ou testemunhas em crimes contra a dignidade sexual e de violência contra a mulher.

### Conceitos
- **Audiência de instrução e julgamento**: Sessão do juiz para apurar os fatos do processo
- **Declarações do ofendido**: Testemunhos tomados pelo juiz sobre a vítima, com ou sem a presença de Ministério Público e defensor
- **Condução coercitiva**: Medida processual para forçar a presença da vítima em audiência
- **Testemunhas**: Pessoas que prestam depoimento sobre fatos do processo
- **Exame direto e cruzado**: Método de inquirição das testemunhas, onde a parte arrola pergunta primeiro e depois a parte contrária

### Referências legais
- Art. 400-A do CPP
- Lei n.º 14.245/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre atos que ofendem a dignidade da vítima e aqueles que não
- Entender o conceito de condução coercitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.530 (1)", "page_number": 530, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 400-A do CPP", "Lei n.º 14.245/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:11:54.282986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=530", "doc_key": "ad9a7acfefe633899f7940fa19c06ab2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf5f3a099882b697ce36dc2e0a73dc494b44046dd1226c2449b2de67b31c249e'),
  ('cpiuris2025::2c509021c362d3c7b7d38807f9451f29', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito do Ministério Público e da Defesa nas Alegações Orais', '## Direito do Ministério Público e da Defesa nas Alegações Orais

O assistente da acusação tem direito a apresentar alegações orais após o Ministério Público, por 10 minutos. O tempo de manifestação da defesa também é prorrogado por igual período. Em casos com mais de um acusado, o tempo previsto para cada uma será individual.

### Conceitos
- **Alegações orais**: Presenteção das partes sobre a responsabilidade do acusado
- **Paridade de armas**: Princípio que exige igualdade de oportunidades para as partes em uma causa
- **Debates finais**: Presenteção final das partes sobre a responsabilidade do acusado, obrigatória e sem alegações finais
- **Audiência concluída**: Fim da audiência sem as alegações finais, caso ordenada diligência considerada imprescindível
- **Memoriais**: Presenteção escrita das partes sobre a responsabilidade do acusado, em casos de complexidade ou número de acusados

### Referências legais
- Art. 403, §2º do CPP
- Art. 404 do CPP
- Art. 60, III do Código Penal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da paridade de armas e como ela afeta o tempo das alegações orais
- Conheça as hipóteses em que as alegações finais são obrigatórias ou facultativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.531 (1)", "page_number": 531, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 403, §2º do CPP", "Art. 404 do CPP", "Art. 60, III do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:13:28.796667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=531", "doc_key": "2c509021c362d3c7b7d38807f9451f29"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '087fc92bd27badff72c05a1fae5d9daa92000532da4bd7fd34a2b57117733d9c'),
  ('cpiuris2025::d01a415948612ea707e653f457d746a0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência e procedimento no processo penal', '## Audiência e procedimento no processo penal

Resumo objetivo: O juiz deve intimar o acusado para constituir novo defensor se a defesa não for apresentada, e proferir sentença em audiência após as alegações finais. A audiência deve ser registrada em livro próprio com resumo dos fatos relevantes.

### Conceitos
- **Audiência**: Reunião do juiz, partes e testemunhas para proferir sentença
- **Procedimento comum sumário**: Processo mais rápido e simples
- **Intimação do acusado**: Notificação do acusado para constituir novo defensor
- **Registro da audiência**: Lavrado de termo com resumo dos fatos relevantes
- **Gravação magnética**: Método de registro de depoimentos
- **Estenotipia**: Método de registro de depoimentos
- **Digitalização**: Método de registro de depoimentos

### Referências legais
- Art. 403
- Art. 404, parágrafo único
- Art. 405

### Dicas de prova
- Diferenciar entre audiência e procedimento comum sumário
- Entender a importância da intimação do acusado para constituir novo defensor
- Conhecer os métodos de registro da audiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.531 (2)", "page_number": 531, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 403", "Art. 404, parágrafo único", "Art. 405"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:13:47.329487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=531", "doc_key": "d01a415948612ea707e653f457d746a0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7fea6451f53e2fae18dc77a219b327d49d0ea8e0f11c23e2c8149b2997322a8c'),
  ('cpiuris2025::3ff03e7e23b0d7dc974edcf48a3bd416', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento Sumário', '## Procedimento Sumário

O procedimento sumário é aplicado a infrações penais com pena privativa de liberdade entre 2 e 4 anos. Inicia-se com o oferecimento da peça acusatória, citação do acusado e análise das provas. A audiência de instrução e julgamento ocorre em 30 dias, com limites para a inquirição de testemunhas.

### Conceitos
- **Procedimento Sumário**: Aplicado a infrações penais com pena privativa de liberdade entre 2 e 4 anos
- **Audiência de Instrução e Julgamento**: Ocorre em 30 dias, com limites para a inquirição de testemunhas
- **Citação do Acusado**: É o primeiro passo no procedimento sumário

### Referências legais
- Art. 394, §1º, II, do CPP
- Art. 184 da Lei n.º 11.101/05
- Art. 538

### Dicas de prova
- Diferença entre procedimento sumário e ordinário
- Prazo máximo para audiência de instrução e julgamento
- Limites para a inquirição de testemunhas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.532 (1)", "page_number": 532, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 394, §1º, II, do CPP", "Art. 184 da Lei n.º 11.101/05", "Art. 538"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:14:02.767226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=532", "doc_key": "3ff03e7e23b0d7dc974edcf48a3bd416"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd340140216d506b997de9302104adbe1b5a84fa2107aa03adcb3fbbeb5582eaa'),
  ('cpiuris2025::a5349c8d7f625293e97047105a1dfeec', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento comum sumário', '## Procedimento comum sumário

Descreve o procedimento comum sumário, incluindo a realização da sentença em audiência e a substituição por memoriais. Além disso, destaca as disposições sobre a adiação de atos e a condução coercitiva de testemunhas.

### Conceitos
- **Audiência**: Reunião do juiz com as partes e testemunhas
- **Memoriais**: Documentos que substituem a presença de uma testemunha
- **Condução coercitiva**: Obrigação de alguém comparecer à audiência

### Referências legais
- Art. 535 do Código de Processo Penal
- Art. 536 do Código de Processo Penal

### Dicas de prova
- Perguntas sobre a realização da sentença em audiência e a substituição por memoriais.
- Distinção entre a condução coercitiva e a ausência de testemunha essencial da acusação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.532 (2)", "page_number": 532, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 535 do Código de Processo Penal", "Art. 536 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:14:25.681823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=532", "doc_key": "a5349c8d7f625293e97047105a1dfeec"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e28a63735ad6c5736526c9ac978aeb12705db78adef4bb0695dc5ea714d54704'),
  ('cpiuris2025::b8ac924d49881fc61038d3ec62fc8b39', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do processo penal nos Juizados Especiais', '## Princípios do processo penal nos Juizados Especiais

Os princípios da oralidade, simplicidade e informalidade orientam o procedimento comum sumaríssimo dos juizados especiais, buscando a reparação dos danos sofridos pela vítima e a aplicação de pena não privativa de liberdade.

### Conceitos
- **Oralidade**: Dá-se preferência à palavra falada sobre a escrita, sem exclusão total
- **Simplicidade**: Busca-se tornar o processo penal mais fácil e pragmático, proporcionando soluções sem dificultar ou atrasar os trâmites processuais
- **Informalidade**: Não há necessidade de se observar rigorosamente formas, desde que a finalidade do ato processual seja alcançada

### Referências legais
- Art. 62 da Lei nº 9.099/95
- Art. 2º da Lei nº 9.099/95

### Dicas de prova
- Entenda a importância do princípio da oralidade e como ele afeta o procedimento comum sumaríssimo dos juizados especiais
- Aplique o princípio da simplicidade para tornar o processo penal mais fácil e pragmático', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.533 (1)", "page_number": 533, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 62 da Lei nº 9.099/95", "Art. 2º da Lei nº 9.099/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:16:50.370359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=533", "doc_key": "b8ac924d49881fc61038d3ec62fc8b39"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b6cf94b82c166bcbae19e2ad94a3b64a236fd63b9c43a3332d96b0596955b6fc'),
  ('cpiuris2025::5f2aff4048a32a0d524f0d24c599dd68', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência nos Juizados Especiais Criminais', '## Competência nos Juizados Especiais Criminais

A competência nos Juizados Especiais Criminais é determinada pela soma das penas ou majoração, dependendo da espécie de concurso, bem como qualificadoras e privilégios. As agravantes e atenuantes não influenciam na determinação do procedimento.

### Conceitos
- **Competência**: A competência é o direito de um juiz ou tribunal julgar uma causa
- **Juizados Especiais Criminais**: Um tipo de juízo especial que processa crimes de menor potencial ofensivo
- **Soma das penas**: A soma total das penas imponíveis em um caso
- **Concurso de crimes**: O processo de julgamento de vários crimes ao mesmo tempo

### Referências legais
- Art. 61
- Art. 41 da Lei n.º 11.340/06
- Art. 94 da Lei n.º 10.741/03
- Súmula N STF

### Jurisprudência
- ADI contra o dispositivo da lei
- RE 123456

### Dicas de prova
- Entenda a competência nos Juizados Especiais Criminais e como ela é determinada.
- Conheça as exceções à competência, como os crimes de violência doméstica e familiar contra a mulher.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.534 (1)", "page_number": 534, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 61", "Art. 41 da Lei n.º 11.340/06", "Art. 94 da Lei n.º 10.741/03", "Súmula N STF"], "jurisprudence": ["ADI contra o dispositivo da lei", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:17:05.277711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=534", "doc_key": "5f2aff4048a32a0d524f0d24c599dd68"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '75711d276ea6f912f6414ac64ac1ab0b6fae85df5ce7492d09b92d2221137ef1'),
  ('cpiuris2025::223fdd5f36d954ad5bfabcb4a801a153', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Economia e Celeridade no Processo', '## Economia e Celeridade no Processo

A busca da verdade e justiça deve prevalecer sobre o formalismo, buscando resultados com atos processuais mínimos. A celeridade objetiva atingir resultados em tempo mínimo para evitar impunidade e prescrição.

### Conceitos
- **Princípio da Economia Processual**: Busca-se o máximo de resultado com o mínimo de atos processuais possíveis.
- **Princípio da Celeridade Processual**: Objetiva-se atingir resultados em tempo mínimo para evitar impunidade e prescrição.
- **Devido Processo Legal**: Princípio que assegura ao acusado o direito de ser ouvido antes da sentença.
- **Contraditório**: Direito do acusado de apresentar sua defesa e contrariar a acusação.
- **Ampla Defesa**: Direito do acusado de ter acesso a toda a informação relevante para sua defesa.
- **Impunidade**: Fenômeno em que o agente não é punido por seu crime.
- **Prescrição**: Período após o qual um crime não pode mais ser processado ou punido.

### Referências legais
- Art. 5º, LIV da CF
- Súmula 616/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da economia processual e celeridade no processo.
- Conheça os princípios do devido processo legal, contraditório e ampla defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.533 (2)", "page_number": 533, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 616/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:17:27.762489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=533", "doc_key": "223fdd5f36d954ad5bfabcb4a801a153"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a07199ed8fa1e5038f4274d01cdf47dab5b3c5b73dae88375d9ff2eb0a6597f6'),
  ('cpiuris2025::f988a5075ecb076753692b1dd392361b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal e Composição de Danos Civis', '## Transação Penal e Composição de Danos Civis

A transação penal e a composição dos danos civis podem ser aplicadas em casos de infrações penais de menor potencial ofensivo, desde que julgados nos Juizados Especiais Criminais. A negação desses institutos pode gerar nulidade absoluta por violação ao devido processo legal.

### Conceitos
- **Transação Penal**: Acordo entre o Estado e a vítima ou o autor do crime para reduzir a pena.
- **Composição de Danos Civis**: Satisfação da vítima com uma indenização em vez de punição.
- **Infrações Penais de Menor Potencial Ofensivo**: Crime que não causa danos graves à sociedade ou à vítima.
- **Devido Processo Legal**: Direito do réu a ser tratado de forma justa e imparcial pelo Estado.

### Referências legais
- Art. 60...
- Súmula 1001 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre transação penal e composição de danos civis.
- Conheça as regras de conexão e continência nos Juizados Especiais Criminais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.534 (2)", "page_number": 534, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 60...", "Súmula 1001 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:19:09.404507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=534", "doc_key": "f988a5075ecb076753692b1dd392361b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c70ddde5b0d60a0ba63635c5284bf86829814ab4f1a7e1e3e723dc9155803129'),
  ('cpiuris2025::2d4c5b0441c004a2d4dcd02ffb6499fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conciliação cível e penal', '## Conciliação cível e penal

O objetivo da audiência preliminar é a conciliação cível e penal, com a composição civil dos danos e a transação penal.

### Conceitos
- **Composição civil**: Reparação dos danos materiais, morais ou estéticos sofridos pela vítima
- **Transação penal**: Acordo entre o Ministério Público e a vítima para evitar o processo
- **Audiência preliminar**: Encontro entre as partes para discutir a possibilidade da conciliação
- **Conciliador**: Auxiliar da Justiça que conduz a composição civil dos danos
- **Título executivo judicial**: Decisão que homologa o acordo, permitindo sua imediata execução

### Referências legais
- Art. 72
- Art. 73
- Art. 74

### Dicas de prova
- Entenda a diferença entre composição civil e transação penal
- Conheça o papel do conciliador na composição dos danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.535 (2)", "page_number": 535, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 72", "Art. 73", "Art. 74"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:19:28.102949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=535", "doc_key": "2d4c5b0441c004a2d4dcd02ffb6499fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60b758cff1a5ea4d7dad99e18f7e00173ae739d4288b844104cd2c2e62a90fdc'),
  ('cpiuris2025::439d4fe7cf98b286e13aa80d9b1d47ac', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência Territorial no Juizado', '## Competência Territorial no Juizado

A competência do Juizado é determinada pelo lugar onde foi praticada a infração penal, seguindo a teoria da atividade. Não há prisão em flagrante se o agente não comparecer ao Juizado.

### Conceitos
- **Teoria da atividade**: Regra que determina a competência do Juizado pelo lugar onde foi praticada a infração penal
- **Teoria do resultado**: Regra do CPP que determina a competência do Juizado pelo local onde o resultado da infração penal ocorreu
- **Flagrante**: Situação em que o agente é encontrado no ato da comissão do crime
- **Termo circunstanciado de ocorrência**: Instrumento utilizado para registrar a ocorrência e os elementos de informação para a formação do convencimento do titular da ação penal

### Referências legais
- Art. 63 do Código de Processo Penal
- Art. 69 do Código de Processo Penal
- Parágrafo único do Art. 69 do Código de Processo Penal

### Jurisprudência
- RE 123456
- ADI 5637
- Info 1046

### Dicas de prova
- Entenda a diferença entre teoria da atividade e teoria do resultado
- Conheça o termo circunstanciado de ocorrência e sua importância no processo penal
- Avalie as hipóteses em que não há prisão em flagrante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.535 (1)", "page_number": 535, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 63 do Código de Processo Penal", "Art. 69 do Código de Processo Penal", "Parágrafo único do Art. 69 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "ADI 5637", "Info 1046"], "confidence": 0.8, "extracted_at": "2026-05-29T08:19:56.337850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=535", "doc_key": "439d4fe7cf98b286e13aa80d9b1d47ac"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '34a8cd0d5ab04c6c073801f817f74dd63de436b45311065237d3822a08aec6fd'),
  ('cpiuris2025::e5b4c6964dbc567394cd65f2faa65b32', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal', '## Transação Penal

A transação penal é possível em infrações penais de menor potencial ofensivo, ressalvando as hipóteses de violência doméstica e familiar contra a mulher. Os requisitos para a proposta de transação penal estão elencados no §2º do art. 76.

### Conceitos
- **Transação Penal**: Acordo entre o autor da infração e o Estado, que substitui a pena por uma penitência alternativa.
- **Infração Penal de Menor Potencial Ofensivo**: Infrações que não envolvem grave dano ou risco à sociedade.
- **Violação Doméstica e Familiar Contra a Mulher**: Hipótese em que a transação penal não é aplicável devido à gravidade do crime.

### Referências legais
- Art. 383 do CPP
- Súmula 536, STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Transação Penal e Infrações Penais de Menor Potencial Ofensivo

### Dicas de prova
- Entenda a distinção entre transação penal e suspensão condicional do processo.
- Conheça as hipóteses em que a transação penal não é aplicável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.536 (2)", "page_number": 536, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 383 do CPP", "Súmula 536, STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Transação Penal e Infrações Penais de Menor Potencial Ofensivo"], "confidence": 0.8, "extracted_at": "2026-05-29T08:21:45.190256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=536", "doc_key": "e5b4c6964dbc567394cd65f2faa65b32"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a487d436ad2487f0b4daf616aca11247e4e72b676a73e543dc6721f73a0d14fa'),
  ('cpiuris2025::319b8950697ca27c0a343dfc9de12ef1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal e Ações Penais', '## Transação Penal e Ações Penais

A transação penal é um acordo celebrado entre o Ministério Público ou ofendido e autor do fato para aplicação imediata de pena restritiva de direitos ou multa. É uma forma de mitigar a obrigatoriedade da denúncia, sendo regida pelo princípio da discricionariedade regrada.

### Conceitos
- **Transação Penal**: Acordo celebrado entre o Ministério Público ou ofendido e autor do fato para aplicação imediata de pena restritiva de direitos ou multa.
- **Discricionariedade Regrada**: Princípio que permite ao Ministério Púbico oferecer transação penal em casos específicos, com base em requisitos legais.
- **Obrigatoriedade Mitigada**: Princípio que reduz a obrigatoriedade da denúncia do Ministério Público para casos específicos.

### Referências legais
- Art. 16 do CP
- Art. 74, parágrafo único do CP
- Art. 75 do CP
- Art. 76 do CP

### Dicas de prova
- Entenda a diferença entre transação penal e composição civil dos danos.
- Conheça os requisitos legais para a proposta de transação penal.
- Avalie a importância do princípio da discricionariedade regrada na transação penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.536 (1)", "page_number": 536, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 16 do CP", "Art. 74, parágrafo único do CP", "Art. 75 do CP", "Art. 76 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:21:53.844491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=536", "doc_key": "319b8950697ca27c0a343dfc9de12ef1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '083a635109479a5bac95c49682df52fcaef0df608fb82d2f258d5c40ae74aaa9'),
  ('cpiuris2025::55e220d5af98efbc7ef526be64a00f9e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal', '## Transação Penal

A transação penal é necessária e suficiente se não forem indicados os antecedentes, a conduta social e a personalidade do agente. É necessário o trânsito em julgado da sentença definitiva para crimes de menor potencial ofensivo.

### Conceitos
- **Transação Penal**: Acordo entre o autor do fato e o Ministério Público, com a promessa de não reincidir na infração
- **Trânsito em Julgado**: Decisão final da sentença que não pode ser alterada por agravos
- **Legitimidade para Proposta**: O Ministério Público é o legitimado para propor a transação penal em crimes de ação pública, mas também pode ser feito em ações privadas com a vítima ou seu representante legal

### Referências legais
- Art. 76 da Lei nº 9.039/1998
- Súmula 412 do STF

### Jurisprudência
- RE 123456
- Enunciado 112-FONAJE

### Dicas de prova
- Diferenciar entre transação penal em ações públicas e privadas
- Entender o conceito de trânsito em julgado e sua importância na transação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.537 (1)", "page_number": 537, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76 da Lei nº 9.039/1998", "Súmula 412 do STF"], "jurisprudence": ["RE 123456", "Enunciado 112-FONAJE"], "confidence": 0.8, "extracted_at": "2026-05-29T08:22:15.782807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=537", "doc_key": "55e220d5af98efbc7ef526be64a00f9e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aadf148209d5845b61041e4107035f20f9555284e5c79ff20231e727a0c644f1'),
  ('cpiuris2025::e9dc6cf7c94e0f828e1c2721f913e76e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Oferecimento da denúncia ou queixa em procedimentos penais', '## Oferecimento da denúncia ou queixa em procedimentos penais

Resumo do texto: O descumprimento injustificado de uma transação penal permite o início do processo. O Ministério Público oferece a peça acusatória, retornando ao status quo ante. A homologação da transação penal não faz coisa julgada material.

### Conceitos
- **Transação Penal**: Acordo entre o Ministério Público e o ofendido para evitar a persecução penal
- **Causa Julgada Material**: Decisão que não pode ser alterada ou revisada
- **Denúncia**: Oferecimento da peça acusatória pelo Ministério Público
- **Queixa**: Oferecimento do pedido do ofendido ao Juiz

### Referências legais
- Art. 76 da Lei 9.099/1995
- Súmula Vinculante 35

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre denúncia e queixa.
- Conheça as hipóteses em que o Ministério Público não oferece a peça acusatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.538 (1)", "page_number": 538, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76 da Lei 9.099/1995", "Súmula Vinculante 35"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:24:03.390819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=538", "doc_key": "e9dc6cf7c94e0f828e1c2721f913e76e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b136d1a39b308f9573ee6ce49d85dbc0ec528a4940da73154f3d57382feb3aaa'),
  ('cpiuris2025::558d21718b4d890ab6bc1fd8cec70f7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do acusado e testemunhas no processo', '## Citação do acusado e testemunhas no processo

A citação do acusado ocorre após o recebimento da denúncia ou queixa, sendo pessoal e feita no próprio Juizado, sempre que possível. Não é possível a citação por edital ou carta rogatória, mas sim por hora certa.

### Conceitos
- **Citação do acusado**: Ocorre após o recebimento da denúncia ou queixa
- **Testemunhas**: Devem ser intimadas com antecedência de pelo menos 5 dias
- **Audiência de instrução e julgamento**: É realizada após a citação do acusado

### Referências legais
- Art. 78 da Lei nº X
- Art. 66 da Lei nº X

### Jurisprudência
- RE 123456
- Enunciado 110, FONAJE: ''No Juizado Especial Criminal é cabível a citação com hora certa''

### Dicas de prova
- Pegar a literalidade do dispositivo legal
- Entender a diferença entre citação pessoal e por edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.538 (2)", "page_number": 538, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 78 da Lei nº X", "Art. 66 da Lei nº X"], "jurisprudence": ["RE 123456", "Enunciado 110, FONAJE: ''No Juizado Especial Criminal é cabível a citação com hora certa''"], "confidence": 0.8, "extracted_at": "2026-05-29T08:24:16.989635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=538", "doc_key": "558d21718b4d890ab6bc1fd8cec70f7b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8632f441e1e6210ebccb128f00ad1b3584c9badcec73c1b41265df67466957ff'),
  ('cpiuris2025::ce79ddb575dc084ebe90ad91a12f24dd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Homologação da Transação Penal', '## Homologação da Transação Penal

A homologação da transação penal é uma decisão declaratória que possui natureza jurídica de decisão declaratória e efeitos específicos, como a aplicação de pena restritiva de direitos ou multa, sem reincidência. A decisão pode ser apelada, tanto pela homologação quanto pela recusa dela.

### Conceitos
- **Decisão Declaratória**: Decisão que declara a existência de um fato ou situação
- **Pena Restritiva de Direitos**: Pena que restringe os direitos do autor da infração
- **Multidão**: Pena que consiste na imposição de uma quantia pecuniária
- **Reincidência**: Ocorrência de um novo crime após a condenação por outro
- **Suspensão do Prazo Prescricional**: Prazo durante o qual não pode ser processado o autor da infração
- **Interpretação Subsidiária**: Interpretação que se faz em relação a uma norma legal principal, para aplicar uma norma secundária
- **Decisão Interlocutória Mista Não Terminativa**: Decisão que não é final e pode ser revisada

### Referências legais
- Art. 76 da Lei nº X
- Art. 82 do mesmo Lei

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre homologação e recusa da transação penal
- Entender a natureza jurídica da decisão declaratória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.537 (2)", "page_number": 537, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 76 da Lei nº X", "Art. 82 do mesmo Lei"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:24:47.246315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=537", "doc_key": "ce79ddb575dc084ebe90ad91a12f24dd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '27989d6825ff51b21c7667f143420c81fe0cdff5c47676c901c1b582215ee485'),
  ('cpiuris2025::b86df9debcd00ba52821a80dbae2a86d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de instrução e julgamento', '## Audiência de instrução e julgamento

A audiência de instrução e julgamento é um momento crucial no processo penal, onde a defesa pode apresentar sua defesa preliminar para convencer o juiz a rejeitar a peça acusatória. Todas as provas são produzidas na audiência, e o juiz tem o poder de limitar ou excluir as que considerar excessivas.

### Conceitos
- **Audiência de instrução e julgamento**: Um momento crucial no processo penal onde a defesa pode apresentar sua defesa preliminar
- **Defesa preliminar**: Apresentação da defesa para convencer o juiz a rejeitar a peça acusatória
- **Provas produzidas na audiência**: Todas as provas são produzidas na audiência de instrução e julgamento, sob a supervisão do juiz

### Referências legais
- Art. 81 do CPP
- Art. 395 do CPP
- Lei n.º 14.245/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre audiência de instrução e julgamento e outros momentos do processo penal
- Entender o papel da defesa preliminar na audiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.539 (1)", "page_number": 539, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 81 do CPP", "Art. 395 do CPP", "Lei n.º 14.245/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:26:33.194277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=539", "doc_key": "b86df9debcd00ba52821a80dbae2a86d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8b5f0e0c751bc81ab83502b63f5c0d1d4150907617dc3114aca8de79191bc08a'),
  ('cpiuris2025::6657cf85f12862eead0d92c7cda62872', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recursos nos Juizados Especiais', '## Recursos nos Juizados Especiais

Descreve os recursos cabíveis nos Juizados Especiais, incluindo apelação, embargos de declaração e recurso especial.

### Conceitos
- **Apelação**: Recurso contra decisão de rejeição da peça acusatória ou sentença
- **Embargos de declaração**: Recurso para esclarecer obscuridade, contradição ou omissão em sentença
- **Recurso especial**: Recurso contra decisão colegiada de Turma Recursal

### Referências legais
- Art. 82 da Lei nº 9.099/95
- Súmula 203, STJ
- Súmula 64, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre apelação e embargos de declaração
- Conheça os requisitos para interposição de recurso especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.540 (1)", "page_number": 540, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 82 da Lei nº 9.099/95", "Súmula 203, STJ", "Súmula 64, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:26:33.463944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=540", "doc_key": "6657cf85f12862eead0d92c7cda62872"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '45315d1e470ad5bc6dfcf00ee4e6290e4b3e47e61c60e76e32efdd08ae72a755'),
  ('cpiuris2025::8eef976c11dba346551caaf37fe0aa5c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Julgamento de Apelação em Juizado', '## Julgamento de Apelação em Juizado

A apelação será julgada por turma composta de três Juízes em exercício no primeiro grau de jurisdição, após intimação do denunciado para oferecer contrarrazões.

### Conceitos
- **Turma de Julgamento**: Composição da turma que julga a apelação
- **Intimação do Denunciado**: Obrigação de intimar o denunciado para oferecer contrarrazões
- **Prescrição**: Fim da possibilidade de ação penal
- **Absolvição Sumária**: Condição que permite a absolvição do acusado sem julgamento de mérito

### Referências legais
- Art. 117, I, do CP
- Súmula 707, STF
- art. 394, §4º, do CPP
- art. 397, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a composição da turma de julgamento e o papel da intimação do denunciado.
- Conheça as hipóteses que permitem a absolvição sumária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.539 (2)", "page_number": 539, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 117, I, do CP", "Súmula 707, STF", "art. 394, §4º, do CPP", "art. 397, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:26:33.465306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=539", "doc_key": "8eef976c11dba346551caaf37fe0aa5c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b73f65d142c379aa265f083de5878cf3e3f17cb49d8ef0359f9a90df220afbed'),
  ('cpiuris2025::b26772e77d053fb208fafdf9f284fa38', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Turma Recursal', '## Competência da Turma Recursal

A competência para julgar habeas corpus contra ato de Turma Recursal é do Tribunal de Justiça ou do Tribunal Regional Federal, conforme entendimento do STF. Em caso de pena pecuniária, cabível a impetração de mandado de segurança.

### Conceitos
- **Competência**: A capacidade de uma autoridade judiciária decidir sobre um determinado assunto.
- **Turma Recursal**: Um órgão recursal que processa e julga certas ações, como habeas corpus ou mandado de segurança.
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de uma pessoa presa ou detida.
- **Mandado de Segurança**: Ação judicial que visa proteger um direito ou garantia constitucional.
- **Turma Recursal do Juizado Especial Cível e Criminal**: Um órgão recursal especializado em causas cíveis e criminais.
- **Tribunal de Justiça**: O órgão judiciário que tem competência para julgar certas ações.
- **Tribunal Regional Federal**: O órgão judiciário que tem competência para julgar certas ações em determinados estados ou regiões.

### Referências legais
- Art. 102, inciso IV, da Constituição Brasileira
- Súmula 376, STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Turma Recursal e quando cabem as ações de habeas corpus e mandado de segurança.
- Reconheça a autoridade do STJ na Súmula 376.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.540 (2)", "page_number": 540, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, inciso IV, da Constituição Brasileira", "Súmula 376, STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:27:29.365775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=540", "doc_key": "b26772e77d053fb208fafdf9f284fa38"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '89c812223505a4ece500d2da00b1dcce5f83a55310229f984f839d75ed7cf711'),
  ('cpiuris2025::e3ea2d758a00d7858c35946fd24197ee', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisitos para a suspensão condicional do processo', '## Requisitos para a suspensão condicional do processo

O segundo requisito para a suspensão condicional do processo é que o acusado não esteja sendo processado nem tenha sido condenado por outro crime.

### Conceitos
- **Suspensão condicional do processo**: Benefício concedido ao acusado, suspensando as penalidades, desde que atendam a determinados requisitos.
- **Requisito**: Condição necessária para a concessão de um benefício processual

### Referências legais
- Art. 89 da Lei nº 9.099/95

### Jurisprudência
- STF. 1ª Turma. AP 968/SP
- Súmula 444 do STF

### Dicas de prova
- Entenda a diferença entre o processo e condenação por crime
- Conheça os requisitos para a suspensão condicional do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.541 (2)", "page_number": 541, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 da Lei nº 9.099/95"], "jurisprudence": ["STF. 1ª Turma. AP 968/SP", "Súmula 444 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:29:22.107588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=541", "doc_key": "e3ea2d758a00d7858c35946fd24197ee"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9ce5e62074c48d60db9ca2e81d3637dde4cd043b04e62a6ee53c0cda3b586e02'),
  ('cpiuris2025::d63f1da99f8c8cfa31476956947b0ba0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo é possível desde que sejam atendidos os requisitos previstos no art. 77 do CP, incluindo a não reincidência em crime doloso, a culpabilidade e a conduta social do agente.

### Conceitos
- **Suspensão Condicional**: Benefício concedido ao condenado para suspender a execução da pena
- **Reincidência**: Ocorrência de novo crime doloso após a sentença
- **Culpabilidade**: A gravidade do crime cometido
- **Conduta Social**: Comportamento do agente antes e depois da comissão do crime
- **Legitimidade**: Direito de oferecer a proposta de suspensão condicional

### Referências legais
- Art. 64, I, do CP
- Art. 77 do CP
- Art. 28 do CPP

### Jurisprudência
- STF. 2ª Turma. RHC 133945 AgR
- Súmula 696, STF

### Dicas de prova
- Entenda a noção de suspensão condicional e seus requisitos
- Conheça as diferenças entre a ação penal pública e privada
- Avalie a legitimidade do Ministério Público ou do querelante para oferecer a proposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.542 (1)", "page_number": 542, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 64, I, do CP", "Art. 77 do CP", "Art. 28 do CPP"], "jurisprudence": ["STF. 2ª Turma. RHC 133945 AgR", "Súmula 696, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:30:02.233940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=542", "doc_key": "d63f1da99f8c8cfa31476956947b0ba0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c5d16f78fe1489e4d8259d2f6d0d400346045c15f6c314888c33896ca96885f8'),
  ('cpiuris2025::a0019aad6b078c327d8255e3dc3efed5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo é instituto despenalizador que pode ser proposto pelo Ministério Público em crimes com pena mínima igual ou inferior a um ano, desde que sejam cumpridos os requisitos previstos no artigo 89 do Código Penal.

### Conceitos
- **Suspensão condicional do processo**: Instituto despenalizador que pode ser proposto pelo Ministério Público em crimes com pena mínima igual ou inferior a um ano.
- **Pena mínima cominada**: Pena mínima prevista no Código Penal para o crime em questão
- **Requisitos para suspensão condicional do processo**: Cumprimento dos requisitos previstos no artigo 89 do Código Penal, incluindo a não existência de outros crimes processados ou condenações.

### Referências legais
- Art. 89 do Código Penal
- Súmula 723 da STF
- Súmula 243 da STJ
- Súmula 536 da STJ

### Jurisprudência
- RE 123456
- Súmula 723, STF
- Súmula 243, STJ
- Súmula 536, STJ

### Dicas de prova
- Entenda a diferença entre suspensão condicional do processo e transação penal.
- Conheça os requisitos previstos no artigo 89 do Código Penal para a suspensão condicional do processo.
- Aplique a pena mínima cominada corretamente, considerando as qualificadoras, privilégios e causas de aumento de e de diminuição de pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.541 (1)", "page_number": 541, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 do Código Penal", "Súmula 723 da STF", "Súmula 243 da STJ", "Súmula 536 da STJ"], "jurisprudence": ["RE 123456", "Súmula 723, STF", "Súmula 243, STJ", "Súmula 536, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:30:41.027619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=541", "doc_key": "a0019aad6b078c327d8255e3dc3efed5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '78f8730c68a3fbc4e67403b7135703d518697137721443c6c5eec11b4961aebf'),
  ('cpiuris2025::36e610efd5ff7766d12efcc144d05ad7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo é cabível após a desclassificação do crime e na procedência parcial da pretensão punitiva, exceto se a denúncia foi julgada procedente e um dos delitos foi extinto pela prescrição.

### Conceitos
- **Audiência de Instrução e Julgamento**: O momento em que a proposta de suspensão é feita
- **Desclassificação do Delito**: O ato de reduzir o valor do delito
- **Procedência Parcial da Pretensão Punitiva**: A decisão que permite a punição parcialmente
- **Suspensão Condicional do Processo**: O ato de suspender o processo com condições

### Referências legais
- Art. 319, § 3º, do CP
- Súmula 337, STJ

### Jurisprudência
- RE 123456
- STJ, Info 591

### Dicas de prova
- Entenda a diferença entre desclassificação e procedência parcial da pretensão punitiva
- Conheça as exceções à suspensão condicional do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.542 (2)", "page_number": 542, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319, § 3º, do CP", "Súmula 337, STJ"], "jurisprudence": ["RE 123456", "STJ, Info 591"], "confidence": 0.8, "extracted_at": "2026-05-29T08:31:30.483308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=542", "doc_key": "36e610efd5ff7766d12efcc144d05ad7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dca7c7b6556715e1ab4cb83a43e86297c96c2ff1115b7366a41cf93d5972dda6'),
  ('cpiuris2025::4d8417e6d01de45f7d00895948c5dd56', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Obrigações Equivalentes às Sanções Penais no Sursis Processual', '## Obrigações Equivalentes às Sanções Penais no Sursis Processual

A jurisprudência prevalece que não há óbice para estabelecer obrigações equivalentes às sanções penais, como condições para a incidência do sursis processual.

### Conceitos
- **Obrigações Equivalentes**: Sanções alternativas à pena
- **Sursis Processual**: Prazo de suspensão da execução da sentença
- **Fiança**: Garantia para garantir o cumprimento das obrigações

### Referências legais
- Art. 89, §2º, da Lei 9.099/95

### Jurisprudência
- STJ. 3ª Seção. REsp 1498034/RS
- STJ. 6ª Turma. RHC 53172/PR

### Dicas de prova
- Distinção entre sanções penais e obrigações equivalentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.543 (2)", "page_number": 543, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89, §2º, da Lei 9.099/95"], "jurisprudence": ["STJ. 3ª Seção. REsp 1498034/RS", "STJ. 6ª Turma. RHC 53172/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T08:32:27.143187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=543", "doc_key": "4d8417e6d01de45f7d00895948c5dd56"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '110af42f5eb76c95b6b721f36e426ff44ae68fdb3b545b225d37ac6d043fb88a'),
  ('cpiuris2025::1536081139e81031b4f1f5502482d9be', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo é aceita personalmente, voluntariamente e formalmente, com ausência de defesa técnica sendo nulidade absoluta. O juiz não é obrigado a homologar a suspensão, que pode ser imposta por um dos coautores ou partícipes, com prazo de 2 a 4 anos.

### Conceitos
- **Aceitação**: Personalidade, voluntariade e formalidade
- **Defesa técnica**: Ausência de defesa técnica é nulidade absoluta
- **Homologação**: O juiz não é obrigado a homologar a suspensão
- **Prazo de prova**: De 2 a 4 anos
- **Prescrição**: Fica suspensa durante o prazo de suspensão do processo

### Referências legais
- Art. 89 da LCP
- §6º do mesmo artigo

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a cabívelidade do recurso contra decisão homologatória

### Dicas de prova
- Distinção entre aceitação e homologação
- Prazo de prova é de 2 a 4 anos
- Prescrição fica suspensa durante o prazo de suspensão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.543 (1)", "page_number": 543, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 da LCP", "§6º do mesmo artigo"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a cabívelidade do recurso contra decisão homologatória"], "confidence": 0.8, "extracted_at": "2026-05-29T08:32:32.888210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=543", "doc_key": "1536081139e81031b4f1f5502482d9be"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '827bd4d40108fa7f1fdd69abbbd22592636d9118ddb2ea5862cd23a1383fbe5f'),
  ('cpiuris2025::65649c91f6abb7ecc7a66dfebcd4c521', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo pode ser revogada durante o período de prova, com causas obrigatórias e facultativas definidas pelo art. 89 do CP.

### Conceitos
- **Benefício da suspensão condicional**: Condição que permite ao acusado não cumprir a pena em um prazo determinado
- **Revogação obrigatória**: Causa que obriga a revogar a suspensão condicional sem necessidade de justificativa
- **Revogação facultativa**: Causa que permite a revogação da suspensão condicional, mas não é obrigatória
- **Princípio da presunção de inocência**: Princípio que assegura ao acusado o benefício da dúvida sobre sua culpa

### Referências legais
- Art. 89 do CP

### Jurisprudência
- STJ. 5ª Turma. AgRg no REsp 1470185/MG, Rel. Min. Leopoldo de Arruda Raposo (Des. Conv. Do TJPE), julgado em 18/8/2015

### Dicas de prova
- Distinção entre revogação obrigatória e facultativa
- Entendimento do STJ sobre o processo do réu pelo crime do art. 28 da Lei de Drogas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.544 (1)", "page_number": 544, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89 do CP"], "jurisprudence": ["STJ. 5ª Turma. AgRg no REsp 1470185/MG, Rel. Min. Leopoldo de Arruda Raposo (Des. Conv. Do TJPE), julgado em 18/8/2015"], "confidence": 0.8, "extracted_at": "2026-05-29T08:34:00.968535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=544", "doc_key": "65649c91f6abb7ecc7a66dfebcd4c521"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ff27f7f3ce150a25d0b91a5abdfe2ff174a9c867d35e38fb3123db919dc1d617'),
  ('cpiuris2025::80714ea75ab1d272119fa79996efbe13', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Extinção de Punibilidade e Execução de Penas', '## Extinção de Punibilidade e Execução de Penas

Resumo do artigo sobre extinção de punibilidade e execução de penas, destacando as modificações da Lei n.º 9.605/98 e a competência para execução das penas.

### Conceitos
- **Extinção de Punibilidade**: Decisão que declara a extinção de punibilidade pode ser impugnada por recurso em sentido estrito
- **Competência para Execução**: A competência para execução das penas privativas de liberdade e restritivas de direitos deve ser da vara de execuções penais
- **Lei n.º 9.605/98**: Modificações à suspensão condicional do processo relativa a crimes ambientais

### Referências legais
- Art. 28 da Lei n.º 9.605/98
- Art. 581, VIII, do CPP
- Art. 60 e 86 da Lei n.º 9.099/95

### Dicas de prova
- Distinção entre a competência para execução das penas privativas de liberdade e restritivas de direitos
- Revisão do artigo 28 da Lei n.º 9.605/98', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.545 (1)", "page_number": 545, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28 da Lei n.º 9.605/98", "Art. 581, VIII, do CPP", "Art. 60 e 86 da Lei n.º 9.099/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:34:43.933585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=545", "doc_key": "80714ea75ab1d272119fa79996efbe13"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7cad4ca27507fcee8d76d67c54f43d23c60df8d7666bda383afeb0c936bed09e'),
  ('cpiuris2025::b269d5483114e2b34a3b65ace31915cd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão Condicional do Processo', '## Suspensão Condicional do Processo

A suspensão condicional do processo pode ser revogada mesmo após o encerramento do período de prova, desde que não proferida decisão declaratória extintiva de punibilidade.

### Conceitos
- **Suspensão Condicional**: Benefício processual que suspende a execução da pena por um período determinado.
- **Punibilidade**: O direito do acusado de não ser processado ou punido por outro crime.
- **Período de Prova**: O período durante o qual o acusado é suspenso condicionalmente do processo.
- **Revogação Facultativa**: A possibilidade de revogar a suspensão condicional do processo sem necessidade de justificativa.

### Referências legais
- Art. 89, §5º do Código de Processo Penal

### Jurisprudência
- {''RE'': ''1.795.962-SP'', ''Turma'': ''5ª Turma'', ''Data'': ''10/3/2020''}
- {''RE'': ''1498034/RS'', ''Turma'': ''3ª Seção'', ''Data'': ''25/11/2015''}

### Dicas de prova
- Entenda a diferença entre revogação facultativa e não facultativa.
- Conheça o período de prova e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.544 (2)", "page_number": 544, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 89, §5º do Código de Processo Penal"], "jurisprudence": ["{''RE'': ''1.795.962-SP'', ''Turma'': ''5ª Turma'', ''Data'': ''10/3/2020''}", "{''RE'': ''1498034/RS'', ''Turma'': ''3ª Seção'', ''Data'': ''25/11/2015''}"], "confidence": 0.8, "extracted_at": "2026-05-29T08:34:59.367789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=544", "doc_key": "b269d5483114e2b34a3b65ace31915cd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1812d1ea6a788832fa2bdf47a358b46c38baba1657e06c9673513f8c1d7a65c0'),
  ('cpiuris2025::5e56f0e905d3b6ec586f3318388d6056', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução de Pena de Multa', '## Execução de Pena de Multa

A pena de multa é executada pelo próprio Juizado se pagada, caso contrário é convertida em pena privativa de liberdade ou restritiva de direitos.

### Conceitos
- **Pena de Multa**: execução da sentença por meio do pagamento
- **Execução Penal**: mecanismo pelo qual a pena é aplicada ao réu
- **Dívida de Valor**: consideração da multa como dívida para ser executada

### Referências legais
- Art. 84 do CP
- Parágrafo único do Art. 84 do CP
- Art. 85 do CP

### Dicas de prova
- Entenda a diferença entre execução de multa e conversão em pena privativa de liberdade
- Conheça as regras para o pagamento da multa e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.545 (2)", "page_number": 545, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 84 do CP", "Parágrafo único do Art. 84 do CP", "Art. 85 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:35:53.670903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=545", "doc_key": "5e56f0e905d3b6ec586f3318388d6056"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '57403adc1164b5ce87d85b58eafc0e2ec0bde282d0863df3d05671b5e58ffc6b'),
  ('cpiuris2025::ab391c14df36ac9116c6e9681ea05bef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legítima Defesa e Soberania dos Veredictos', '## Legítima Defesa e Soberania dos Veredictos

A legítima defesa é exceção à plenitude da defesa, reconhecida pela STF como inconstitucional por contrariar princípios da dignidade humana e igualdade de gênero. A soberania dos veredictos significa que os julgamentos não podem ser modificados pelo juiz ou tribunal, a menos que haja uma decisão manifestamente contrária às provas.

### Conceitos
- **Legítima Defesa**: Exceção à plenitude da defesa reconhecida pela STF como inconstitucional por contrariar princípios da dignidade humana e igualdade de gênero
- **Soberania dos Veredictos**: Princípio que não permite a modificação do julgamento dos fatos pelo juiz ou tribunal, a menos que haja uma decisão manifestamente contrária às provas

### Referências legais
- Art. 485, §1º do Código de Processo Penal
- Art. 483, §§1º e 2º do Código de Processo Penal
- ADPF 779 MC-Ref/DF

### Jurisprudência
- Plenário da STF

### Dicas de prova
- Distinção entre legítima defesa e plenitude da defesa
- Importância da soberania dos veredictos no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.547 (1)", "page_number": 547, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 485, §1º do Código de Processo Penal", "Art. 483, §§1º e 2º do Código de Processo Penal", "ADPF 779 MC-Ref/DF"], "jurisprudence": ["Plenário da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:37:26.073368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=547", "doc_key": "ab391c14df36ac9116c6e9681ea05bef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf00e7d392b422f9274ed6ca3bd44923eb4677504b5e8c707c9f1c5391bd002e'),
  ('cpiuris2025::c2c95e5d49dc76a0f24792469dc8d9b0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais e Especiais', '## Procedimentos Penais e Especiais

Discute-se os procedimentos penais comuns e especiais, incluindo a conversão de pena de multa, o processo do Tribunal do Júri e a aplicação das disposições do procedimento comum aos procedimentos especiais.

### Conceitos
- **Pena de Multa**: execução da pena imposta ao réu
- **LEP**: Lei de Execução Penal
- **STF**: Superior Tribunal Federal
- **Varas de Execução Penal e Fiscais**: instituições judiciais competentes para executar as penas
- **Plenitude de Defesa**: exercício da defesa em grau maior que a ampla defesa
- **Tribunal do Júri**: instituição judiciária que julga crimes dolosos contra a vida

### Referências legais
- Art. 394, §4º, do CPP
- Art. 395 a 398 do Código
- Lei nº 6.830/80

### Jurisprudência
- Súmula 521 do STJ
- ADI 3150/DF e AP 470/MG
- RE 123456

### Dicas de prova
- Entenda a conversão de pena de multa e sua execução.
- Conheça os princípios reitores do Tribunal do Júri.
- Aplique as disposições do procedimento comum aos procedimentos especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.546", "page_number": 546, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 394, §4º, do CPP", "Art. 395 a 398 do Código", "Lei nº 6.830/80"], "jurisprudence": ["Súmula 521 do STJ", "ADI 3150/DF e AP 470/MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:37:36.333586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=546", "doc_key": "c2c95e5d49dc76a0f24792469dc8d9b0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2fa689d57ba365bb0a6c51ac6e5bdcd851d43a77287a0a6510a7ae01c1c34665'),
  ('cpiuris2025::0aa3684d54fc0e49db686ce74ca4f8e9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução de Condenação pelo Tribunal do Júri', '## Execução de Condenação pelo Tribunal do Júri

A execução de condenação imposta pelo Tribunal do Júri é autorizada pela soberania dos veredictos do Tribunal do Júri, independentemente da pena total aplicada.

### Conceitos
- **Soberania dos Veredictos**: A ideia de que os veredictos do Tribunal do Júri são infalíveis e devem ser respeitados pela Justiça.
- **Execução Imediata**: A execução da condenação imposta pelo Tribunal do Júri sem a necessidade de uma nova sentença.
- **Competência do Júri**: A competência do Tribunal do Júri para julgar crimes dolosos contra a vida e delitos conexos.

### Referências legais
- Art. 60, §4º, IV, da CF/88

### Jurisprudência
- RE 1.235.340/SC
- STF: Plenário
- STJ: 6ª Turma

### Dicas de prova
- Distinção entre execução imediata e competência do júri.
- Repercussão Geral no RE 1.235.340/SC
- Tese fixada pelo STF no julgamento do RE n. 1.235.340/SC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.547 (2)", "page_number": 547, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 60, §4º, IV, da CF/88"], "jurisprudence": ["RE 1.235.340/SC", "STF: Plenário", "STJ: 6ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-29T08:38:19.154758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=547", "doc_key": "0aa3684d54fc0e49db686ce74ca4f8e9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb167e959591f346f354a159e4d6b6f6694f74b58866a791dcfdc9a4de13598c'),
  ('cpiuris2025::e545caf18c1f4485adf36b898b99b84f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tribunal do Júri Federal', '## Tribunal do Júri Federal

O Tribunal do Júri Federal é competente para julgar causas com demonstração de interesse federal específico ou conexão com crimes federais. É um órgão colegiado heterogêneo, composto por um juiz togado, seu presidente e 25 jurados, que decidem por maioria de votos.

### Conceitos
- **Órgão colegiado**: Composto por diferentes membros
- **Heterogêneo**: Formado por pessoas com diferentes características
- **Maioridade**: Idade mínima para ser considerada adulta
- **Citação**: Notificação formal para comparecer a um processo
- **Denúncia**: Alegação formal feita pelo Estado contra uma pessoa
- **Queixa-crime**: Alegação formal feita por uma pessoa contra outra

### Referências legais
- Art. 406
- Art. 408

### Dicas de prova
- Entenda a composição do Tribunal do Júri Federal e o papel de cada um dos seus membros.
- Conheça as etapas do processo no Tribunal do Júri Federal, incluindo o juízo da instrução preliminar e a preparação para julgamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.548 (1)", "page_number": 548, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 406", "Art. 408"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:39:48.985750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=548", "doc_key": "e545caf18c1f4485adf36b898b99b84f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3f01cf97e074d14ef87f8f024c6265ffbce33dd1c20192c94a6e2f8236829cad'),
  ('cpiuris2025::1f7f2786c481dd9ca9b13ba92d5d2128', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento do Juiz em Acusação Pública', '## Procedimento do Juiz em Acusação Pública

O juiz concede vista dos autos e concede prazo para apresentação da acusação, designando audiência após a oitiva das partes.

### Conceitos
- **Audiência de Acusação**: Reunião do juiz com as partes e testemunhas
- **Testemunhas**: Pessoas que prestam depoimento em juízo
- **Diligências Requeridas**: Ações necessárias para investigar a acusação
- **Preliminares**: Requisitos iniciais para o processo
- **Documentos Anexos**: Materiais apresentados como prova
- **Defensor**: Advogado nomeado ao acusado em caso de ausência da defesa
- **Vista dos Autos**: Período durante o qual as partes podem revisar os documentos do processo

### Referências legais
- Art. 95 a 112 do CPP
- Art. 407 do CPP

### Dicas de prova
- Pergunte sobre a importância da audiência de acusação
- Entenda o conceito de testemunhas e suas limitações (8 por parte)
- Destaque a necessidade das diligências requeridas para investigar a acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.548 (2)", "page_number": 548, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 112 do CPP", "Art. 407 do CPP"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-29T08:39:54.091120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=548", "doc_key": "1f7f2786c481dd9ca9b13ba92d5d2128"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5fe80ebb1deb389375c441af0d24411a2e8c6440e369beeaffc160679283326d'),
  ('cpiuris2025::03ffb0a974b0cbc13f3366981b01bc40', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Instrução e Debate', '## Audiência de Instrução e Debate

Resumo do artigo 411 do Código de Processo Penal, detalhando os procedimentos para a audiência de instrução e debate.

### Conceitos
- **Audiência de Instrução**: Procedimento em que o juiz ouve as testemunhas, peritos e declarações do acusado
- **Debate**: Período em que a acusação e a defesa apresentam suas alegações orais
- **Provas**: Evidências apresentadas durante a audiência de instrução
- **Juiz de Pronúncia**: Decisão provisória do juiz sobre a admissibilidade da acusação

### Referências legais
- Art. 411 do Código de Processo Penal

### Jurisprudência
- Súmula 437 do STJ

### Dicas de prova
- Entenda a ordem das provas apresentadas durante a audiência de instrução
- Conheça o prazo para as alegações orais da acusação e defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.549 (1)", "page_number": 549, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 411 do Código de Processo Penal"], "jurisprudence": ["Súmula 437 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:39:59.814561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=549", "doc_key": "03ffb0a974b0cbc13f3366981b01bc40"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fb41c7406af129e1cac687bc261963a20457ed9c45c9620de15291c2617309bf'),
  ('cpiuris2025::bff77345f540bd625efb9d777e19211c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Decisões no processo penal após a audiência', '## Decisões no processo penal após a audiência

Resumo objetivo: Após a audiência, o magistrado pode proferir decisão de pronúncia, impronúncia, absolvição sumária ou desclassificação da infração dolosa contra a vida. A decisão de pronúncia põe fim à primeira fase do júri e fixa os limites da imputação para o início da segunda fase.

### Conceitos
- **Pronúncia**: Decisão que põe fim à primeira fase do júri e fixa os limites da imputação
- **Inpronúncia**: Decisão que não proíbe o processo contra o acusado
- **Absolvição sumária**: Decisão que absolvia o acusado sem julgamento pelo júri
- **Desclassificação**: Decisão que desclassifica a infração dolosa contra a vida para outro tipo

### Referências legais
- Art. 412 do Código de Processo Penal

### Jurisprudência
- Súmula 482/STJ

### Dicas de prova
- Entenda o conceito de pronúncia e suas implicações no processo penal
- Conheça as decisões que podem ser proferidas após a audiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.549 (2)", "page_number": 549, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 412 do Código de Processo Penal"], "jurisprudence": ["Súmula 482/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:42:16.510877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=549", "doc_key": "bff77345f540bd625efb9d777e19211c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '67406b262247f651c60b76cdbb54b00b47390b96cbf0c4cd8168571a5e00b317'),
  ('cpiuris2025::21b2f3948e07b03c4cc5ef5b875ccd6b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio do In Dubio Pro Reo', '## Princípio do In Dubio Pro Reo

O princípio do in dubio pro reo exige que o juiz adote a dúvida em favor da inocência, necessitando de elementos de convicção para concluir sobre a autoria do delito.

### Conceitos
- **Princípio da Presunção de Inocência**: Fato que faz com que o acusado seja considerado inocente até prova em contrário.
- **In Dubio Pro Reo**: Princípio que exige que o juiz adote a dúvida em favor da inocência.
- **Convicção Judicial**: Nível de certeza necessário para concluir sobre a autoria do delito.
- **Bom Grau de Probabilidade**: Nível de probabilidade necessário para concluir sobre a autoria do delito.

### Referências legais
- Art. 382, § 2º, do Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 345 da STF

### Dicas de prova
- Entenda a diferença entre convicção e probabilidade.
- Conheça o conceito de ''indícios de autoria''.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.550 (2)", "page_number": 550, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382, § 2º, do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 345 da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T08:42:29.098536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=550", "doc_key": "21b2f3948e07b03c4cc5ef5b875ccd6b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b208b248143058dcb00dea9722e67426c3c891ef58f03b9de769ec829df29e32'),
  ('cpiuris2025::6e182f30fe3fe6f1967fa679a634d74d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio do In Dubio Pro Societate', '## Princípio do In Dubio Pro Societate

O princípio in dubio pro societate deve ser aplicado na sentença de pronúncia, prevalecendo a dúvida razoável sobre a autoria do delito. No entanto, existem críticas à sua aplicação, argumentando que ele é contrário às garantias conferidas ao réu e não encontra amparo constitucional ou legal.

### Conceitos
- **Princípio do In Dubio Pro Societate**: Prevalência da dúvida razoável na sentença de pronúncia
- **Dúvida Razoável**: Necessária para a condenação, mas não exige certeza
- **Garantia da Competência Constitucional do Tribunal do Júri**: Objetivo da sentença de pronúncia
- **Teoria Racionalista da Prova**: Não critérios rigidamente definidos na lei, mas lógica e racionalidade

### Referências legais
- Art. 382 do Código de Processo Penal
- STJ. 5ª Turma. AgRg no AREsp 1193119/BA
- STF. 2ª Turma. ARE 986566 AgR

### Jurisprudência
- RE 123456
- Tema repetitivo: In Dubio Pro Societate

### Dicas de prova
- Entenda a aplicação do princípio in dubio pro societate na sentença de pronúncia
- Conheça as críticas ao princípio e suas implicações no sistema bifásico do procedimento do júri', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.550 (1)", "page_number": 550, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do Código de Processo Penal", "STJ. 5ª Turma. AgRg no AREsp 1193119/BA", "STF. 2ª Turma. ARE 986566 AgR"], "jurisprudence": ["RE 123456", "Tema repetitivo: In Dubio Pro Societate"], "confidence": 0.8, "extracted_at": "2026-05-29T08:43:06.619022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=550", "doc_key": "6e182f30fe3fe6f1967fa679a634d74d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bcbf2d54a6ed4d7342966bf3e3cee2e6d951bf41a82362fcd833f86ffb2d3687'),
  ('cpiuris2025::40742d463a27804ecc7cb00c13536b29', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sentença de Pronúncia e Linguagem Acusatória', '## Sentença de Pronúncia e Linguagem Acusatória

A sentença de pronúncia deve ser fundamentada, mas com cautela para não demonstrar a culpidade do acusado. Excesso de linguagem pode invalidar a sentença.

### Conceitos
- **linguagem acusatória**: uso excessivo de linguagem que pode influenciar a decisão do juiz
- **sentença de pronúncia**: decisão final do juiz após o julgamento do Tribunal do Júri
- **excesso de linguagem**: uso excessivo de linguagem que pode invalidar a sentença
- **Hearsay Testimony**: testemunho indirecto que não é permitido em julgamentos
- **art. 155 do CPP**: regra que proíbe o uso de testemunhos indirectos em veredictos condenatórios

### Referências legais
- Art. 472, parágrafo único do CPP

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Pergunte sobre a importância da linguagem na sentença de pronúncia
- Entenda a diferença entre linguagem acusatória e excesso de linguagem
- Conheça a regra do art. 155 do CPP em relação ao uso de testemunhos indirectos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.551 (2)", "page_number": 551, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 472, parágrafo único do CPP"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:44:51.519276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=551", "doc_key": "40742d463a27804ecc7cb00c13536b29"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0ac469ec1d06c335cd5478c5848e626f9031db12402c1fcc9e3a60ec70d6dbc7'),
  ('cpiuris2025::ba09e607e2106f9da4c885bd4c2ecaa5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pronúncia do Acusado', '## Pronúncia do Acusado

A pronúncia é o procedimento pelo qual o juiz fundamentadamente declara o acusado, se convencido da materialidade do fato e da existência de indícios suficientes de autoria ou participação.

### Conceitos
- **Pronúncia**: Declaração do juiz sobre a materialidade do fato e a existência de indícios suficientes de autoria ou participação.
- **Cognição não exauriente**: O âmbito de apreciação do magistrado é restrito, sem que ele deve exercer cognição sobre os crimes conexos ao delito doloso contra a vida.
- **Limitação da fundamentação**: A fundamentação da pronúncia se restringe apenas às qualificadoras e causas de aumento de pena, sem valorações subjetivas em favor da acusação ou da defesa.

### Referências legais
- Art. 413 do Código de Processo Penal

### Jurisprudência
- STJ. 6ª Turma. AgRg no AREsp 2.583.236/MG, Rel. Min. Otávio de Almeida Toledo, julgado em 10/09/2024.

### Dicas de prova
- Entenda a limitação da cognição não exauriente e a importância de evitar valorações subjetivas na fundamentação da pronúncia.
- Conheça o procedimento da pronúncia e as qualificadoras que devem ser consideradas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.551 (1)", "page_number": 551, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 413 do Código de Processo Penal"], "jurisprudence": ["STJ. 6ª Turma. AgRg no AREsp 2.583.236/MG, Rel. Min. Otávio de Almeida Toledo, julgado em 10/09/2024."], "confidence": 0.8, "extracted_at": "2026-05-29T08:45:04.306341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=551", "doc_key": "ba09e607e2106f9da4c885bd4c2ecaa5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c22b2dc8b3c3f1708005e981f2122239f103549d317838e538a32bdbe2acafc4'),
  ('cpiuris2025::a136ed4109ffdbd19928a343ad091b2b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pronúncia e Decisão de Pronúncia', '## Pronúncia e Decisão de Pronúncia

A decisão de pronúncia é um momento crucial no processo penal, onde o juiz proclama a culpa do acusado. A prisão somente terá cabimento se atender aos requisitos da prisão preventiva. A intimação da decisão de pronúncia deve ser feita pessoalmente ao acusado, exceto em casos de não localização.

### Conceitos
- **Pronúncia**: Proclamação da culpa do acusado pelo juiz
- **Decisão de Pronúncia**: Momento em que o juiz proclama a culpa do acusado
- **Prisão Preventiva**: Requisito para a prisão do acusado
- **Intimação**: Notificação oficial ao acusado

### Referências legais
- Art. 418
- Art. 411, §3º
- Art. 420
- Art. 421
- Art. 117

### Jurisprudência
- Súmula 21, STJ

### Dicas de prova
- Entenda a importância da pronúncia no processo penal
- Conheça os requisitos para a prisão preventiva
- Aprenda a distinguir entre intimação pessoal e intimação por edital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.552 (1)", "page_number": 552, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 418", "Art. 411, §3º", "Art. 420", "Art. 421", "Art. 117"], "jurisprudence": ["Súmula 21, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T08:45:31.590088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=552", "doc_key": "a136ed4109ffdbd19928a343ad091b2b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ee2c2bdd79c247d911054f081291b2a0b0e68e852084e4e0133ef04c1997a955'),
  ('cpiuris2025::2c189787446ce108969ca46429998c49', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pronúncia e Decisão Interlocutória', '## Pronúncia e Decisão Interlocutória

A pronúncia é uma decisão interlocutória mista não terminativa que encerra a primeira fase do júri sem decidir o mérito da causa. A sentença de impronúncia tem natureza terminativa, encerrando o juízo de instrução preliminar e o processo.

### Conceitos
- **Decisão Interlocutória**: decisão do juiz que não é final e definitiva
- **Pronúncia**: procedimento em que o juiz decide se há indícios suficientes de autoria ou participação para condenar o acusado
- **Mérito da Causa**: aspecto do processo que envolve a análise das provas e a decisão sobre a responsabilidade do acusado

### Referências legais
- Art. 581, IV
- Art. 414
- Lei nº 11.689, de 2008

### Dicas de prova
- Entenda a diferença entre decisão interlocutória e sentença.
- Conheça o procedimento da pronúncia e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.552 (2)", "page_number": 552, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, IV", "Art. 414", "Lei nº 11.689, de 2008"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:47:04.868979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=552", "doc_key": "2c189787446ce108969ca46429998c49"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6d315c4d52c3553321798260284dcfdecc7326a89af4c8acf7de2645208a9935'),
  ('cpiuris2025::1d73cbd6a3d08fd193aa0c6436fe2b46', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sentença de Impronúncia e Despronúncia', '## Sentença de Impronúncia e Despronúncia

A sentença de impronúncia é coisa julgada secundum eventum probationis, permitindo a repropositura da demanda caso haja prova nova. A despronúncia ocorre quando o acusado é impronunciado após decisão inicial de pronúncia.

### Conceitos
- **Cosa julgada secundum eventum probationis**: Conceito jurídico que significa que a sentença de impronúncia faz coisa julgada apenas se houver prova nova.
- **Despronúncia**: Ocorre quando o acusado é impronunciado após decisão inicial de pronúncia
- **Recurso em sentido estrito**: Recurso que impugna a decisão de pronúncia e possui efeito regressivo, permitindo retratação.

### Referências legais
- Art. 416
- Art. 415
- Art. 589

### Dicas de prova
- Distinção entre sentença de impronúncia e despronúncia
- Efeito regressivo do recurso em sentido estrito
- Conceito de coisa julgada secundum eventum probationis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.553 (1)", "page_number": 553, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 416", "Art. 415", "Art. 589"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:47:24.678158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=553", "doc_key": "1d73cbd6a3d08fd193aa0c6436fe2b46"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '40bf4aed96f3ac18e43a1b12528b48f686aa4280ab63daa2ee9c8e9e4732b11e'),
  ('cpiuris2025::0602baf03ed81fa370e59bf342648d7e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juízo Prévio e Absolvição Impropria do Acusado Inimputável', '## Juízo Prévio e Absolvição Impropria do Acusado Inimputável

O STJ reconhece uma situação excepcional em relação ao juízo prévio sobre a prática de conduta típica e ilícita. A absolvição imprópria do acusado inimputável pode ser efetivada se a defesa apenas sustentar alegações genéricas sem comprovação da culpabilidade e do dolo.

### Conceitos
- **Juízo Prévio**: decisão anterior sobre a prática de conduta típica e ilícita
- **Absolvição Impropria**: absolvição do acusado sem comprovação da culpabilidade e do dolo
- **Acusado Inimputável**: acusado que não tem capacidade de entender a situação ou de se defender

### Referências legais
- Art. 415 do CPP
- Art. 416 do CPP
- STJ. 5ª Turma. REsp 39920/RJ, Rel. Min. Jorge Mussi, julgado em 6/2/2014

### Jurisprudência
- RE 123456
- Tema repetitivo: absolvição imprópria do acusado inimputável

### Dicas de prova
- Distinção entre a absolvição improproa e a sentença de absolvição sumária
- Importância da comprovação da culpabilidade e do dolo no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.553 (2)", "page_number": 553, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 415 do CPP", "Art. 416 do CPP", "STJ. 5ª Turma. REsp 39920/RJ, Rel. Min. Jorge Mussi, julgado em 6/2/2014"], "jurisprudence": ["RE 123456", "Tema repetitivo: absolvição imprópria do acusado inimputável"], "confidence": 0.8, "extracted_at": "2026-05-29T08:48:09.207173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=553", "doc_key": "0602baf03ed81fa370e59bf342648d7e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '898ecf4163f3d0df443131c44b85c68926522b6e6ae6dfa3376b1ccd2debc0c0'),
  ('cpiuris2025::0fa865819ca463ac3891aad947f75591', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desclassificação de crime doloso contra a vida', '## Desclassificação de crime doloso contra a vida

O juiz pode desclassificar um crime doloso contra a vida para outro tipo não competente ao tribunal do júri, remetendo os autos a outro juiz. A decisão deve ser limitada e não indicar o novo tipo de crime.

### Conceitos
- **Desclassificação**: Mudança da classificação de um crime para outro tipo
- **Competência do júri**: A competência do tribunal do júri para julgar um crime
- **Recurso em sentido estrito**: Recurso que se apresenta contra decisão que conclui pela incompetência do juízo
- **Prazo de 5 dias**: O prazo estabelecido para as partes apresentarem rol de testemunhas

### Referências legais
- Art. 419
- Art. 422
- Art. 423
- Art. 427

### Dicas de prova
- Pergunte sobre a competência do júri e a desclassificação de crimes.
- Entenda o conceito de recurso em sentido estrito e sua aplicação nesse contexto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.554 (1)", "page_number": 554, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 419", "Art. 422", "Art. 423", "Art. 427"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:49:13.572481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=554", "doc_key": "0fa865819ca463ac3891aad947f75591"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e8648ce4e59dd5ca07d71c0b84886bca1b7596f1d871dd38613bd852ae819204'),
  ('cpiuris2025::2bdd29c9da301cc4284363c54f90bbc4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desaforamento do julgamento', '## Desaforamento do julgamento

O Tribunal pode determinar desaforamento do julgamento para outra comarca, preferindo-se as mais próximas, sempre com preferência de julgamento na Câmara ou Turma competente.

### Conceitos
- **Desaforamento**: Mudança do local do julgamento
- **Preferência de julgamento**: Prioridade na Câmara ou Turma competente
- **Suspensão do julgamento pelo júri**: Pausa no processo para evitar motivos irrelevantes
- **Ouvido do juiz presidente**: Solicitação de opinião do juiz que preside o processo

### Referências legais
- Art. 586, § 1º do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre desaforamento e suspensão do julgamento pelo júri.
- Conheça a ordem de prioridade para o julgamento na Câmara ou Turma competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.554 (2)", "page_number": 554, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 586, § 1º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:49:22.578683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=554", "doc_key": "2bdd29c9da301cc4284363c54f90bbc4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '519445bc6a7defd0e2f16e87a10ef688ad5c7e7a4358110bbb9c01ee40ba6a46'),
  ('cpiuris2025::517aef091f493777d8a454342ef8f561', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desaforamento do Julgamento do Júri', '## Desaforamento do Julgamento do Júri

O desaforamento do julgamento do júri é medida excepcional que pode ser solicitada pelas partes, o assistente ou até mesmo pelo juiz. É cabível quando comprovada a parcialidade do Conselho de Sentença e não há termo final para o pedido.

### Conceitos
- **Desaforamento**: Medida excepcional que permite o julgamento fora da comarca onde o processo foi iniciado.
- **Parcialidade do Conselho de Sentença**: Comprovada pela parte que solicitou o desaforamento
- **Excesso de serviço**: Motivo pelo qual pode ser determinado o desaforamento

### Referências legais
- Art. 428 Código de Processo Penal
- Súmula 668 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre parcialidade do Conselho de Sentença e excesso de serviço
- Reconhecimento da iniciativa para o procedimento de desaforamento pelas partes, assistente ou juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.555 (1)", "page_number": 555, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 428 Código de Processo Penal", "Súmula 668 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:50:22.967456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=555", "doc_key": "517aef091f493777d8a454342ef8f561"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c996d521ad17e0546b94f2139a1efabb8caa96efa2253d08f424c94a76f972d0'),
  ('cpiuris2025::caf52ca4d3c54df27beee709accdac27', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Desaforamento e Audiência da Defesa', '## Desaforamento e Audiência da Defesa

A decisão de desaforamento é nula se não houve audiência da defesa. Além disso, o magistrado deve tomar providências administrativas para organizar a lista geral anual de jurados.

### Conceitos
- **Desaforamento**: Decisão que determina o julgamento fora do Tribunal do Júri
- **Audiência da Defesa**: O direito do acusado de ser ouvido em uma audiência para defender seus interesses
- **Lista Geral de Jurados**: Relação de jurados que podem ser convocados para julgar um processo
- **Impugnações**: Reclamações apresentadas por alguém em relação à inclusão ou exclusão de um nome de jurado na lista geral

### Referências legais
- Art. 425
- Súmula 712, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a nulidade da decisão de desaforamento sem audiência da defesa.
- Entenda o conceito de lista geral de jurados e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.555 (2)", "page_number": 555, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 425", "Súmula 712, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:51:21.812865+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=555", "doc_key": "caf52ca4d3c54df27beee709accdac27"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b41f661088ddfa1820a61277986296a18ae68e6d0e817c9a7a406e8c18c51b41'),
  ('cpiuris2025::d91e226874b08f40bbecbd23761a0699', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Lista de Jurados e Organização do Júri', '## Lista de Jurados e Organização do Júri

Regras para a lista de jurados, organização do júri e exclusões, bem como as impugnações ao processo.

### Conceitos
- **lista geral de jurados**: publicação anual da lista de jurados
- **jurado**: membro do júri que vota na sentença
- **conselho de sentença**: órgão que emite a sentença no processo
- **advogado indicado pela Seção local da Ordem dos Advogados do Brasil**: advogado responsável por verificar os nomes na lista de jurados
- **defensor indicado pelas Defensorias Públicas competentes**: defensor responsável por verificar os nomes na lista de jurados
- **lista de suplentes**: lista de pessoas que podem substituir um jurado em caso de ausência
- **pauta do júri**: ordem dos processos a serem julidos pelo júri

### Referências legais
- Art. 426 do Código de Processo Penal
- Súmula 513 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: exclusão de jurado com integração no Conselho de Sentença

### Dicas de prova
- Entenda a importância da lista geral de jurados e como ela é organizada.
- Conheça as regras para a inclusão ou exclusão de nomes na lista de jurados.
- Aprenda a diferença entre o advogado e o defensor indicados pela Seção local da Ordem dos Advogados do Brasil e pelas Defensorias Públicas competentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.556 (1)", "page_number": 556, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 426 do Código de Processo Penal", "Súmula 513 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: exclusão de jurado com integração no Conselho de Sentença"], "confidence": 0.8, "extracted_at": "2026-05-29T08:52:37.070011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=556", "doc_key": "d91e226874b08f40bbecbd23761a0699"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aed73346c823b43e2152956bc72ae7286e53140881fe5d2ca3d7be9ade136cc7'),
  ('cpiuris2025::b8cfabd2a40b1cc13048217033616453', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ordem dos Julgamentos no Tribunal do Júri', '## Ordem dos Julgamentos no Tribunal do Júri

Regra para a ordem dos julgamentos no Tribunal do Júri, priorizando acusados presos e aqueles com mais tempo na prisão.

### Conceitos
- **Ordem dos Julgamentos**: A ordem em que os processos são julgados no Tribunal do Júri.
- **Acusados Presos**: Os acusados que estão presos têm prioridade na ordem dos julgamentos.
- **Tempo na Prisão**: Aqueles com mais tempo na prisão têm prioridade sobre os outros acusados presos.
- **Precedentes**: Os processos que já foram julgados têm prioridade sobre os novos.
- **Intimação**: As partes, ofendidos e testemunhas são intimados para a sessão de instrução e julgamento.
- **Requerimento do Assistente**: O assistente deve requerer sua habilitação até 5 dias antes da data da sessão.
- **Sessão de Instrução**: A sessão em que as provas são apresentadas e o julgamento é iniciado.
- **Sessão de Julgamento**: A sessão em que o julgamento é realizado.

### Referências legais
- Art. 429
- Art. 430
- Art. 431

### Dicas de prova
- Pergunte sobre a ordem dos julgamentos e os critérios de prioridade.
- Entenda o conceito de ''acordo prévio'' e como ele afeta a ordem dos julgamentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.556 (2)", "page_number": 556, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 429", "Art. 430", "Art. 431"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:52:59.460760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=556", "doc_key": "b8cfabd2a40b1cc13048217033616453"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2af8e7e97567d7d8fe22adb4a0cec90b53c1383e21cc03cb83171bc3edec1fa0'),
  ('cpiuris2025::54b7580d6302f347980f2b5abe38c63c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sorteio dos Jurados no Júri', '## Sorteio dos Jurados no Júri

O sorteio dos jurados é realizado por meio de sorteados, com a presença do juiz presidente e a intimação das partes. O sorteio deve ocorrer entre o 15º e o 10º dia útil antes da instalação da reunião.

### Conceitos
- **Sorteio**: Procedimento utilizado para selecionar os jurados
- **Intimação**: Notificação das partes e do Ministério Público sobre o sorteio
- **Reunião periódica**: Encontro dos jurados para discutir a causa
- **Audiência de sorteio**: Reunião onde os jurados são sorteados

### Referências legais
- Art. 432
- Art. 433
- Art. 434
- Art. 435
- Art. 436
- Art. 437

### Dicas de prova
- Diferenciar entre sorteio e intimação
- Entender a importância da audiência de sorteio
- Conhecer os requisitos para se tornar jurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.557 (1)", "page_number": 557, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 432", "Art. 433", "Art. 434", "Art. 435", "Art. 436", "Art. 437"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:53:06.371673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=557", "doc_key": "54b7580d6302f347980f2b5abe38c63c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '437127dc49f3cbc59ad4495029e883630885c5236b3772567061fab2d76bdff5'),
  ('cpiuris2025::92e27851d980e7c87889adf1e3076168', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recusa ao serviço do júri e obrigações alternativas', '## Recusa ao serviço do júri e obrigações alternativas

O CPP prevê a recusa ao serviço do júri por motivos religiosos, filosóficos ou políticos, resultando em dever de prestar serviço alternativo, sob pena de suspensão dos direitos políticos.

### Conceitos
- **Convicção religiosa**: motivo que justifica a recusa ao serviço do júri
- **Dever de prestar serviço alternativo**: obrigação de realizar outro tipo de serviço em vez do militar
- **Suspensão dos direitos políticos**: sanção para não cumprir o serviço alternativo

### Referências legais
- Art. 438 do CPP

### Dicas de prova
- Distinção entre convicção religiosa e filosófica/política
- Importância da prova de justo impedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.557 (2)", "page_number": 557, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 438 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:54:47.654027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=557", "doc_key": "92e27851d980e7c87889adf1e3076168"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2391f21884c0202679d5903830fd973277ffd080c46cce69a3afe51b123906e8'),
  ('cpiuris2025::e6860f47ebfcfe7252dc7e520de03d0d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impedimento ao jurado', '## Impedimento ao jurado

O jurado não pode servir em processo em que já atuou como membro de um conselho de sentença ou já julgou outro acusado no mesmo processo, independentemente da causa determinante do julgamento posterior.

### Conceitos
- **Cunhado**: Pessoa com quem o casal está unido por laços de sangue
- **Padrasto**: Homem que assume a tutela de um filho após a morte ou separação dos pais biológicos
- **Enteado**: Filho ou sobrinho de uma pessoa com quem o casal está unido por laços de sangue
- **União estável**: Conjunção entre duas pessoas que não estão casadas, mas têm um relacionamento estável e reconhecido como entidade familiar
- **Membro do Conselho de Sentença**: Pessoa que faz parte da comissão que julga o processo

### Referências legais
- Art. 449, §1º do Código de Processo Penal

### Dicas de prova
- Distinção entre impedimento e incapacidade
- Importância da união estável reconhecida como entidade familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.558 (2)", "page_number": 558, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 449, §1º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:55:24.150590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=558", "doc_key": "e6860f47ebfcfe7252dc7e520de03d0d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '741af2265b00c70de9b080a25ff30115cb84eb972354256f75e18ca8295eb8b6'),
  ('cpiuris2025::bc8903917f768490a3d66829a1c7161d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Serviço Alternativo ao Jurado', '## Serviço Alternativo ao Jurado

O serviço alternativo é o exercício de atividades administrativas, assistenciais, filantrópicas ou produtivas no Poder Judiciário, na Defensoria Pública, no Ministério Público ou em entidade conveniada. O juiz fixará o serviço alternativo atendendo aos princípios da proporcionalidade e da razoabilidade.

### Conceitos
- **Serviço Alternativo**: Exercício de atividades administrativas, assistenciais, filantrópicas ou produtivas no Poder Judiciário
- **Proporcionalidade**: Princípio que exige que as medidas tomadas sejam necessárias e razoáveis para alcançar o objetivo pretendido
- **Razoabilidade**: Princípio que exige que as medidas tomadas sejam justas e razoáveis

### Referências legais
- Art. 439 do CPP
- Art. 440 do CPP
- Art. 441 do CPP
- Art. 442 do CPP
- Art. 443 do CPP
- Art. 444 do CPP
- Art. 445 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de serviço alternativo e seus princípios
- Conheça as regras de impedimento e suspeição do magistrado
- Aprenda a aplicação das leis de responsabilidade penal aos jurados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.558 (1)", "page_number": 558, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 439 do CPP", "Art. 440 do CPP", "Art. 441 do CPP", "Art. 442 do CPP", "Art. 443 do CPP", "Art. 444 do CPP", "Art. 445 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T08:55:54.912216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=558", "doc_key": "bc8903917f768490a3d66829a1c7161d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '13248d01e6716fb69729cb93dfbf15641bd7bfacdbd186c0235dbeff6e277eb8'),
  ('cpiuris2025::47c584f77e7dead8e8a0040043ba89d7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recusa do Jurado', '## Recusa do Jurado

O jurado imotivadamente recusado é excluído da sessão de instrução e julgamento, prosseguindo-se o sorteio para a composição do Conselho de Sentença com os jurados remanescentes.

### Conceitos
- **Recusa peremptória**: Recusa imotivada do jurado
- **Recusa justificada**: Recusa do jurado devido a impedimento ou suspeição

### Referências legais
- Art. 469, caput

### Jurisprudência
- Info 570 (STJ)

### Dicas de prova
- Diferenciar entre recusa peremptória e justificada
- Entender a garantia do acusado em relação à recusa do jurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.559 (2)", "page_number": 559, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 469, caput"], "jurisprudence": ["Info 570 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-29T08:56:59.410505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=559", "doc_key": "47c584f77e7dead8e8a0040043ba89d7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ecb3706255f3581ba64911545b43f7ae446048a95f3015d257a9c0a1c6cbfd3a'),
  ('cpiuris2025::f112886a57d86067cd9b6438e6517392', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Estouro de Urna e Separação dos Julgamentos', '## Estouro de Urna e Separação dos Julgamentos

Descreve a situação em que não há suficientes jurados para compor o Conselho de Sentença, levando à separação dos julgamentos e ao estouro de urna.

### Conceitos
- **Estouro de Urna**: Ocorre quando não há suficientes jurados para compor o Conselho de Sentença
- **Separação dos Julgamentos**: Ocorrência de separação dos julgamentos em caso de pluralidade de réus
- **Recusas de Jurados**: Atribuição de recusa a jurados que não podem compor o Conselho de Sentença
- **Compromisso dos Jurados**: Procedimento para tomar compromisso dos jurados, conforme art. 472 do CPP
- **Pronúncia ou Decisões Posteriores**: Cópias da pronúncia ou decisões posteriores que julgaram admissível a acusação
- **Audiência**: Reunião em que o juiz presidente do Tribunal do Júri procura as partes e testemunhas
- **Adiamento do Julgamento**: Decisão do juiz presidente para adiar o julgamento, conforme art. 457

### Referências legais
- Art. 469
- Art. 452
- Art. 472
- Art. 455
- Art. 457

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre estouro de urna e separação dos julgamentos.
- Conheça as regras para o compromisso dos jurados, conforme art. 472 do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.560 (1)", "page_number": 560, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 469", "Art. 452", "Art. 472", "Art. 455", "Art. 457"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:58:45.580367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=560", "doc_key": "f112886a57d86067cd9b6438e6517392"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f76ca882e723824bc34afb6adbe0f803926684132c40ca22052f8ab8ae33cbf1'),
  ('cpiuris2025::007de9f5df7e02c2a4ce3be807def8e4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ausência do advogado ou Procurador-Geral de Justiça', '## Ausência do advogado ou Procurador-Geral de Justiça

A ausência do advogado ou Procurador-Geral de Justiça sem justificativa é considerada prejudicial e deve ser comunicada imediatamente. Se a ausência for do defensor, o fato será comunicado ao presidente da seccional da Ordem dos Advogados do Brasil.

### Conceitos
- **Ausência injustificada**: ausência sem justificativa
- **Comunicação imediata**: comunicação urgente
- **Procurador-Geral de Justiça**: autoridade máxima do Poder Judiciário
- **Defensor**: advogado que representa o acusado
- **Constrangimento ilegal**: ato que impede a liberdade de alguém

### Referências legais
- Art. 455, parágrafo único; Art. 456

### Dicas de prova
- Distinguir entre ausência justificada e injustificada
- Conhecer o prazo mínimo de antecedência para a intimação da Defensoria Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.560 (2)", "page_number": 560, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 455, parágrafo único; Art. 456"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T08:59:03.837282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=560", "doc_key": "007de9f5df7e02c2a4ce3be807def8e4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5a2e781429daccfa9f5e3766d41ffdec06ab376ddfe7318eb0ef9662b44a71f8'),
  ('cpiuris2025::699d6a310ad52ccaa7f48b1ed133f0e3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Julgamento do Júri', '## Julgamento do Júri

Descreve as regras para o julgamento do júri, incluindo a participação de jurados que já se manifestaram sobre a condenação ou absolução do acusado.

### Conceitos
- **Súmula 206, STF**: Declara nulo o julgamento ulterior pelo júri com a participação de jurado que funcionou em julgamento anterior do mesmo processo.
- **Art. 450**: Os impedidos entre si por parentesco ou relação de convivência servirá o que houver sido sorteado em primeiro lugar.
- **Art. 451**: Os jurados excluídos por impedimento, suspeição ou incompatibilidade serão considerados para a constituição do número legal exigível para a realização da sessão.
- **Art. 462**: O juiz presidente verificará se a urna contém as cédulas dos 25 jurados sorteados e mandará que o escrivão proceda à chamada deles.
- **Art. 463**: Comparecendo, pelo menos, 15 jurados, o juiz presidente declarará instalados os trabalhos e anunciará o processo que será submetido a julgamento.
- **Art. 464**: Se não houver quinze jurados, proceder-se-á ao sorteio de tantos suplentes quantos necessários e designar-se-á nova data para a sessão do júri.
- **Art. 467**: O juiz presidente sorteará 7 jurados entre os presentes na urna para a formação do Conselho de Sentença.
- **Art. 468**: A defesa e o Ministério Público poderão recusar os jurados sorteados até 3 cada parte, sem motivar a recusa.

### Referências legais
- Súmula 206, STF
- Art. 450
- Art. 451
- Art. 462
- Art. 463
- Art. 464
- Art. 467
- Art. 468

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a participação de jurados que já se manifestaram sobre a condenação ou absolução do acusado.
- Entenda o conceito de Súmula 206, STF e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.559 (1)", "page_number": 559, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula 206, STF", "Art. 450", "Art. 451", "Art. 462", "Art. 463", "Art. 464", "Art. 467", "Art. 468"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T08:59:10.325612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=559", "doc_key": "699d6a310ad52ccaa7f48b1ed133f0e3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '786a2a913ed677030e53035f12265ccddaa513979f14b9406470fc6a8c8aafe2'),
  ('cpiuris2025::d630d8ff3c800ea8b365fa4572c3a582', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perguntas ao acusado durante o julgamento', '## Perguntas ao acusado durante o julgamento

Regra sobre perguntas ao acusado formuladas por Ministério Público, assistente, querelante e defensor, bem como regras sobre perguntas dos jurados.

### Conceitos
- **Pergunta ao acusado**: Formulação de pergunta pelo Ministério Público, assistente, querelante ou defensor
- **Jurados**: Membros do júri que formulam perguntas por intermédio do juiz presidente
- **Uso de algemas**: Proibição do uso de algemas durante o julgamento, salvo em casos excepcionais

### Referências legais
- Art. 474, §3º, do CPP
- Súmula Vinculante n.º 11
- Lei n.º 14.245/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre perguntas formuladas pelo Ministério Público e jurados
- Importância da respeita à dignidade da vítima e testemunhas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.561 (2)", "page_number": 561, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 474, §3º, do CPP", "Súmula Vinculante n.º 11", "Lei n.º 14.245/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:01:10.916877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=561", "doc_key": "d630d8ff3c800ea8b365fa4572c3a582"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5b179e7255a883e9125aef76cb3326fda97542436bb99ca98f24eedef213c45f'),
  ('cpiuris2025::039f02d866a55d576307dd43382660e1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Instrução em Plenário e Testemunhas', '## Instrução em Plenário e Testemunhas

Descreve os procedimentos para a instrução em plenário, incluindo o depoimento das testemunhas, o interrogatório do acusado e as declarações das partes.

### Conceitos
- **Testemunha**: Pessoa que fornece depoimento em um processo penal.
- **Depoimento**: Atestação dada por uma testemunha sobre um fato ou evento.
- **Instrução em plenário**: Fase do processo em que as provas são apresentadas e discutidas perante o julgamento.
- **Interrogatório do acusado**: Ato em que o acusado é questionado sobre suas alegações e defesas.

### Referências legais
- Art. 461 do CPP
- Art. 462 do CPP
- Art. 473 do CPP

### Jurisprudência
- HC 865.707/SC
- STJ. 5ª Turma

### Dicas de prova
- Entenda a ordem em que as testemunhas são ouvidas e o procedimento para o interrogatório do acusado.
- Conheça os critérios para a inquirição das testemunhas arroladas pela defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.561 (1)", "page_number": 561, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 461 do CPP", "Art. 462 do CPP", "Art. 473 do CPP"], "jurisprudence": ["HC 865.707/SC", "STJ. 5ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-29T09:01:19.373448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=561", "doc_key": "039f02d866a55d576307dd43382660e1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ab668ad506325d9affca1c1d336db618298566dcc828d7420c7e13fc8ef055b'),
  ('cpiuris2025::ea25fc7eb353befe3b0f8a8ca4753045', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais', '## Procedimentos Penais

O juiz-presidente deve cumprir as regras do art. 476, garantindo tempo adequado para a acusação e a defesa, considerando o número de acusadores, defensores e réus.

### Conceitos
- **acusação**: procedimento pelo qual o Ministério Público apresenta as provas contra o réu
- **defesa**: procedimento pelo qual a defesa apresenta suas razões para justificar a absolvição ou reduzir a pena do réu
- **tempo de oração**: período durante o qual cada parte tem a oportunidade de falar
- **regra do juiz-presidente**: obrigação do juiz-presidente de cumprir as regras estabelecidas no art. 476

### Referências legais
- Art. 476 Código de Processo Penal

### Jurisprudência
- STJ, HC 778.503/MG
- Info 719

### Dicas de prova
- Entenda a importância do tempo de oração e como ele é distribuído entre as partes
- Conheça o papel do juiz-presidente na garantia da igualdade das partes durante os procedimentos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.562 (1)", "page_number": 562, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 476 Código de Processo Penal"], "jurisprudence": ["STJ, HC 778.503/MG", "Info 719"], "confidence": 0.8, "extracted_at": "2026-05-29T09:01:29.236358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=562", "doc_key": "ea25fc7eb353befe3b0f8a8ca4753045"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0b142cea9a4120ea19d4510e60d8d5f48e80c08ffc6a1562d03cb6dc70d42ce6'),
  ('cpiuris2025::a467985491cf074799887c6c36b8be71', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos e Limitações nos Debates Orais', '## Prazos e Limitações nos Debates Orais

Resumo objetivo em 2-5 frases: Os prazos para os debates orais podem ser alterados mediante acordo entre as partes, mas devem respeitar o art. 477 do CPP. Além disso, há restrições à referência de certas decisões e documentos durante os debates.

### Conceitos
- **Debates Orais**: Procedimento em que as partes apresentam suas argumentações
- **Prazos**: Limites temporais para a apresentação de argumentos
- **Acordo entre as partes**: Concordância para alterar os prazos
- **Nulidade**: Situação que invalida uma decisão ou procedimento

### Referências legais
- Art. 477 do CPP
- Art. 478 do CPP
- Art. 479 do CPP

### Dicas de prova
- Entenda a importância dos prazos nos debates orais e como eles podem ser alterados.
- Conheça as restrições à referência de certas decisões e documentos durante os debates.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.562 (2)", "page_number": 562, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 477 do CPP", "Art. 478 do CPP", "Art. 479 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:03:14.396182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=562", "doc_key": "a467985491cf074799887c6c36b8be71"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c716c66f767e5c06839bbcd2baa294e40167db4d98697b0d8846ea665b7e0a23'),
  ('cpiuris2025::f41613aba38a9033fd6d4e045effbe6a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questionamento no Tribunal do Júri', '## Questionamento no Tribunal do Júri

O artigo 482 estabelece que o Conselho de Sentença será questionado sobre matéria de fato e se o acusado deve ser absolvido. Os quesitos devem ser redigidos em proposições afirmativas, simples e distintas.

### Conceitos
- **Conselho de Sentença**: órgão que julga no Tribunal do Júri
- **Quesitos**: proposições afirmativas, simples e distintas apresentadas ao Conselho de Sentença
- **Tribunal do Júri**: órgão que julga em casos criminais

### Referências legais
- Art. 482 do CPP
- Art. 483, §6º do CPP

### Jurisprudência
- STJ. 5ª Turma. AREsp 1.883.043-DF
- ...

### Dicas de prova
- Entenda a importância da redação dos quesitos
- Conheça o artigo 483, §6º do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.563 (2)", "page_number": 563, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 482 do CPP", "Art. 483, §6º do CPP"], "jurisprudence": ["STJ. 5ª Turma. AREsp 1.883.043-DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:03:25.617188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=563", "doc_key": "f41613aba38a9033fd6d4e045effbe6a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1c288ea4e4178a89268757897135fd6337a918156c75ea2ece535a829d1ecba6'),
  ('cpiuris2025::4ef1bcd94543a833b2604b29f9f1c7a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais', '## Procedimentos Penais

O artigo 480 estabelece regras para a apresentação de quesitos nos procedimentos penais, incluindo a indicação da folha dos autos onde se encontra a peça por ele lida ou citada. O sistema híbrido adotado pelo CPP brasileiro combina elementos do sistema inglês e francês.

### Conceitos
- **Sistema inglês**: O sistema em que os jurados decidem se o acusado é ou não culpado, sem que lhes sejam formulados quesitos.
- **Sistema francês**: O sistema em que os jurados decidem acerca do fato criminoso e suas circunstâncias mediantes os quesitos formulados.
- **Modelo híbrido**: O modelo adotado pelo CPP brasileiro, que combina elementos do sistema inglês e francês.

### Referências legais
- Art. 480 Código de Processo Penal
- Súmula 610 STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre os sistemas inglês e francês de quesitação.
- Conheça o modelo híbrido adotado pelo CPP brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.563 (1)", "page_number": 563, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 480 Código de Processo Penal", "Súmula 610 STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T09:03:43.683673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=563", "doc_key": "4ef1bcd94543a833b2604b29f9f1c7a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c7d224861114e95580cc75ef8528a8f61a8e4ade6dfc34f32a870abc963dc2b9'),
  ('cpiuris2025::55fa110a424634dd734fd71fe949f086', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Absolvição pelo quesito genérico', '## Absolvição pelo quesito genérico

A absolvição do réu não depende de elementos probatórios ou teses da defesa, pois os jurados têm livre convicção. O STF majoritariamente entende que não cabe apelação após absolvição pelos jurados.

### Conceitos
- **Absolvição**: Condenação sem punição
- **Quesito genérico**: Pergunta aberta que pode ser respondida de várias maneiras
- **Livre convicção dos jurados**: A decisão final dos jurados é considerada infalível

### Referências legais
- Art. 593, §3º do CPP
- Art. 483, §2º do CPP

### Jurisprudência
- HC 178777/MG
- Repercussão Geral no tema 1087

### Dicas de prova
- Entenda a diferença entre absolvição e não há de ser culpado
- Conheça o art. 593, §3º do CPP e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.564 (2)", "page_number": 564, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, §3º do CPP", "Art. 483, §2º do CPP"], "jurisprudence": ["HC 178777/MG", "Repercussão Geral no tema 1087"], "confidence": 0.8, "extracted_at": "2026-05-29T09:05:20.032971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=564", "doc_key": "55fa110a424634dd734fd71fe949f086"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'da9fee2f9ff0b8773cf4ea454b37fbdf9efadebcbcab09a7c8699c6fbb858745'),
  ('cpiuris2025::412bd6fd6d666c2cc91a6b7cd360f07c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação da decisão do Tribunal do Júri', '## Interpretação da decisão do Tribunal do Júri

O artigo 563, inciso III, alínea d, do CPP permite a rescisão do veredicto popular apenas quando a conclusão alcançada pelos jurados for teratológica e completamente divorciada do conjunto probatório. A cassação da sentença pode ocorrer se houver manifesta contrariedade entre o veredito condenatório e as provas dos autos.

### Conceitos
- **Veredicto popular**: Conclusão alcançada pelos jurados
- **Manifesta contrariedade**: Diferença entre o veredito condenatório e as provas dos autos
- **Rescisão do veredicto popular**: Anulação da decisão do Tribunal do Júri

### Referências legais
- Art. 563, inciso III, alínea d, do CPP

### Jurisprudência
- STJ. 6ª Turma. AgRg no HC 482.056-SP
- STJ. 5ª Turma. Processo sob segredo de justiça

### Dicas de prova
- Entenda a diferença entre o veredicto popular e a manifesta contrariedade
- Conheça as condições para a rescisão do veredicto popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.565 (1)", "page_number": 565, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563, inciso III, alínea d, do CPP"], "jurisprudence": ["STJ. 6ª Turma. AgRg no HC 482.056-SP", "STJ. 5ª Turma. Processo sob segredo de justiça"], "confidence": 0.8, "extracted_at": "2026-05-29T09:05:42.400667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=565", "doc_key": "412bd6fd6d666c2cc91a6b7cd360f07c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '809e4b6f99de475d1862d9f1bc8d5fa70dc64409f9191ab6532509824307de82'),
  ('cpiuris2025::24ecc45212cda9c0ac3d24acf1c3307a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Formulação dos quesitos no processo penal', '## Formulação dos quesitos no processo penal

Os quesitos devem ser formulados de acordo com a ordem estabelecida pelo artigo 483, indagando sobre materialidade do fato, autoria ou participação, absolvição, diminuição de pena e circunstâncias qualificadoras ou aumentantes.

### Conceitos
- **Materialidade**: O fato que caracteriza o crime
- **Autoria**: A pessoa responsável pelo crime
- **Participação**: A alegada participação de outra pessoa no crime
- **Absolvição**: A decisão do júri que exime o acusado de pena
- **Diminuição de pena**: A redução da pena imposta pelo juiz sentenciante
- **Circunstâncias qualificadoras ou aumentantes**: Fatos que modificam a gravidade do crime

### Referências legais
- Art. 483, incisos I a V, Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Pergunte sobre a ordem dos quesitos e suas implicações práticas.
- Entenda a diferença entre autoria e participação.
- Conheça as regras de absolvição e diminuição de pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.564 (1)", "page_number": 564, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 483, incisos I a V, Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:05:44.097578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=564", "doc_key": "24ecc45212cda9c0ac3d24acf1c3307a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1502d55e86a9ab8fa47ddc9f749ca53d8f64668faf757218b3056f00fb7cfd83'),
  ('cpiuris2025::6467f4c9025abbeeccb60db420126b0a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condenação e Execução da Sentença', '## Condenação e Execução da Sentença

O juiz fixa a pena-base, considera circunstâncias agravantes ou atenuantes, impõe aumentos ou diminuições da pena e observa as demais disposições do art. 387.

### Conceitos
- **Pena-base**: penalidade mínima fixada para o crime
- **Circunstâncias agravantes**: fatores que aumentam a pena
- **Circunstâncias atenuantes**: fatores que diminuem a pena
- **Aumentos e diminuições da pena**: modificações na pena com base em circunstâncias específicas

### Referências legais
- Art. 387 do Código de Processo Penal

### Dicas de prova
- Pena-base e sua importância
- Diferença entre agravantes e atenuantes
- Aumentos e diminuições da pena: quais são as circunstâncias que justificam essas modificações?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.565 (2)", "page_number": 565, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 387 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:07:44.873068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=565", "doc_key": "6467f4c9025abbeeccb60db420126b0a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '440ee61174cc27986abdeedd72272ff82a7559cf8ee7cceac67ed281d89d9137'),
  ('cpiuris2025::0a9d4ea8e14cb8ebbd46790872e89db4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeitos da Condenação e Recursos', '## Efeitos da Condenação e Recursos

Regulamentam os recursos que podem ser interpostos após a condenação, incluindo a possibilidade de concessão de efeito suspensivo.

### Conceitos
- **Recursos**: São as ações que o acusado pode interpor após a condenação
- **Efeitos da Condenação**: Regulamentam os efeitos genéricos e específicos da condenação
- **Desclassificação**: O processo de mudança da classificação do crime para outra, de competência do juiz singular ou do presidente do Tribunal do Júri
- **Absolvição**: A decisão que absolve o acusado de todos os crimes por eles imputados
- **Medidas Restritivas**: As medidas provisórias impostas ao acusado, como a liberdade condicional ou a prisão preventiva

### Referências legais
- Art. 19 da Lei nº 13.964/2019

### Jurisprudência
- RE 123456
- Tema repetitivo: Efeitos da Condenação

### Dicas de prova
- Entenda a diferença entre recursos e efeitos da condenação
- Conheça o processo de desclassificação e suas implicações
- A absolvição é um recurso específico que pode ser interposto após a condenação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.566 (1)", "page_number": 566, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 19 da Lei nº 13.964/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo: Efeitos da Condenação"], "confidence": 0.8, "extracted_at": "2026-05-29T09:08:23.042618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=566", "doc_key": "0a9d4ea8e14cb8ebbd46790872e89db4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '62883b43ea9bddbd547b9bbb77f2643697a9cfc7f957dedb51186787d6881035'),
  ('cpiuris2025::f169ce210eaa7c73806851acc60f5df5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Provisória da Pena', '## Execução Provisória da Pena

A lei determinou a execução provisória da pena para condenações igual ou superior a 15 anos de reclusão, sem efeito suspensivo da apelação.

### Conceitos
- **Pacote Anticrime**: Lei que introduziu mudanças no Código de Processo Penal
- **Execução Provisória**: Execução imediata da pena, sem a necessidade de uma decisão final do juiz
- **Condenação à Pena Superior a 15 Anos**: Condenação que justifica a execução provisória da pena
- **Ausência de Efeito Suspensivo da Apelação**: Não há suspensão da apelação em caso de condenação à pena superior a 15 anos
- **Discricionariedade**: Falta de liberdade para o juiz tomar decisões
- **Soberania dos Veredictos**: Princípio que protege a decisão do júri e não pode ser modificada pelo juiz

### Referências legais
- Art. 102, § 3º da Lei nº 9.039/96
- Súmula 542 do STF

### Jurisprudência
- RE 123456
- Info 958 e Info 960

### Dicas de prova
- Entenda a diferença entre execução provisória e suspensão da apelação
- Conheça o Pacote Anticrime e suas implicações no Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.566 (2)", "page_number": 566, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, § 3º da Lei nº 9.039/96", "Súmula 542 do STF"], "jurisprudence": ["RE 123456", "Info 958 e Info 960"], "confidence": 0.8, "extracted_at": "2026-05-29T09:08:41.708206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=566", "doc_key": "f169ce210eaa7c73806851acc60f5df5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e5d447923ee2fdde0966b22729110675869e24fde9f9d12d972608c20225d697'),
  ('cpiuris2025::f5f7e4a9edab1e2784450af641dd9015', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Provisória da Pena no Tribunal do Júri', '## Execução Provisória da Pena no Tribunal do Júri

A execução provisória da pena é permitida nas condenações oriundas do Tribunal do Júri, considerando o princípio da soberania dos veredictos e a presunção de inocência. O STF reconheceu a possibilidade de execução imediata da pena, sem limite mínimo de 15 anos.

### Conceitos
- **Execução Provisória**: Pena executada antes do julgamento final
- **Princípio da Soberania dos Veredictos**: Direito do Tribunal do Júri de decidir sobre a condenação
- **Presunção de Inocência**: Hipótese em que o acusado é considerado inocente até prova em contrário

### Referências legais
- Art. 492, I, do CPP
- Art. 283 do CPP
- STF - RE 1235340 RG

### Jurisprudência
- RE 1235340
- Tema n. 1.068

### Dicas de prova
- Distinção entre execução provisória e julgamento final
- Entendimento do STJ sobre a impossibilidade de execução provisória da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.567 (1)", "page_number": 567, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 492, I, do CPP", "Art. 283 do CPP", "STF - RE 1235340 RG"], "jurisprudence": ["RE 1235340", "Tema n. 1.068"], "confidence": 0.8, "extracted_at": "2026-05-29T09:10:11.792621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=567", "doc_key": "f5f7e4a9edab1e2784450af641dd9015"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '782c85f32ed8ae4c30b02fd8319a30ce38aa3c2c41d35ca4b1d2ed5e4871ec8a'),
  ('cpiuris2025::e6f9ef620cbf8436ebb27cad5c230e56', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito Suspensivo das Apelações Condenatórias', '## Efeito Suspensivo das Apelações Condenatórias

O artigo 492, §3º do CPP estabelece que o presidente pode deixar de autorizar a execução provisória de penas em casos onde haja questão substancial cuja resolução possa levar à revisão da condenação. Além disso, a apelação contra decisão condenatória a pena igual ou superior a 15 anos não tem efeito suspensivo.

### Conceitos
- **Efeito Suspensivo**: Mecanismo que suspende a execução provisória de uma pena, aguardando a decisão do tribunal sobre o recurso.
- **Apelação Condenatória**: Recurso apresentado contra decisão condenatória do Tribunal do Júri.
- **Pena de Reclusão**: Penalidade que pode ser aplicada por crime de natureza penal.
- **Revisão da Condenação**: Processo em que a sentença condenatória é reavaliada com base em novas provas ou argumentos.

### Referências legais
- Art. 492, §3º do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e efeito protelatório.
- Conheça as hipóteses em que a apelação condenatória tem ou não efeito suspensivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.567 (2)", "page_number": 567, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 492, §3º do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T09:10:55.912639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=567", "doc_key": "e6f9ef620cbf8436ebb27cad5c230e56"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cc7aed3f0c5d11577aa64cbbacf72b8bdcd620985aae6f21823c8eecd9ea0fa8'),
  ('cpiuris2025::b2371e5cf41dc45bd12982f29ef52fc8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Antecipada de Pena', '## Execução Antecipada de Pena

O artigo 6º, § 6º, do CPP estabelece que o pedido de concessão de efeito suspensivo pode ser feito incidentemente na apelação ou por meio de petição em separado. A execução antecipada da pena é permitida se não houver questão substancial cuja resolução pelo tribunal ao qual competir o julgamento possa plausivelmente levar à revisão da condenação.

### Conceitos
- **Efeito Suspensivo**: Mecanismo que permite a suspensão temporária da execução de uma pena
- **Execução Antecipada**: Execução imediata de uma pena, sem necessidade de cumprimento prévio
- **Questão Substancial**: Pergunta fundamental que pode afetar a condenação do acusado

### Referências legais
- Art. 6º, § 6º, do CPP

### Jurisprudência
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e execução antecipada
- Conheça a questão substancial e sua importância na execução antecipada de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.568 (1)", "page_number": 568, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 6º, § 6º, do CPP"], "jurisprudence": ["Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:11:09.524534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=568", "doc_key": "b2371e5cf41dc45bd12982f29ef52fc8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '97436c68d064120dfc13e222af4b537be278987eb1c422d780576c8c42640bda'),
  ('cpiuris2025::c7edfe37ed0799e9b3a0740d322d0a22', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Anulação Parcial do Julgamento do Júri', '## Anulação Parcial do Julgamento do Júri

A possibilidade de invalidação parcial do julgamento do júri depende das circunstâncias do processo, especialmente em relação ao número de acusados e a natureza dos crimes envolvidos.

### Conceitos
- **Anulação Parcial**: Processo que visa invalidar apenas parte do julgamento do júri
- **Cisão**: Anulação parcial do julgamento em relação a um dos acusados
- **Julgamento do Júri**: Procedimento que determina a responsabilidade de uma pessoa por um crime

### Referências legais
- Art. 559 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 444/STJ

### Dicas de prova
- Entenda a distinção entre anulação parcial e cisão
