  ('cpiuris2025::f30b4469d9d7259be72964e8ba56596a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Autuação e notificação do acusado em crimes afiançáveis', '## Autuação e notificação do acusado em crimes afiançáveis

O juiz autua a denúncia ou queixa em devida forma, notificando o acusado para responder por escrito dentro de 15 dias. Se não for conhecida a residência do acusado, é nomeado defensor.

### Conceitos
- **Autuação**: Ato pelo qual o juiz inicia o processo
- **Notificação**: Comunicação oficial ao acusado
- **Crimes afiançáveis**: Delitos que podem ser resolvidos fora do sistema judiciário
- **Procedimento especial**: Regra específica para determinados tipos de crimes

### Referências legais
- Art. 514 da LBP
- Art. 515 da LBP

### Dicas de prova
- Entenda a diferença entre autuação e notificação
- Conheça as limitações do artigo 514 (crimes afiançáveis)
