  ('cpiuris2025::f2837960d12c9fd236fcdb2d7d6e469c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sobrania dos Veredictos e Recurso Extraordinário', '## Sobrania dos Veredictos e Recurso Extraordinário

Resumo do trecho: O STJ entendeu que os tribunais de segunda instância podem determinar novo júri em caso de absolvição por quesito genérico, desde que haja contrariedade às provas dos autos. Além disso, o STF decidiu que é possível recorrer de decisão do Tribunal do Júri que absolveu um réu sem fundamentação específica.

### Conceitos
- **Sobrania dos Veredictos**: A ideia de que os veredictos do júri são imunes a revisão ou alteração
- **Recurso Extraordinário**: Um recurso especial apresentado ao STF para questionar uma decisão do STJ ou do Tribunal Superior de Justiça
- **Nem Reformatio in Pejus**: Princípio que proíbe a alteração da sentença original em favor da parte contrária, sem consentimento dela
- **Absolvição por Quesito Genérico**: A absolvição de um réu por falta de provas suficientes para condená-lo, mesmo que haja contrariedade às provas dos autos
- **Contrariedade às Provas dos Autos**: A situação em que as provas apresentadas pelo Estado não são suficientes para comprovar a culpa do réu

### Referências legais
- Art. 5º, XXXVIII, C, CF
- STF, Info 927
- Art. 483, III, C/C §2º, CPP

### Jurisprudência
- RECURSO EXTRAORDINÁRIO COM AGRAVO. PENAL E PROCESSUAL PENAL.
- ARE 1225185 RG

### Dicas de prova
- Entenda a soberania dos veredictos e como ela pode ser questionada em recurso extraordinário
- Conheça o princípio da ne reformatio in pejus e como ele se aplica à absolvição por quesito genérico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.569 (1)", "page_number": 569, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXVIII, C, CF", "STF, Info 927", "Art. 483, III, C/C §2º, CPP"], "jurisprudence": ["RECURSO EXTRAORDINÁRIO COM AGRAVO. PENAL E PROCESSUAL PENAL.", "ARE 1225185 RG"], "confidence": 0.8, "extracted_at": "2026-05-29T09:14:22.537011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=569", "doc_key": "f2837960d12c9fd236fcdb2d7d6e469c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0394706948611c52027bdd7bc8be83ed122c3e0dc46a395512ac5145a2ea2e74'),
  ('cpiuris2025::1941fb292c76faf43c7b95c0475e6903', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Defesa Preliminar no Rito Penal', '## Defesa Preliminar no Rito Penal

A defesa preliminar é apresentada pelo acusado ou seu defensor, com objetivo de convencer o juiz a rejeitar a peça acusatória. É uma faculdade obrigatória, mas não necessária para todos os casos.

### Conceitos
- **Defesa Preliminar**: Apresentação da defesa pelo acusado ou seu defensor, com objetivo de convencer o juiz a rejeitar a peça acusatória.
- **Obrigatório**: Faculdade obrigatória para todos os casos
- **Não Necessária**: Somente aplicável em casos específicos, como concurso de crimes

### Referências legais
- Art. 514 do Código de Processo Penal
- Súmula 330 do STJ
- Julgamento do STF no caso Info 743

### Jurisprudência
- RE 123456
- Tema repetitivo sobre defesa preliminar

### Dicas de prova
- Entenda a diferença entre defesa preliminar e defesa de mérito
- Conheça as exceções à obrigatória apresentação da defesa preliminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.570 (1)", "page_number": 570, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 514 do Código de Processo Penal", "Súmula 330 do STJ", "Julgamento do STF no caso Info 743"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre defesa preliminar"], "confidence": 0.8, "extracted_at": "2026-05-29T09:14:23.206795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=570", "doc_key": "1941fb292c76faf43c7b95c0475e6903"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c7feae1f78574ecbe295a1ff3f7b3464cf8b6323920c4122d4ddb89ea2df9c91'),
  ('cpiuris2025::0d8b29dffb7a267cf711c1318f309cb1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento em casos criminais', '## Procedimento em casos criminais

Resumo objetivo: A rejeição da denúncia ou queixa é feita com base no art. 395 do CPP e tem natureza de decisão interlocutória terminativa. Após a recebimento da denúncia, procede-se à citação, aplicando o procedimento comum ordinário. Os crimes contra a honra são julgados conforme as disposições da Lei de Juizados Especiais.

### Conceitos
- **Denúncia**: Ação formal apresentada pelo Ministério Público para condenar o réu
- **Rejeição da denúncia**: Decisão do juiz que não aceita a denúncia apresentada pelo Ministério Público
- **Citação**: Atividade processual que notifica o réu sobre a acusação
- **Procedimento comum ordinário**: Regulamento do procedimento em casos criminais, aplicado após a citação
- **Lei de Juizados Especiais**: Lei que regula os crimes contra a honra

### Referências legais
- Art. 395 do CPP
- Art. 517 e 518 do CPP

### Dicas de prova
- Diferenciar entre denúncia e rejeição da denúncia
- Entender a aplicação do procedimento comum ordinário após a citação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.570 (2)", "page_number": 570, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 395 do CPP", "Art. 517 e 518 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:15:33.152398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=570", "doc_key": "0d8b29dffb7a267cf711c1318f309cb1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e745d4074849661032ca73677c938341efbb90778207a6c8ca476e43a499a8a1'),
  ('cpiuris2025::bafadb63c83a6bf6adaf565a143682ff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Oferecimento da exceção da verdade e notoriedade do fato imputado', '## Oferecimento da exceção da verdade e notoriedade do fato imputado

O querelante pode oferecer exceção da verdade ou notoriedade do fato imputado, podendo contestá-la no prazo de dois dias. Se a exceção for procedente, o fato é atípico e o querelado será absolvido.

### Conceitos
- **Exceção da verdade**: oferecimento feito pelo querelante para provar a não ocorrência de um fato imputado
- **Notoriedade do fato imputado**: fato que pode ser comprovado por meio de documentos ou depoimentos de testemunhas
- **Procedimento comum ordinário**: regulamento do procedimento em casos não especiais

### Referências legais
- Art. 396 do CPP
- Art. 523 do CPP

### Dicas de prova
- Distinção entre exceções da verdade e notoriedade do fato imputado
- Prazo para contestar a exceção da verdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.571 (2)", "page_number": 571, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 396 do CPP", "Art. 523 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:16:25.899687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=571", "doc_key": "bafadb63c83a6bf6adaf565a143682ff"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '52a9e9ff70890405b3ef6ec29230592ccf65ddef0f28a6bb9f3ca55d45bb5e47'),
  ('cpiuris2025::9c87c30f6228ecea3c50e5b33f1e6cce', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conciliação em Processos Penais', '## Conciliação em Processos Penais

O CPP estabelece procedimento especial para crimes de calúnia e injúria, com tentativa de conciliação antes da apresentação da peça acusatória. A conciliação pode gerar arquivamento da queixa e extinção da punibilidade.

### Conceitos
- **Conciliação**: Tentativa de reconciliar as partes antes da apresentação da peça acusatória
- **Reconciliação**: Atividade que visa conciliar as partes em conflito
- **Desistência**: Declaração de desistência do querelante após a reconciliação
- **Punibilidade**: Período durante o qual o acusado pode ser punido, se não for extinta
- **Extinção de Punibilidade**: Fim da punibilidade do acusado

### Referências legais
- Art. 520 CPP
- Art. 521 CPP
- Art. 522 CPP
- Súmula 714 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: conciliação em processos penais

### Dicas de prova
- Entenda a diferença entre reconciliação e conciliação
- Conheça as condições para a extinção de punibilidade após conciliação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.571 (1)", "page_number": 571, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 520 CPP", "Art. 521 CPP", "Art. 522 CPP", "Súmula 714 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: conciliação em processos penais"], "confidence": 0.8, "extracted_at": "2026-05-29T09:17:02.671249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=571", "doc_key": "9c87c30f6228ecea3c50e5b33f1e6cce"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3ff9a2c5d7f0f4f74da9b89373cda8380eaefb86fe6b3c022550836cc9b57ea2'),
  ('cpiuris2025::ce9f06dfdb35e1463fcd608cb0728c57', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento especial dos crimes contra a propriedade imaterial', '## Procedimento especial dos crimes contra a propriedade imaterial

Regulamentação do procedimento dos crimes contra a propriedade imaterial, incluindo as regras de laudo pericial e busca/apreensão.

### Conceitos
- **Procedimento especial**: Regras específicas para os crimes contra a propriedade imaterial
