  ('cpiuris2025::b770732f4282b24a283f0cc72eea99c3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo decadencial na ação penal por crimes contra a propriedade imaterial', '## Prazo decadencial na ação penal por crimes contra a propriedade imaterial

O STJ firmou entendimento sobre a interpretação do prazo de 30 dias do art. 529, considerando a homologação de laudo pericial.

### Conceitos
- **Prazo decadencial**: Período durante o qual deve ser propositada a ação penal
- **Crimes contra a propriedade imaterial**: Delitos que afetam a proteção de direitos intangíveis, como a imagem e a reputação
- **Laudo pericial**: Relatório técnico produzido por especialistas para esclarecer fatos do caso

