  ('cpiuris2025::cb05279c47d984a02a3b768bb4108c5a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Apreensão de bens em crimes de violação de direito autoral', '## Apreensão de bens em crimes de violação de direito autoral

Sobre o procedimento para a apreensão de bens em crimes de violação de direito autoral, incluindo a perícia e a lavratura do termo de apreensão.

### Conceitos
- **Apreensão**: Procedimento utilizado pela polícia para apreender bens ilícitos
- **Perícia**: Exame técnico e científico de objetos ou bens para determinar sua natureza e origem
- **Termo de apreensão**: Documento que descreve os bens apreendidos e suas origens, assinado por testemunhas
- **Lavratura do termo de apreensão**: Atividade processual de registrar a apreensão de bens em um documento oficial

### Referências legais
- Art. 530-A
- Art. 530-B
- Súmula 574, STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre perícia e laudo de apreensão.
