  ('cpiuris2025::0795ccf4a173016d40673aab9f81678f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Laudo de Constatação e Procedimento com Drogas Apreendidas', '## Laudo de Constatação e Procedimento com Drogas Apreendidas

O laudo de constatação é um documento necessário para o recebimento da denúncia, afirmando a materialidade do delito. Ele pode ser utilizado excepcionalmente no lugar do laudo definitivo.

### Conceitos
- **Laudo de Constatação**: Documento que certifica a natureza e quantidade da droga apreendida
- **Procedimento com Drogas Apreendidas**: Tratamento especial para as drogas apreendidas, incluindo a destruição delas
- **Laudo Preliminar**: Versão inicial do laudo que pode ser utilizado em lugar do laudo definitivo

### Referências legais
- Art. 12.961, de 2014

### Dicas de prova
- Entenda a importância do laudo de constatação na procedência da denúncia
- Conheça as condições para o uso do laudo preliminar em vez do laudo definitivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.574 (2)", "page_number": 574, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12.961, de 2014"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:20:42.700710+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=574", "doc_key": "0795ccf4a173016d40673aab9f81678f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '626f9892b7a091483e904f846cef7e4598df8821912608737adafb4cfe116788'),
  ('cpiuris2025::82c479646ac84420d4411cc00045db05', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impugnação à ilicitude ou inadmissibilidade da ação penal', '## Impugnação à ilicitude ou inadmissibilidade da ação penal

O juiz pode determinar a destruição de bens ilicitamente produzidos e o perdimento de equipamentos em favor da Fazenda Nacional, que deve destruí-los ou doá-los aos entes públicos e instituições de assistência social.

### Conceitos
- **Impugnação à ilicitude**: Ação direta contra a ilicitude de um crime
- **Inadmissibilidade da ação penal**: O juiz pode declarar inadmissível a ação penal por falta de determinação do autor do ilícito
- **Lei nº 10.695/2003**: Lei que introduziu as alterações ao Código de Processo Penal

### Referências legais
- Art. 530-G
- Art. 530-H
- Lei nº 10.695

