  ('cpiuris2025::d98be7166d8916ff4dc9ac61f1d9c232', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento especial da Lei de Drogas', '## Procedimento especial da Lei de Drogas

Descreve as regras específicas para a aplicação da lei de drogas, incluindo a prisão em flagrante e o procedimento a ser seguido.

### Conceitos
- **Prisão em flagrante**: Ato policial que detém imediatamente uma pessoa suspeita de cometer um crime.
- **Lei de Drogas**: Lei nº 11.343/06 que dispõe sobre as penas para os crimes relacionados à droga.
- **Auto de prisão em flagrante**: Documento que registra a prisão de uma pessoa suspeita de cometer um crime.
- **Lavratura do auto**: Atividade realizada pela polícia para registrar a prisão de uma pessoa.
- **Competência**: A autoridade judiciária competente é a que tem jurisdição sobre o caso.
- **Requisições**: Pedidos feitos à polícia para obter informações ou documentos relacionados ao caso.
- **Exames e perícias**: Atividades realizadas pela polícia para coletar provas do crime.
- **Juizados Especiais Criminais**: Tribunal especializado em crimes menores, previsto na Lei nº 9.099/95

### Referências legais
- Art. 48 da Lei nº 11.343/06
- Art. 76 da Lei nº 9.099/95

### Jurisprudência
- RE 123456
- ...

