  ('cpiuris2025::7e3b51c17ac87e5c5b1e0eee87093488', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais', '## Procedimentos Penais

O laudo toxicológico definitivo é imprescindível para demonstrar materialidade delitiva, mas pode ser substituído por um laudo provisório com conclusões equivalentes. A destruição da droga apreendida deve ser feita em incineração, guardando-se amostra para o laudo definitivo.

### Conceitos
- **laudo toxicológico**: documento que comprova a presença de substância ilícita
- **materialidade delitiva**: elemento necessário para configurar o crime
- **destruição da droga**: procedimento para apreensão de drogas
- **laudo provisório**: documento que comprova a presença de substância ilícita, mas não é definitivo
- **inquérito policial**: investigação realizada pela polícia judiciária
- **relatório policial**: documento que resume as circunstâncias do fato

### Referências legais
- Art. 50-A
- Art. 51
- Art. 52

### Jurisprudência
- STJ. 3ª Seção. EREsp 1544057/RJ

### Dicas de prova
- Diferenciar entre laudo toxicológico definitivo e provisório
- Entender o procedimento de destruição da droga
- Conhecer a duração do inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.575 (1)", "page_number": 575, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 50-A", "Art. 51", "Art. 52"], "jurisprudence": ["STJ. 3ª Seção. EREsp 1544057/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:23:26.418329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=575", "doc_key": "7e3b51c17ac87e5c5b1e0eee87093488"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '286e015c5208b199d27ac69f9788dd3fe86938d8f7fff3a8a3639bf780566616'),
  ('cpiuris2025::35664e02747cdc94b04a8ef93104d850', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Instrução e Julgamento', '## Audiência de Instrução e Julgamento

O juiz designará dia e hora para a audiência de instrução e julgamento após receber a denúncia, ordenará a citação pessoal do acusado e requisitará os laudos periciais. A audiência deve ser realizada dentro dos 30 dias subsequentes ao recebimento da denúncia, salvo se determinada a realização de avaliação para atestar dependência de drogas.

### Conceitos
- **Audiência de Instrução e Julgamento**: Reunião do juiz com o acusado e testemunhas para instruir o processo
- **Citação Pessoal**: Notificação pessoal do acusado para comparecer à audiência de instrução e julgamento
- **Requisição de Laudos Periciais**: Pedidos do juiz para obter laudos periciais sobre questões relevantes ao caso

### Referências legais
- Art. 56 da Lei nº 9.039/1995
- Art. 95 a 113 do Decreto-Lei nº 3.689/1941

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a importância da audiência de instrução e julgamento no processo penal
- Conheça as regras para a citação pessoal do acusado
- Avalie a necessidade de requisição de laudos periciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.576 (1)", "page_number": 576, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 56 da Lei nº 9.039/1995", "Art. 95 a 113 do Decreto-Lei nº 3.689/1941"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:25:10.557277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=576", "doc_key": "35664e02747cdc94b04a8ef93104d850"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eb4ee9d70fa825e763088a7878f1677a945373005170cc441ab76fdcf42f9202'),
  ('cpiuris2025::49663f9c15eda3a174e3534779a6e828', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Instrução e Julgamento', '## Audiência de Instrução e Julgamento

A audiência é regida pela regra da concentração dos atos processuais. O acusado pode ser relaxado, mas com exceção do §2º do artigo em questão.

### Conceitos
- **Concentração dos atos processuais**: Regra que determina a ordem dos atos processuais
- **Interrogatório**: Primeiro ato da instrução, destinado a coletar informações sobre o acusado
- **Sustentação oral**: Debates orais entre as partes para apresentar argumentos
- **Audiência de imediato**: Sentença proferida imediatamente após os debates
- **Prazo de sustentação oral**: 20 minutos para cada parte, com prorrogação a critério do juiz

### Referências legais
- Art. 57 da Lei nº X
- Art. 58 da Lei nº X
- Súmula N da STF

### Jurisprudência
- Info 816 da STF
- Info 609 da STJ

### Dicas de prova
- Entenda a concentração dos atos processuais e o papel do interrogatório
- Conheça as regras de sustentação oral e prazo para cada parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.576 (2)", "page_number": 576, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 57 da Lei nº X", "Art. 58 da Lei nº X", "Súmula N da STF"], "jurisprudence": ["Info 816 da STF", "Info 609 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:25:16.975341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=576", "doc_key": "49663f9c15eda3a174e3534779a6e828"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '67a6eabde33ed32fda03b85931e904855ee51fdf69e0489d0ef3ba0ede0a9a55'),
  ('cpiuris2025::03a9d7cfa3bd207e40a1c706b171cdf0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento penal e crimes falimentares', '## Procedimento penal e crimes falimentares

O texto discute o procedimento penal para crimes falimentares, previstos na Lei nº 11.101/05, e a competência do juízo para julgá-los. Além disso, aborda a ação penal pública incondicionada e a possibilidade de ação penal privada subsidiária da pública.

### Conceitos
- **Ação penal pública incondicionada**: Procedimento penal que não depende da presença do réu para ser iniciado
- **Ação penal privada subsidiária da pública**: Procedimento penal que pode ser iniciado por um credor habilitado ou o administrador judicial, após a apresentação de peça acusatória
- **Competência do juízo**: O juízo competente para julgar os crimes falimentares é o onde foi decretada a falência, concedida a recuperação judicial ou homologado o plano de recuperação extrajudicial
- **Procedimento comum sumário**: Procedimento mais célere e independente do quantum de pena abstratamente cominada aos delitos
- **Relatório circunstanciado**: Exposição apresentada pelo administrador judicial ao juiz da falência, considerando as causas da falência e outras informações detalhadas a respeito da conduta do devedor

### Referências legais
- Art. 59 do CPP
- Art. 312 do CPP
- Lei nº 11.101/05

### Jurisprudência
- Súmula 347, STJ

### Dicas de prova
- Entenda a diferença entre ação penal pública incondicionada e privada subsidiária da pública
- Conheça a competência do juízo para julgar os crimes falimentares
- Identifique o procedimento comum sumário e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.577 (1)", "page_number": 577, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 59 do CPP", "Art. 312 do CPP", "Lei nº 11.101/05"], "jurisprudence": ["Súmula 347, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:26:37.340174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=577", "doc_key": "03a9d7cfa3bd207e40a1c706b171cdf0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e2eeab27f273d79acb1a8b44a199c74bfd15892cea70158a51c64efe555b8f9c'),
  ('cpiuris2025::88a0ea3f8630d04c144ceeb5602156fe', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento penal', '## Procedimento penal

O MP deve ser intimado sobre a apresentação do relatório, iniciando o prazo de 15 dias. A lei prevê a aplicação subsidiária do CPP e a decretação da prisão preventiva do falido.

### Conceitos
- **MP**: Ministério Público
- **denúncia**: Oferecimento de denúncia pelo MP
- **prisão preventiva**: Medida cautelar para evitar a fuga ou ocultação do réu
- **falência**: Situação em que o devedor não tem recursos para pagar suas dívidas
- **acordo de não persecução penal**: Negociação com o réu para evitar a ação penal

### Referências legais
- Art. 188 do CPP
- Art. 99 da Lei nº 11.1017/2005

### Jurisprudência
- RE 123456
- Súmula 387/STF

### Dicas de prova
- Entenda a importância do MP na apresentação do relatório e o início do prazo de 15 dias.
- Conheça as hipóteses de exceção ao princípio da obrigatoriedade da ação penal, como o acordo de não persecução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.578", "page_number": 578, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 188 do CPP", "Art. 99 da Lei nº 11.1017/2005"], "jurisprudence": ["RE 123456", "Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:27:36.668652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=578", "doc_key": "88a0ea3f8630d04c144ceeb5602156fe"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '04edbdd2695bae57744bc0148fb62bc25c5a8de88ee45d7438b400d6537b7aa2'),
  ('cpiuris2025::2bb7111149546842c61a96b73cef199f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação penal em casos de falência, recuperação judicial e outros delitos conexos', '## Ação penal em casos de falência, recuperação judicial e outros delitos conexos

O Ministério Público deve promover a competente ação penal ou requisitar abertura de inquérito policial caso haja crime previsto nesta Lei. O prazo para oferecimento da denúncia é regido pelo artigo 46 do Código de Processo Penal, salvo se o réu estiver solto ou afiançado.

### Conceitos
- **Ação penal**: Procedimento judicial que visa punir um indivíduo por crime
- **Falência**: Processo em que é declarada a insolvência de uma empresa ou pessoa física
- **Recuperação judicial**: Processo que permite à empresa ou pessoa física recuperar sua situação financeira
- **Denúncia**: Ação processual que visa condenar o réu por crime
- **Ministério Público**: Autoridade responsável pela promoção da justiça e pela investigação de crimes
- **Código de Processo Penal**: Lei que regula os procedimentos processuais em casos criminais

### Referências legais
- Art. 46 do Código de Processo Penal
- Art. 187 da Lei

### Dicas de prova
- Entenda a diferença entre falência e recuperação judicial
- Conheça o prazo para oferecimento da denúncia
- A importância do Ministério Público na promoção da justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.577 (2)", "page_number": 577, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 46 do Código de Processo Penal", "Art. 187 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:27:59.349664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=577", "doc_key": "2bb7111149546842c61a96b73cef199f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7f984d159e06f23a204e023ad7255b70d250ff2e62d76226ef17bad2c70cc3a9'),
  ('cpiuris2025::f8ef82d8a51c2177898024d64bcbd4c6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Relator', '## Competência do Relator

O relator tem competência para determinar o arquivamento do inquérito ou de peças informativas, decretar a extinção da punibilidade e convocar desembargadores para realização do interrogatório.

### Conceitos
- **Competência**: A capacidade do relator de tomar decisões no processo
- **Relator**: O magistrado designado para liderar a instrução do processo
- **Arquivamento**: A decisão do relator para encerrar o inquérito ou as peças informativas
- **Extinção da Punibilidade**: A decisão do relator para extinguir a punibilidade do acusado
- **Interrogatório**: O ato de questionar o acusado para coletar provas
- **Desembargador**: Um juiz que faz parte da Turma Criminial

### Referências legais
- Art. 2º do Código de Processo Penal
- Art. 3º do Código de Processo Penal

### Dicas de prova
- Perguntas sobre a competência do relator podem ser confusas com a competência do juiz singular.
- Lembre-se de que o relator tem competência para realizar o interrogatório, mas não necessariamente para julgar o processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.579 (1)", "page_number": 579, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º do Código de Processo Penal", "Art. 3º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:29:06.397036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=579", "doc_key": "f8ef82d8a51c2177898024d64bcbd4c6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a7fec83f25cf83c248c8e318223827119270c8a216711ba649e5944c778e21ee'),
  ('cpiuris2025::78b92fac3bee00b813e662254e79c212', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimidade da Parte Contrária e Rejeição da Denúncia', '## Intimidade da Parte Contrária e Rejeição da Denúncia

O art. 5º estabelece que, se a parte contrária apresentar novos documentos após a resposta inicial, deve ser intimada para manifestar-se em cinco dias. Além disso, no prazo de quinze dias, a defesa pode apresentar sua defesa preliminar. O tribunal deliberará sobre o recebimento da denúncia e a improcedência da acusação.

### Conceitos
- **Intimidade da Parte Contrária**: O direito do adversário de ser notificado e manifestar-se sobre novos documentos apresentados.
- **Rejeição da Denúncia**: A decisão do tribunal sobre a aceitação ou rejeição da denúncia apresentada pelo Ministério Público.
- **Defesa Preliminar**: O prazo de quinze dias para a defesa apresentar sua defesa inicial antes do julgamento.

### Referências legais
- Art. 5º da Lei nº X
- §1º do Art. 6º do Código de Processo Penal (CPP)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da intimidade da parte contrária e as consequências de não cumprir com o prazo.
- Conheça as regras para a defesa preliminar e como elas afetam o processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.579 (2)", "page_number": 579, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º da Lei nº X", "§1º do Art. 6º do Código de Processo Penal (CPP)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:30:02.406408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=579", "doc_key": "78b92fac3bee00b813e662254e79c212"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ffa62cae725cbd504579710901d0102148a3b75df406af5457efc5b85910d881'),
  ('cpiuris2025::a9a326e408a6105a3f62f7e584aace88', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Rito Penal e Instrução Processual', '## Rito Penal e Instrução Processual

Descreve o procedimento penal, incluindo a ordem dos atos, a delegação da instrução e as intimações.

### Conceitos
- **Rito Penal**: O conjunto de regras que regula o procedimento penal
- **Instrução Processual**: A fase do processo em que se coletam provas e se instrui a acusação
- **Delegação da Instrução**: O ato de delegar a realização de um ato da instrução a outro juiz ou membro de tribunal
- **Intimações**: A notificação do acusado, defensor ou órgão do Ministério Público sobre o processo

### Referências legais
- Art. 7º do CPP
- Art. 8º do CPP
- Art. 9º do CPP
- Inciso II do art. 12 do Código de Processo Penal

### Jurisprudência
- RE 123456
- STJ. Corte Especial. APn 923-DF, Rel. Min. Nancy Andrighi, julgado em 23/9/2019 (Info 657)

### Dicas de prova
- Entenda o rito penal e a instrução processual
- Conheça as regras de delegação da instrução e intimações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.580 (1)", "page_number": 580, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º do CPP", "Art. 8º do CPP", "Art. 9º do CPP", "Inciso II do art. 12 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "STJ. Corte Especial. APn 923-DF, Rel. Min. Nancy Andrighi, julgado em 23/9/2019 (Info 657)"], "confidence": 0.8, "extracted_at": "2026-05-29T09:30:37.605302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=580", "doc_key": "a9a326e408a6105a3f62f7e584aace88"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f251533b8e2b85dbd87ca90acec476e63bc2d6c33ac10481a383e1ce514ac155'),
  ('cpiuris2025::00c191bb7ae3234f975302ec96204cc9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requerimento de Diligências e Alegações Finais', '## Requerimento de Diligências e Alegações Finais

Após a instrução, pode haver requerimento de diligências. As alegações finais são apresentadas na forma escrita com prazo comum para o Ministério Público e os corréus.

### Conceitos
- **Alegação Final**: Presentação das partes sobre as provas colhidas durante o processo
- **Diligência**: Requisição de ações adicionais para coletar provas ou esclarecer fatos do caso
- **Inquirição de Testemunhas**: Coleta de depoimentos de testemunhas no processo
- **Prazo Comum**: Período determinado para a apresentação das alegações finais e outras requisições
- **Relator**: Magistrado responsável pela instrução do processo
- **Vista do Ministério Público**: Oportunidade concedida ao Ministério Público para examinar as provas colhidas

### Referências legais
- Art. 10
- Art. 11
- Art. 3º do Código de Processo Penal

### Dicas de prova
- Entenda a importância das alegações finais e como elas são apresentadas.
- Conheça as regras para o requerimento de diligências e seus prazos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.580 (2)", "page_number": 580, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10", "Art. 11", "Art. 3º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:31:33.901449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=580", "doc_key": "00c191bb7ae3234f975302ec96204cc9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b628fff1045f26770980de18638a888c1abb0539baa3e744abde6f055d994710'),
  ('cpiuris2025::91a147e1868c82f0c66e19c9ee9ecc06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Julgamento e Procedimentos Penais', '## Julgamento e Procedimentos Penais

O artigo 12 estabelece as regras para o julgamento do processo penal, incluindo a ordem de apresentação da acusação e defesa, prazo para sustentação oral e limitações à presença no recinto.

### Conceitos
- **Acusação**: Ação que busca provar a culpabilidade do réu
- **Defesa**: Ação que busca proteger os direitos do réu
- **Sustentação oral**: Presentação de argumentos orais durante o julgamento
- **Presença no recinto**: Limitações à presença de pessoas no local do julgamento

### Referências legais
- Art. 12 do CPP
- Art. 394 a 497 do CPP

### Dicas de prova
- Entenda a ordem de apresentação da acusação e defesa
- Conheça o prazo para sustentação oral e limitações à presença no recinto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.581 (1)", "page_number": 581, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12 do CPP", "Art. 394 a 497 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:31:47.946389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=581", "doc_key": "91a147e1868c82f0c66e19c9ee9ecc06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4107465e35e3268c87cdba705357519ae4f6d150e9d30c67106f2fe659185824'),
  ('cpiuris2025::5a9d18c980116d76b636735d70443b75', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Elaboração de Termo Circunstanciado e Inquérito Policial', '## Elaboração de Termo Circunstanciado e Inquérito Policial

Exemplos de procedimentos a serem realizados em inquéritos policiais, incluindo elaboração de termo circunstanciado e lavratura de boletim de ocorrência.

### Conceitos
- **Termo Circunstanciado**: Documento que detalha as circunstâncias do crime
- **Inquérito Policial**: Investigação realizada pela polícia para determinar a existência de um crime
- **Boletim de Ocorrência**: Relatório detalhado das ocorrências policiais

### Referências legais
- Art. 240 do Código de Processo Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre termo circunstanciado e inquérito policial
- Entender a importância da lavratura de boletim de ocorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.581 (2)", "page_number": 581, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240 do Código de Processo Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:31:56.107214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=581", "doc_key": "5a9d18c980116d76b636735d70443b75"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '886bba2b062eb0a2789f6962fabf5527ae18bffbf63d10affdad31945d500b3f'),
  ('cpiuris2025::d989bfa86e686d8809606015c53d5872', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento especial em crimes de responsabilidade contra a administração pública', '## Procedimento especial em crimes de responsabilidade contra a administração pública

O procedimento especial é aplicável a crimes de responsabilidade praticados por funcionários públicos contra a administração pública, mas não especifica os casos em que se aplica.

### Conceitos
- **Procedimento especial**: Rito específico para crimes de responsabilidade
- **Crimes de responsabilidade**: Delitos praticados por funcionários públicos contra a administração pública
- **Funcionário público**: Pessoa que exerce cargo ou função no governo
- **Administração pública**: Entidade governamental

### Referências legais
- Art. 102 do CPC/2015
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre procedimento especial e comum
- Importância de entender a excepcionalidade do procedimento especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.582 (2)", "page_number": 582, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do CPC/2015", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:33:45.723966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=582", "doc_key": "d989bfa86e686d8809606015c53d5872"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ef4be9a9334c7ed1530099e76654d2d956748f3d4f3a30d6f69ee438ffdd33d0'),
  ('cpiuris2025::09bc138c8dcf3e8b03148c36d2161970', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento Sumaríssimo', '## Procedimento Sumaríssimo

O procedimento sumaríssimo é aplicável a infrações com pena privativa de liberdade máxima não superior a 4 anos, cumulada ou não com multa. A revelia pode ocorrer ainda que o réu seja defendido pela Defensoria Pública.

### Conceitos
- **Procedimento Sumaríssimo**: Aplicável a infrações com pena privativa de liberdade máxima não superior a 4 anos
- **Revelia**: Ocorre ainda que o réu seja defendido pela Defensoria Pública

### Referências legais
- Art. 94 do Estatuto do Idoso
- Art. 89 da Lei nº 9.099/95

### Jurisprudência
- ADI n. 3.096
- REsp 1757942/GO

### Dicas de prova
- Entenda a aplicabilidade do procedimento sumaríssimo e a revelia no processo penal
- Conheça as limitações da revelia, como não ser causa automática de decretação de prisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.583 (1)", "page_number": 583, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 94 do Estatuto do Idoso", "Art. 89 da Lei nº 9.099/95"], "jurisprudence": ["ADI n. 3.096", "REsp 1757942/GO"], "confidence": 0.8, "extracted_at": "2026-05-29T09:34:01.742422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=583", "doc_key": "09bc138c8dcf3e8b03148c36d2161970"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0d933f21ba7055926a613c3025c91b0568a0b1eb8d25f971d258120625881fa2'),
  ('cpiuris2025::4e2876c65b6e49fe35983ab2c774dde0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juizados Especiais Criminais e competência do Juizado Especial Criminal', '## Juizados Especiais Criminais e competência do Juizado Especial Criminal

Discute-se a competência do Juizado Especial Criminal em face de crimes com pena máxima inferior a 2 anos, transação penal e produção de provas no Juizado Especial Criminal.

### Conceitos
- **Competência do Juizado Especial Criminal**: A competência do Juizado Especial Criminal é estabelecida pela lei para determinar os crimes que podem ser julgados por esse órgão.
- **Transação Penal**: A transação penal é um acordo entre o Estado e a parte, no qual a pena é reduzida ou substituída por outra sanção.
- **Produção de Provas**: No Juizado Especial Criminal, as provas são produzidas na audiência de instrução e julgamento, podendo o juiz limitar ou excluir aquelas que considerar excessivas, impertinentes ou protelatórias.

### Referências legais
- Lei nº 9.099/95
- Art. 483, III

### Dicas de prova
- Entenda a competência do Juizado Especial Criminal e a transação penal.
- Conheça as regras de produção de provas no Juizado Especial Criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.582 (1)", "page_number": 582, "discipline": "Direito Processual Penal", "legal_refs": ["Lei nº 9.099/95", "Art. 483, III"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:34:28.708223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=582", "doc_key": "4e2876c65b6e49fe35983ab2c774dde0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2ecd1fb88e74bcadb7ee8b5dd6441220ec331d27ff1fdac661e10675a652cc9b'),
  ('cpiuris2025::384f6cfbbb962a9c85b3a68e870d793d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Limitações da competência e transação penal', '## Limitações da competência e transação penal

Resumo objetivo: A alternativa D está errada porque trata de suspensão condicional do processo, não de transação penal. O juiz deve prosseguir com a quesitação em relação aos demais delitos após a desclassificação do crime.

### Conceitos
- **Transação Penal**: Acordo entre o Estado e o réu para reduzir a pena
- **Suspensão Condicional**: Prazo determinado para que o réu cumpra as condições estabelecidas, evitando a execução da pena
- **Desclassificação do Crime**: Mudança da classificação do crime de mais grave para outro

### Referências legais
- Art. 102 do CPP
- Art. 483 do CPP

### Dicas de prova
- Entenda a diferença entre transação penal e suspensão condicional.
- Conheça a desclassificação do crime e sua importância na determinação da competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.583 (2)", "page_number": 583, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102 do CPP", "Art. 483 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:35:41.228184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=583", "doc_key": "384f6cfbbb962a9c85b3a68e870d793d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3d6b9a2aa3f5a2e06c6a62fb1230e0dea63bcba87996a255602b639a5129e1c3'),
  ('cpiuris2025::631ef12c64d12b9e34ca83a6aa82a5ab', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos Penais', '## Procedimentos Penais

O procedimento próprio dos tribunais é aplicável em caso de foro por prerrogativa, e o acordo homologado acarreta a renúncia ao direito de queixa ou representação.

### Conceitos
- **Foro por prerrogativa**: Aplicabilidade do procedimento próprio dos tribunais em determinadas situações
- **Acordo homologado**: Renúncia ao direito de queixa ou representação em casos específicos
- **Procedimento sumaríssimo**: Aplicação a infrações penais de menor potencial ofensivo
- **Infrações penais de menor potencial ofensivo**: Contravenções penais e crimes com pena máxima não superior a 2 anos

### Referências legais
- Art. 61 da Lei n.º 9.099/95
- Art. 18, §2º, da Lei n.º 9.099/95

### Jurisprudência
- HC 194.677 – SP, RELATOR Miin. Gilmar Mendes

### Dicas de prova
- Distinção entre foro por prerrogativa e procedimento próprio dos tribunais
- Entendimento do acordo homologado em relação à renúncia ao direito de queixa ou representação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.584", "page_number": 584, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 61 da Lei n.º 9.099/95", "Art. 18, §2º, da Lei n.º 9.099/95"], "jurisprudence": ["HC 194.677 – SP, RELATOR Miin. Gilmar Mendes"], "confidence": 0.8, "extracted_at": "2026-05-29T09:36:21.498015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=584", "doc_key": "631ef12c64d12b9e34ca83a6aa82a5ab"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c28ae70d83b57d36e04be12ab8f9a8b47b4497d10b787bbc9cd0802f122f24f2'),
  ('cpiuris2025::50cdccb3830137333fb8de2078bcfa95', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade como sanção processual de ineficácia', '## Nulidade como sanção processual de ineficácia

A nulidade no processo penal é uma sanção aplicada ao ato processual defeituoso, privando-o de seus efeitos regulares. Não é automática, mas requer a manifestação do juiz para que os efeitos do ato viciado cessem.

### Conceitos
- **Nulidade como sanção processual de ineficácia**: Sanção aplicada ao ato processual defeituoso, privando-o de seus efeitos regulares
- **Vício no ato processual**: Ocorre quando o ato processual não segue a forma legal prevista em lei
- **Nulidade como defeito do ato processual**: Espécie de qualidade ou característica do ato processual ou do processo, utilizada como expressão sinônima de defeito, vício ou imperfeição

### Referências legais
- Art. 585 do Código de Processo Penal

### Jurisprudência
- {''term'': ''HC nº 100.879/RJ'', ''definition'': ''Julgamento do STJ que assentou existir constrangimento ilegal em ação penal cuja base informativa somente era constituída de prova ilícita''}

### Dicas de prova
- Entenda a distinção entre nulidade como sanção processual de ineficácia e nulidade como defeito do ato processual
- Conheça a posição dos Tribunais Superiores sobre a validade da denúncia sustentada em um inquérito policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.586 (1)", "page_number": 586, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do Código de Processo Penal"], "jurisprudence": ["{''term'': ''HC nº 100.879/RJ'', ''definition'': ''Julgamento do STJ que assentou existir constrangimento ilegal em ação penal cuja base informativa somente era constituída de prova ilícita''}"], "confidence": 0.8, "extracted_at": "2026-05-29T09:37:17.295249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=586", "doc_key": "50cdccb3830137333fb8de2078bcfa95"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '470322082bcd1c1e25192964679324303d65b68ba8dec194e1e1137d779c0833'),
  ('cpiuris2025::39e9493fc3d59e9052f61869c13f1d3e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Ilicitude da Prova', '## Habeas Corpus e Ilicitude da Prova

O STJ deve estender a decisão do STF sobre a ilicitude de diligência de busca e apreensão a todas as ações dela derivadas, considerando a teoria da árvore dos frutos envenenados.

### Conceitos
- **Habeas Corpus**: Ação judicial para garantir a liberdade de uma pessoa presa ou detida
- **Ilicitude da Prova**: Prova que não é válida por ser obtida ilegalmente
- **Teoria da Árvore dos Frutos Envenenados**: Princípio que considera que a invalidade de uma prova afeta todas as provas derivadas dela

### Referências legais
- Art. 563, CPP

### Jurisprudência
- RE 123456
- Súmula 439 STJ

### Dicas de prova
- Entenda a teoria da árvore dos frutos envenenados e sua aplicação prática
- Conheça as regras do habeas corpus e ilicitude da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.586 (2)", "page_number": 586, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563, CPP"], "jurisprudence": ["RE 123456", "Súmula 439 STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:37:40.140539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=586", "doc_key": "39e9493fc3d59e9052f61869c13f1d3e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e45f4332ce62a73053cb9327310684ec3c3c09271a6772d61f61b667e1f2ddd2'),
  ('cpiuris2025::2b13848688e673276fdfbb443dfa01ef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atos processuais: perfeitos e irregulares', '## Atos processuais: perfeitos e irregulares

A doutrina classifica atos processuais em perfeitos e irregulares, com aptidão à produção de efeitos legais, embora os irregulares estejam eivados de irregularidades sem consequências ao processo.

### Conceitos
- **Atos perfeitos**: atos cuja prática observou fielmente o modelo legalmente previsto
- **Atos meramente irregulares**: atos válidos e eficazes, mas com irregularidades sem consequências ao processo
- **Irregularidades**: acarretam sanções extraprocessuais ou somente afetam a responsabilidade do agente

### Referências legais
- Art. 319 do Código de Processo Civil
- Súmula nº 366 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre atos perfeitos e irregulares
- Entender que as irregularidades não afetam a eficácia dos atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.587 (2)", "page_number": 587, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319 do Código de Processo Civil", "Súmula nº 366 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T09:39:11.786305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=587", "doc_key": "2b13848688e673276fdfbb443dfa01ef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7e6c510a2d259a339b812a4efd0ab169eed165a39f5f688a787d547ff1cb2c2d'),
  ('cpiuris2025::55a77d1cdaa2f5177403b963e7c5f076', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades', '## Nulidades

Atos nulos são passíveis de decretação de ineficácia, podendo ser absolutos ou relativos. Atos inexistentes não podem ser convalidados.

### Conceitos
- **Sistema formalista**: O meio predomina sobre o fim
- **Sistema legalista**: Somente os atos que a lei expressamente consideram nulos são nulos
- **Sistema instrumental**: A forma deve sucumbir à finalidade do ato
- **Princípio do pas de nullité sans grief**: Nenhum ato é declarado nulo sem prejuízo para a acusação ou defesa

### Referências legais
- Art. 563 e 566 do CPP

### Dicas de prova
- Entenda o conceito de nulidade e as suas classificações
- Conheça os sistemas de nulidades (formalista, legalista e instrumental)
- Aprenda a aplicar o princípio do pas de nullité sans grief', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.588 (1)", "page_number": 588, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563 e 566 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:39:35.896014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=588", "doc_key": "55a77d1cdaa2f5177403b963e7c5f076"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8e4578ab07b274dd356ec967e13775a624aceab56efdc6434fb1fdee73e0e57b'),
  ('cpiuris2025::98a6299aa2584c8a5730d046623f0221', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades e Irregularidades no Processo', '## Nulidades e Irregularidades no Processo

Resumo sobre as nulidades e irregularidades no processo, incluindo suas classificações e consequências.

### Conceitos
- **Isonomia**: Princípio que exige igualdade de tratamento para todas as partes em um processo.
- **Segurança jurídica**: Princípio que visa garantir a estabilidade e previsibilidade do direito.
- **Teoria dos frutos da árvore envenenada**: Teoria que considera que uma irregularidade no processo pode afetar todas as provas apresentadas, tornando-as imprestáveis.
- **Irregularidades ou defeitos sem consequência**: Atos processuais que não trazem consequências para o processo, mesmo que tenham sido praticados de forma irregular.
- **Irregularidades ou defeitos com sanções extraprocessuais**: Atos processuais que acarretam sanções apenas para o advogado ou outorgante, sem afetar a validade do processo.
- **Irregularidades ou defeitos que podem acarretar a invalidade do ato**: Atos processuais que podem levar à declaração de nulidade do ato, caso atenda a interesse público ou às partes envolvidas.
- **Irregularidades ou defeitos que acarretam a inexistência jurídica do ato**: Atos processuais que não existem devido à gravidade da irregularidade, como em casos de impedimento de juiz.

### Referências legais
- Art. 169, §1º, CPC/73

### Dicas de prova
- Entenda a diferença entre nulidades e irregularidades no processo.
- Conheça as classificações de irregularidades e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.587 (1)", "page_number": 587, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 169, §1º, CPC/73"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:39:53.048088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=587", "doc_key": "98a6299aa2584c8a5730d046623f0221"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3f4de034d9056cbbcbdf0dd2ba33e6838ef9f9389a31333d8b9efb61aa2200e2'),
  ('cpiuris2025::f5c1c93d295429c48ad41afcb23eece7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo', '## Nulidades no Processo

A nulidade de ato ou processo pode ser tratada em capítulo próprio, mas não significa que a nulidade seja declarada automaticamente. O princípio do interesse somente se aplica às nulidades relativas e não ao Ministério Público.

### Conceitos
- **Princípio do Interesse**: Somente a parte prejudicada pode argumentar nulidade referente à formalidade cuja observância só à parte contrária interesse.
- **Nulidade Absoluta**: Não há nulidade por omissão de formalidade que só interesse à parte contrária
- **Princípio da Lealdade ou da Boa-Fé**: Nenhuma das partes pode arguir nulidade a que haja dado causa ou para ter concorrido.

### Referências legais
- Art. 565, parte final, do CPP

### Dicas de prova
- Entenda o princípio do interesse e sua aplicação nas nulidades relativas.
- Conheça a diferença entre nulidade absoluta e relativa.
- Não confunda o princípio da lealdade ou boa-fé com o princípio do interesse.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.589 (1)", "page_number": 589, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 565, parte final, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:41:46.318588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=589", "doc_key": "f5c1c93d295429c48ad41afcb23eece7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a17bf3baa9c67996d6e6a88ddce3dfd1649d48361d905551cebe6a74af02d59c'),
  ('cpiuris2025::cdd1cb5f33454a10e16e64ce528629a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de nulidade e efetivo prejuízo', '## Reconhecimento de nulidade e efetivo prejuízo

A jurisprudência firmemente estabelece que o reconhecimento de nulidade exige a comprovação de efetivo prejuízo, de acordo com o princípio pas de nulité sans grief.

### Conceitos
- **Nulidade**: Condição que justifica a anulação de uma decisão ou ato processual
- **Relativa nulidade**: Nulidade que não afeta o mérito da causa, mas sim a procedência do processo
- **Absoluta nulidade**: Nulidade que afeta o mérito da causa e anula completamente o processo
- **Princípio pas de nulité sans grief**: Princípio que estabelece que a nulidade não pode ser reconhecida sem comprovação de efetivo prejuízo

### Referências legais
- Art. 563, do CPP

### Jurisprudência
- AgRg no REsp 1814988/PR
- AgRg no AREsp n. 713.197/MG
- AgRg no AREsp 1490192/SP

### Dicas de prova
- Entenda o conceito de nulidade e suas formas (relativa e absoluta)
- Conheça o princípio pas de nulité sans grief e sua importância
- Análise da jurisprudência firmada pela Corte Superior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.588 (2)", "page_number": 588, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563, do CPP"], "jurisprudence": ["AgRg no REsp 1814988/PR", "AgRg no AREsp n. 713.197/MG", "AgRg no AREsp 1490192/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T09:42:00.448208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=588", "doc_key": "cdd1cb5f33454a10e16e64ce528629a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '143ddb4e8d4297cf8cbd15fc725adf3e354a0e36da041b587ace11376d6e995b'),
  ('cpiuris2025::12e1362ee7f9e643359290b47546d432', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade de Atos Processuais e Consequências', '## Nulidade de Atos Processuais e Consequências

A nulidade de ato processual relevante pode desencadear consequências, como o princípio da causalidade e a dos consequentes. A lei disciplina a renovação ou retificação do vício existente em determinado ato processual.

### Conceitos
- **Nulidade de Atos Processuais**: A declaração de invalidade de um ato processual relevante
- **Princípio da Causalidade**: O princípio que estabelece a relação de causalidade entre os atos processuais
- **Efeito Expansivo**: A expansão do efeito de uma declaração de nulidade para incluir outros atos relacionados
- **Sequencialidade**: A ordem em que os atos processuais devem ser realizados
- **Contaminação ou Consequencialidade**: A relação entre a declaração de nulidade e seus efeitos
- **Renovação ou Retificação**: A ação de renovar ou retificar o vício existente em determinado ato processual
- **Dependência ou Causalidade**: A relação entre os atos processuais que dependem ou são consequências da declaração de nulidade

### Referências legais
- Art. 573, caput, do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a relação entre a nulidade de ato processual e suas consequências
- Discuta a importância da dependência ou causalidade entre os atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.589 (2)", "page_number": 589, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 573, caput, do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:42:40.778055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=589", "doc_key": "12e1362ee7f9e643359290b47546d432"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60f340b33a44d4d9c937a7ff29148628ed19128ce65b4c2b2d9c7c51ae6316b9'),
  ('cpiuris2025::b5603f07b0bb63ec89bec676dedd5697', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da conservação dos atos processuais (confinamento da nulidade)', '## Princípio da conservação dos atos processuais (confinamento da nulidade)

O princípio do confinamento da nulidade ou da conservação dos atos processuais impõe a preservação da validade dos atos posteriores que não dependam ou sejam consequência direta de ato anterior declarado inválido.

### Conceitos
- **Princípio da causalidade**: Declara a declaração de nulidade de ato posterior que dependa ou seja consequência direta de ato anteriormente declarado nulo.
- **Princípio da conversão**: Preserva o ato posterior se não for verificada relação de consequência ou dependência direta com o ato anterior.
- **Atos irrelevantes**: Não são declarados nulos se não influirem na apuração da verdade substancial ou na decisão da causa.

### Referências legais
- Art. 573, §2º, do CPP

### Dicas de prova
- Entenda a diferença entre princípio da causalidade e conversão.
- Conheça o conceito de atos irrelevantes para o deslinde da causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.590 (1)", "page_number": 590, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 573, §2º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:43:59.566643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=590", "doc_key": "b5603f07b0bb63ec89bec676dedd5697"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9cb43472fe5a50b2e5846d01f40d6ace01644c2bbe3019605b3a99e9b410e6fb'),
  ('cpiuris2025::f8465c8f6043510b8d56d304679ddc31', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Convalidação', '## Princípio da Convalidação

O princípio da convalidação não declara a nulidade de atos processuais se for possível suprir o defeito apresentado.

### Conceitos
- **Convalidação**: suprição do defeito em um ato processual
- **Princípio da Convalidação**: não declara a nulidade de atos processuais se for possível suprir o defeito apresentado
- **Aproveitamento**: suprição do defeito em um ato processual
- **Proteção**: suprição do defeito em um ato processual
- **Saneamento**: não é aplicável ao princípio da convalidação
- **Revisão Criminal Pro Societate**: ação autônoma de impugnação, não relacionada à convalidação

### Referências legais
- Art. 585 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Súmula 444/STF

### Dicas de prova
- Entenda a diferença entre saneamento e convalidação
- Conheça as hipóteses de nulidade relativa e absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.590 (2)", "page_number": 590, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Súmula 444/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:44:07.816654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=590", "doc_key": "f8465c8f6043510b8d56d304679ddc31"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '74dff484541f0b5312609d86fc36c9e0ec837d2b2032e0210e9ed34e3dea40ab'),
  ('cpiuris2025::7c31360300e3dc3263dcd25e3773ab8a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades Absolutas', '## Nulidades Absolutas

Nulidades absolutas ocorrem quando o ato processual é eivado de vício que viola o interesse público, como o devido processo legal, ampla defesa e contraditório. O prejuízo presumido é considerado relativo e não absoluto.

### Conceitos
- **Prejuízo Presumido**: consideração que o prejuízo advindo de nulidade absoluta é presumido, mas relativo
- **Inversão do Ónus da Prova**: quando a parte alega a ocorrência de uma nulidade absoluta, ela fica exonerada de provar a existência do prejuízo, enquanto a parte contrária tem que provar a inexistência

### Referências legais
- Art. 156, caput, do CPP

### Jurisprudência
- HC nº 227.263/RJ
- Súmula do STJ

### Dicas de prova
- Entenda o conceito de prejuízo presumido e inversão do ónus da prova
- Conheça as características fundamentais das nulidades absolutas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.591 (1)", "page_number": 591, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 156, caput, do CPP"], "jurisprudence": ["HC nº 227.263/RJ", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:44:17.350023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=591", "doc_key": "7c31360300e3dc3263dcd25e3773ab8a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fc1651da98e01ac4332a06f4a4a66d41005d6732ffbd758bbbc31f035f1876f6'),
  ('cpiuris2025::ad9972a579ab51c9443b336773fe2f24', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição do Julgador e Convalidação', '## Suspeição do Julgador e Convalidação

A suspeição do julgador não influencia o resultado da sessão de julgamento, desde que não haja prejuízo à parte. A convalidação é arguida a qualquer momento, inclusive após o trânsito em julgado.

### Conceitos
- **Suspeição do Julgador**: O estado de incompatibilidade entre o juiz e uma das partes
- **Convalidação**: A ação de sanar ou justificar um vício no processo
- **Princípio do Pas de Nullité Sans Grief**: O princípio que estabelece que a nulidade absoluta não pode ser declarada se não houver prejuízo à parte

### Referências legais
- Art. 585, § 2º, do Código de Processo Civil
- Súmula 646 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a suspeição do julgador e sua influência no resultado da sessão de julgamento
- Entenda o princípio da convalidação e sua aplicabilidade em diferentes momentos do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.591 (2)", "page_number": 591, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 2º, do Código de Processo Civil", "Súmula 646 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:46:26.754125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=591", "doc_key": "ad9972a579ab51c9443b336773fe2f24"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7c138c1ca3d5297cd60ab139fa3be1dd0fef66463e531d54417d2e464718d38b'),
  ('cpiuris2025::e9ca34ef6217fb5e722df80f96d867df', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades e Prequestionamento', '## Nulidades e Prequestionamento

A questão aborda a necessidade de prequestionamento da nulidade absoluta perante os Tribunais Superiores, bem como as características das nulidades relativas, que não têm presunção de prejuízo e devem ser arguidas oportunamente.

### Conceitos
- **Nulidade Absoluta**: Vício que impossibilita a sentença de produzir os efeitos pretendidos pelo autor
- **Nulidade Relativa**: Vício que não impede a sentença de produzir os efeitos pretendidos pelo autor, mas que pode ser removido mediante prequestionamento
- **Prequestionamento**: Ação necessária para que o tribunal superior possa se manifestar sobre uma nulidade absoluta

### Referências legais
- Art. 571 do CPP
- Súmula nº 356 do STF
- Súmula nº 320 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça o conceito de prequestionamento e sua importância
- Lembre-se de que as nulidades relativas não têm presunção de prejuízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.592 (1)", "page_number": 592, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 571 do CPP", "Súmula nº 356 do STF", "Súmula nº 320 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:46:51.178230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=592", "doc_key": "e9ca34ef6217fb5e722df80f96d867df"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '58b92e3bd549b87f1bd30abd53619edaa0821a5bdfdb8e3e666f27acd3308346'),
  ('cpiuris2025::0e9514a595adb2a36060e9b5e7c81579', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Preclusão Temporal e Lógica nas Nulidades Relativas', '## Preclusão Temporal e Lógica nas Nulidades Relativas

A preclusão temporal e lógica são fundamentais para a arguição das nulidades relativas, sendo essas últimas arguidas em sede de alegações orais após a apresentação da resposta à acusação.

### Conceitos
- **Preclusão Temporal**: O decurso do tempo que impede a arguição de uma ação ou defesa
- **Preclusão Lógica**: A aceitação tácita dos efeitos de um ato por parte de uma das partes
- **Nulidades Relativas**: Erros ou omissões no procedimento que podem ser arguidos em sede de alegações orais
- **Arguição de Nulidades**: O processo de apresentar argumentos para justificar a existência de uma nulidade relativa

### Referências legais
- Art. 571 do CPP
- Art. 406, inciso I do CPP
- Art. 411, §§4º, 5º e 6º do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre preclusão temporal e lógica
- Conheça o conceito de nulidades relativas e como serem arguidas
- Interprete corretamente o art. 571 do CPP em face das alterações da legislação processual penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.592 (2)", "page_number": 592, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 571 do CPP", "Art. 406, inciso I do CPP", "Art. 411, §§4º, 5º e 6º do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:47:09.261444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=592", "doc_key": "0e9514a595adb2a36060e9b5e7c81579"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e7e57e7b662e7e2a9c235cd1467295bf562f9f5ee21677d075af960e6925766e'),
  ('cpiuris2025::f593aa1b60711b309fe1872b013168e2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Penal', '## Nulidades no Processo Penal

Regra geral para alegação de nulidades relativas nos processos penais, com mudanças na legislação.

### Conceitos
- **Art. 396-A do CPP**: Dispositivo que estabelece a obrigação de alegar as nulidades relativas após o oferecimento da peça acusatória.
- **Preclusão**: Consequência de não alegar uma questão dentro do prazo legal
- **Nulidade Relativa**: Ocorrência que invalida apenas parte da decisão do juiz, deixando a restante válida.

### Referências legais
- Art. 500 (inciso II) do CPP
- Art. 396-A, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a regra geral para alegação de nulidades relativas nos processos penais.
- Conheça o conceito de preclusão e sua aplicação na legislação processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.593 (1)", "page_number": 593, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 500 (inciso II) do CPP", "Art. 396-A, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:48:37.862817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=593", "doc_key": "f593aa1b60711b309fe1872b013168e2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bfeb6b0e509dd64516f5e2382793ffcf69d9944e5331a72c85c2c296cf7c3905'),
  ('cpiuris2025::487af5fc344bead76ac750f66d78f0a2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Preclusão nas Recursos', '## Preclusão nas Recursos

A preclusão nas alegações escritas ou orais pode ocorrer se não for arguida nas razões recursais ou na sustentação oral. As nulidades relativas podem ser arguidas após a decisão da primeira instância, mas também podem ser consideradas como preliminares no recurso interposto.

### Conceitos
- **Preclusão**: Omissão de argumento relevante que pode resultar em perda do direito de alegá-lo
- **Alegações escritas**: Documentos apresentados pelas partes para sustentar sua defesa
- **Sustentação oral**: Argumentação feita pelas partes em audiência
- **Razões recursais**: Argumentos apresentados pela parte recorrida para justificar a decisão do juiz

### Referências legais
- Art. 11, caput, Lei n.º 8.038/90
- Art. 12, I, Lei n.º 8.038/90
- Art. 571, inciso VII, CPP

### Dicas de prova
- Entenda a noção de preclusão e como ela se aplica às alegações escritas e orais
- Conheça as regras para arguir nulidades relativas nas razões recursais ou na sustentação oral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.593 (2)", "page_number": 593, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 11, caput, Lei n.º 8.038/90", "Art. 12, I, Lei n.º 8.038/90", "Art. 571, inciso VII, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:49:22.063800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=593", "doc_key": "487af5fc344bead76ac750f66d78f0a2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b847c431f8a8a44ca6d3e37a8c6926032613c3dc1db3cbb58f4d2a6739d5e1d2'),
  ('cpiuris2025::5cfdae0ffd66603cc207c66cca8ffde8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades Relativas', '## Nulidades Relativas

Resumo objetivo: Nulidades relativas podem ser arguidas novamente na fase recursal, desde que não forem acolhidas pelo juízo no momento oportuno. Convalidação das nulidades relativas ocorre se as nulidades não forem arguidas no momento oportuno ou se a parte aceitar os seus efeitos.

### Conceitos
- **Nulidade Relativa**: Vício que pode ser arguido novamente na fase recursal, desde que não for acolhida pelo juízo no momento oportuno.
- **Convalidação**: Ato de aceitar os efeitos de um ato relativamente nulo, sanando o vício.
- **Preclusão Temporal**: Fenômeno que ocorre quando uma ação não é arguida no momento oportuno, tornando-a inadmissível na fase recursal.
- **Vício Saneado**: Ato de aceitar os efeitos de um ato relativamente nulo, sanando o vício e tornando-o legítimo.

### Referências legais
- Art. 572 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre nulidades absolutas e relativas.
- Conheça as hipóteses de convalidação das nulidades relativas.
- Aprenda a aplicar o conceito de preclusão temporal em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.594 (1)", "page_number": 594, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 572 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T09:49:46.726022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=594", "doc_key": "5cfdae0ffd66603cc207c66cca8ffde8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8f16973f8cf4ccb57290e3e0930febd86fe9d5e7f3a3f6ff40f54a284e99bcfc'),
  ('cpiuris2025::e38f67596ace3920c5db9206929081d0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no processo penal', '## Nulidades no processo penal

Resumo objetivo em 2-5 frases: Artigos 564, III e IV do CPP tratam de nulidades específicas no processo penal, incluindo ausência de interrogatório, não intimação de réu ou testemunhas, e omissão de formalidade. Essas nulidades podem resultar em nulidade absoluta ou relativa, com possibilidade de convalidação.

### Conceitos
- **Nulidade Absoluta**: Extinção do processo por vício insanável no procedimento
- **Nulidade Relativa**: Extinção do erro ou vício que não é insanável
- **Convalidação**: Aprovação da decisão apesar de nulidade relativa

### Referências legais
- Art. 564, III e IV do CPP

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça as formalidades essenciais no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.594 (2)", "page_number": 594, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III e IV do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:50:38.408647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=594", "doc_key": "e38f67596ace3920c5db9206929081d0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2e2b6f7adc307a3d865672383d376936afd6af4aa5511af688fb2c2fff3a6480'),
  ('cpiuris2025::f602c595959fa6b484671a81bccc5457', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência do Juiz', '## Incompetência do Juiz

A incompetência do juiz gera nulidade absoluta, com presunção de prejuízo, enquanto a competência relativa gera nulidade do tipo relativo.

### Conceitos
- **Incompetência absoluta**: Ração materiae, ratione personae/funcionae ou competência funcional
- **Incompetência relativa**: Em razão do local
- **Nulidade absoluta**: Presunção de prejuízo
- **Nulidade do tipo relativo**: Só afeta os atos decisórios

### Referências legais
- Art. 564, I, 1ª parte, CPP

### Dicas de prova
- Entenda a distinção entre incompetência absoluta e relativa
- Conheça as consequências do reconhecimento da incompetência do juiz
- Não se engane com questões que fazem uma digressão doutrinária/jurisprudencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.595 (1)", "page_number": 595, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, I, 1ª parte, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:51:31.914674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=595", "doc_key": "f602c595959fa6b484671a81bccc5457"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9f11087684693bd9cf7051873554932395202b4301fa6c4060bf6cd92c7778f4'),
  ('cpiuris2025::7508d19ab70952ad696954f9b8395f57', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Necessidade de repetição dos atos decisórios', '## Necessidade de repetição dos atos decisórios

A doutrina majoritária rechaça a diferenciação entre nulidades absoluta e relativa, afirmando que não há necessidade de repetição dos atos decisórios. O STF entendeu que mesmo em caso de incompetência absoluta, pode haver ratificação simples dos atos decisórios.

### Conceitos
- **Nulidade**: Condição que impede a produção de efeito de uma decisão ou ato processual
- **Incompetência absoluta**: O juízo não tem competência para julgar um feito, devido a uma falta absoluta de jurisdição
- **Ratificação**: Ação de reconhecer a validade de um ato ou decisão que já foi considerada nula

### Referências legais
- Art. 564, I, parte final, CPP

### Jurisprudência
- HC n.º 83.006/SP
- Súmula do STF

### Dicas de prova
- Pergunta sobre a necessidade de repetição dos atos decisórios
- Entendimento da doutrina majoritária e do STF
- Distinção entre nulidades absoluta e relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.595 (2)", "page_number": 595, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, I, parte final, CPP"], "jurisprudence": ["HC n.º 83.006/SP", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:52:03.350593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=595", "doc_key": "7508d19ab70952ad696954f9b8395f57"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '39d56fb5b2763d31131af5ae96e6d94e8a5808ebb5b44224ab78f7737087ecac'),
  ('cpiuris2025::b87ea46a62eec0a15079ca7d19e0e9a2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Saneamento da ilegitimidade ad processum', '## Saneamento da ilegitimidade ad processum

O artigo 568 do CPP permite a sanção da ilegitimidade ad processum mediante ratificação dos atos processuais, somente aplicável à nulidade relativa e não à ilegitimidade ad causam.

### Conceitos
- **Ilegitimidade ad processum**: nulidade relativa
- **Ilegitimidade ad causam**: nulidade absoluta
- **Ratificação dos atos processuais**: sanção da ilegitimidade ad processum

### Referências legais
- Art. 568 do CPP

### Dicas de prova
- Entenda a diferença entre nulidade relativa e absoluta.
- Conheça o conceito de ratificação dos atos processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.596 (2)", "page_number": 596, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 568 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:53:04.678154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=596", "doc_key": "b87ea46a62eec0a15079ca7d19e0e9a2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '739f99950a3623bf727ed02422dbba6fc696d50b652473da7839fcc226d21bca'),
  ('cpiuris2025::34f57d100b531f766378cab97df3bf7d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Penal', '## Nulidades no Processo Penal

Descreve as nulidades absolutas e relativas no processo penal, incluindo suspeição do juiz, quebra de imparcialidade, suborno do juiz, ilegitimidade de parte e legitimidade processual.

### Conceitos
- **Suspeição do juiz**: Presunção jure et jure de que o juiz não é totalmente isento para oficiar no feito
- **Quebra de imparcialidade**: Expressões ofensivas, desrespeitosas e pejorativas proferidas pelo magistrado na sessão de julgamento contra a honra do réu
- **Suborno do juiz**: Recebendo o juiz qualquer tipo de vantagem, seja ela financeira ou não, o ato por ele praticado estará eivado de nulidade absoluta
- **Ilegitimidade de parte**: Pertinência subjetiva da ação, ou seja, a situação prevista em lei que permite a um determinado sujeito propor a demanda judicial
- **Legitimidade processual**: Capacidade de estar em juízo, pressuposto processual de validade

### Referências legais
- Art. 564, I, parte final, CPP

### Jurisprudência
- RE 123456
- Info. 743 STJ

### Dicas de prova
- Pergunte sobre a suspeição do juiz e quebra de imparcialidade
- Entenda a diferença entre ilegitimidade ad causam e ilegitimidade ad processum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.596 (1)", "page_number": 596, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, I, parte final, CPP"], "jurisprudence": ["RE 123456", "Info. 743 STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T09:53:28.605467+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=596", "doc_key": "34f57d100b531f766378cab97df3bf7d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5b543a05dba3a3d58aa168eb29b4d6a272de8644712569085570cae6a430d2ac'),
  ('cpiuris2025::75d12ef2a4f32b4456dd82559c9e8cc1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Criminal', '## Nulidades no Processo Criminal

A nulidade do tipo absoluto é verificada pela falta da peça acusatória (denúncia ou queixa-crime) ou das condições de procedibilidade (representação do ofendido ou de seu representante legal ou requisição do Ministro da Justiça). A ausência do exame de corpo de delito, ressalvado o art. 167, também configura nulidade absoluta.

### Conceitos
- **Nulidade Absoluta**: Verificada pela falta da peça acusatória ou das condições de procedibilidade
- **Peca Acusatória**: Denúncia ou queixa-crime necessária para iniciar o processo criminal
- **Representação do Ofendido**: Obrigatório para iniciar o processo criminal em determinadas situações
- **Requisição do Ministro da Justiça**: Hipótese de nulidade que não está expressa no artigo, mas sim na lei

### Referências legais
- Art. 129, inciso I da Constituição Federal
- Art. 564, III, a do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar a nulidade atinente à falta de peça acusatória da hipótese de omissão de formalidade
- Conhecer as condições de procedibilidade necessárias para iniciar o processo criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.597 (1)", "page_number": 597, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, inciso I da Constituição Federal", "Art. 564, III, a do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:54:46.353184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=597", "doc_key": "75d12ef2a4f32b4456dd82559c9e8cc1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eb9e9b987bd9bf1cfed180e09df32e7645ec3af2493f10379339cb0c9e4919d5'),
  ('cpiuris2025::6780e65f0c62e2df14882cdd78f41f0a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade do processo', '## Nulidade do processo

A ausência do exame de corpo de delito não impede a nulidade absoluta do processo, mas se os vestígios desapareceram, pode ser suprida pela prova testemunhal.

### Conceitos
- **Nulidade absoluta**: Extinção do processo por vício em legítima processual
- **Exame de corpo de delito**: Análise dos vestígios físicos coletados no local do crime
- **Prova testemunhal**: Depoimentos de testemunhas que assistiram ao crime
- **Confissão**: Declaração do acusado sobre o crime

### Referências legais
- Art. 564, III, c, CPP

### Dicas de prova
- Distinção entre nulidade absoluta e nulidade relativa
- Importância da nomeação de defensor ao acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.597 (2)", "page_number": 597, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, c, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:54:57.987670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=597", "doc_key": "6780e65f0c62e2df14882cdd78f41f0a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '647e38c22ec68fa1618a22ed9c1d7e137934de6480ea4a07164be8230782a588'),
  ('cpiuris2025::167118c9c4f29dc2688f05b8136f5794', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade de Processo', '## Nulidade de Processo

A falta de defesa técnica acarreta nulidade absoluta, enquanto a sua deficiência gera nulidade do tipo relativa. Além disso, a não intervenção do Ministério Público em todos os termos da ação por ele intentada e nos da intentada pela parte ofendida pode gerar nulidade.

### Conceitos
- **Nulidade Absoluta**: Falta de defesa técnica
- **Nulidade do Tipo Relativa**: Deficiência da defesa
- **Intervenção do Ministério Público**: Obrigação de participar em todos os termos da ação
- **Paridade de Armas**: Direito à igualdade entre as partes
- **Princípio do Interesse**: Direito à defesa do interesse da parte

### Referências legais
- Art. 42 do CPP
- Súmula n.º 523 do STF

### Jurisprudência
- HC n.º 181.306/PE
- ...

### Dicas de prova
- Diferenciar entre nulidade absoluta e nulidade do tipo relativa
- Entender a importância da intervenção do Ministério Público em todos os termos da ação
- Apligar o princípio da paridade de armas e do interesse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.598 (1)", "page_number": 598, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 42 do CPP", "Súmula n.º 523 do STF"], "jurisprudence": ["HC n.º 181.306/PE", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:56:02.873382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=598", "doc_key": "167118c9c4f29dc2688f05b8136f5794"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '14f08b66cb22d07879f50fc83551f013e41b3d37e25702c63a0207207cf32e4a'),
  ('cpiuris2025::4b5858afd74656e3c1bb70ac04c5a6ac', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo', '## Nulidades no Processo

Resumo do texto sobre nulidades no processo penal, incluindo ausência de citação, interrogatório e não concessão de prazos.

### Conceitos
- **Ausência de citação**: A ausência de citação é considerada nulidade absoluta do processo desde o seu início.
- **Interrogatório**: O interrogatório é um ato fundamental para a defesa, e sua ausência ou negação pode resultar em nulidade absoluta.
- **Prazos**: A não concessão de prazos às partes pode acarretar nulidade relativa do ato.

### Referências legais
- Art. 570 do CPP
- Art. 564, III do CPP

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Importância do interrogatório para a defesa
- Cautela com a não concessão de prazos às partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.599 (1)", "page_number": 599, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 570 do CPP", "Art. 564, III do CPP"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T09:56:39.356031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=599", "doc_key": "4b5858afd74656e3c1bb70ac04c5a6ac"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0470c678e059e95dffbc2fc3afd3c998c4d17a09273be749c5c3f5d4baf4a7e0'),
  ('cpiuris2025::0fa8abfdb7465c998035e59789072863', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade na Ação Penal Pública e Privada', '## Nulidade na Ação Penal Pública e Privada

A nulidade absoluta ocorre se o Ministério Público não for intimado a praticar atos instrutórios ou deixar de praticar atos postulatórios. A nulidade relativa ocorre se o Ministério Público é intimado e não pratica os atos instrutórios. Além disso, a ausência de citação do réu para se ver processar, o seu interrogatório e os prazos concedidos à acusação e à defesa também resultam em nulidade.

### Conceitos
- **Nulidade Absoluta**: Ocorre quando o Ministério Público não é intimado a praticar atos instrutórios ou deixar de praticar atos postulatórios.
- **Nulidade Relativa**: Ocorre quando o Ministério Público é intimado e não pratica os atos instrutórios.
- **Citação do Réu**: É o ato pelo qual se dá ciência ao acusado do recebimento de uma peça acusatória oferecida no seu desfavor, chamando-o a se processar.

### Referências legais
- Art. 564, III, CPP
- Art. 5º, inciso LIX, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre nulidade absoluta e relativa
- Entender o conceito de citação do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.598 (2)", "page_number": 598, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, CPP", "Art. 5º, inciso LIX, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:56:48.894206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=598", "doc_key": "0fa8abfdb7465c998035e59789072863"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c876d6b3a0650a8507f4f0d7b50add81e3ac9999702a6d3088dc0ef19d9cb7cd'),
  ('cpiuris2025::0c7600bf6b9fb691089e4b3d8307184d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ausência da decisão de pronúncia e nulidade absoluta do processo', '## Ausência da decisão de pronúncia e nulidade absoluta do processo

A ausência da decisão de pronúncia gera nulidade absoluta do processo, pois é condição imprescindível à submissão do acusado ao julgamento em plenário do Tribunal do Júri.

### Conceitos
- **Decisão de pronúncia**: decisão que encerra a primeira fase do procedimento do Júri
- **Nulidade absoluta do processo**: estado processual em que o processo é anulado por completo
- **Elocuência acusatória**: falta de limitação da decisão de pronúncia, permitindo indevida influência no animus judicandi dos jurados

### Referências legais
- Art. 564, III, F, 1ª parte, CPP

### Dicas de prova
- Pergunte se a ausência da decisão de pronúncia gera nulidade absoluta do processo.
- Entenda o conceito de eloquência acusatória e como ela afeta a decisão de pronúncia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.599 (2)", "page_number": 599, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, F, 1ª parte, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:58:57.879116+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=599", "doc_key": "0c7600bf6b9fb691089e4b3d8307184d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f668b9153aa55d06bb12fe1513eec504fd2e5a3da55f3ce8e7e4ae97dfb5b71f'),
  ('cpiuris2025::6dc25fe819c6485ed9a4c56964f17426', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade do processo e intimação das testemunhas', '## Nulidade do processo e intimação das testemunhas

Resumo objetivo: Nulidade do processo por falta de intimação do acusado ou das testemunhas, com a consequente lesão à garantia constitucional da ampla defesa. Além disso, a extinção do libelo acusatório e da contrariedade determina que as partes devem arrolar as testemunhas que querem ouvir na sessão plenária.

### Conceitos
- **Nulidade do processo**: Fato que impede a continuidade do processo
- **Intimação**: Notificação formal de uma pessoa sobre um ato processual
- **Ampla defesa**: Direito do acusado de se defender adequadamente
- **Falta de intimação**: Omissão que impede a notificação adequada de uma pessoa sobre um ato processual

### Referências legais
- Art. 570 do CPP
- Art. 564, III, h do CPP

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Importância da intimação das testemunhas
- Consequências da extinção do libelo acusatório e da contrariedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.600 (2)", "page_number": 600, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 570 do CPP", "Art. 564, III, h do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T09:59:15.682312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=600", "doc_key": "6dc25fe819c6485ed9a4c56964f17426"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '08e1c71af1fdbb7428a7c58cf61c5e104c3e3307722d3137fa18d9626a06b425'),
  ('cpiuris2025::93064d7942812308217a2db3bb71adf9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo do Júri', '## Nulidades no Processo do Júri

Resumo objetivo: Nulidades no processo do júri, incluindo falta de libelo acusatório e não intimação do acusado. A reforma processual permitiu o julgamento em sessão plenária sem a presença do acusado, mas isso não impede a nulidade se o réu não for regularmente intimado.

### Conceitos
- **Nulidade**: Condição que invalida um ato processual
- **Intimação**: Notificação formal do acusado sobre o processo
- **Sessão de julgamento**: Ato em que o tribunal decide a punição do réu
- **Revelia**: Julgamento sem a presença do acusado
- **Autodefesa**: Direito do réu de se defender em si mesmo

### Referências legais
- Art. 564, III, g, CPP
- Art. 572, CPP
- Lei n.º 11.689/08

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre nulidade e preclusão temporal
- Entender a importância da intimação do acusado no processo do júri
- Conhecer as regras de autodefesa do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.600 (1)", "page_number": 600, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, g, CPP", "Art. 572, CPP", "Lei n.º 11.689/08"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T09:59:38.333030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=600", "doc_key": "93064d7942812308217a2db3bb71adf9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd7ad51154de53272e31b70346c90b97ff490ebba39cc24ceb9523547f1f4ee6a'),
  ('cpiuris2025::a90904d1f5d14581ee0d3e7a40c2de7f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo', '## Nulidades no Processo

Resumo do artigo sobre nulidades no processo penal, destacando as regras de intimação de testemunhas e a constituição do júri.

### Conceitos
- **Imprescindibilidade**: O dever de declarar expressamente que o depoimento é imprescindível para a parte que o arrolou.
- **Intimação por Mandado**: A forma de intimação da testemunha, quando solicitada pela parte que a arrolou.
- **Nulidade Absoluta**: O tipo de nulidade que se aplica quando o direito à prova é violado, como no caso de não intimação de testemunha.

### Referências legais
- Art. 461 do CPP
- Art. 564, inciso III, alínea h, do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a constituição do júri

### Dicas de prova
- Entenda o conceito de imprescindibilidade e sua importância na intimação de testemunhas.
- Conheça as regras para a intimação de testemunhas e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.601 (1)", "page_number": 601, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 461 do CPP", "Art. 564, inciso III, alínea h, do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a constituição do júri"], "confidence": 0.8, "extracted_at": "2026-05-29T10:01:20.284863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=601", "doc_key": "a90904d1f5d14581ee0d3e7a40c2de7f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f430114fb0bc9b5eb9a00c1e85e1489ef17f5f0d5af94a6dd5950c21213d3b10'),
  ('cpiuris2025::47da6a6b3cb449017687fc53e0143ebc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Constituição e composição do Júri', '## Constituição e composição do Júri

A constituição do Júri requer pelo menos 15 dos 25 jurados convocados. A ausência de jurados pode resultar em nulidade absoluta se o juiz presidente decidir realizar a sessão de julgamento.

### Conceitos
- **Júri**: órgão judiciário que decide os casos criminais
- **Constituição do Júri**: procedimento pelo qual o Júri é composto por jurados
- **Impedimento, suspeição ou incompatibilidade**: motivos que excluem um jurado da composição do Júri

### Referências legais
- Art. 463, caput, do CPP
- Art. 564, inciso III, alínea i, do CPP

### Jurisprudência
- HC n.º 88.801/SP
- STF - julgamento do HC n.º 88.801/SP

### Dicas de prova
- Entenda a importância da composição do Júri e os motivos que excluem um jurado.
- Conheça as regras para a realização da sessão de julgamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.601 (2)", "page_number": 601, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 463, caput, do CPP", "Art. 564, inciso III, alínea i, do CPP"], "jurisprudence": ["HC n.º 88.801/SP", "STF - julgamento do HC n.º 88.801/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T10:01:33.635030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=601", "doc_key": "47da6a6b3cb449017687fc53e0143ebc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '25a085f6ee574beb4c3c85315a32a3b10e36895b6e73d01494dc9d086fb400d4'),
  ('cpiuris2025::5dd4414a6be0937f2e918621772ad803', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Tribunal do Júri', '## Nulidades no Tribunal do Júri

Resumo objetivo: Discute as nulidades que podem ser declaradas em um julgamento do Tribunal do Júri, incluindo a falta de sorteio dos jurados, a participação de jurados impedidos e a violação da incomunicabilidade.

### Conceitos
- **Nulidade absoluta**: Declaração de nulidade que não pode ser revertida
- **Sorteio dos jurados**: Procedimento pelo qual os jurados são sorteados para a formação do Conselho de Sentença
- **Incomunicabilidade dos jurados**: Característica constitucional que proíbe as comunicações entre os jurados durante o julgamento

### Referências legais
- Art. 467 do CPP
- Art. 564, III, j, 1ª parte do CPP
- Art. 449, inciso I do CPP
- Súmula nº 206 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a participação de jurados impedidos

### Dicas de prova
- Diferenciar entre nulidade absoluta e nulidade relativa
- Entender a importância do sorteio dos jurados para evitar a nulidade
- Conhecer as hipóteses que levam à declaração de nulidade da participação de um jurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.602 (1)", "page_number": 602, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 467 do CPP", "Art. 564, III, j, 1ª parte do CPP", "Art. 449, inciso I do CPP", "Súmula nº 206 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a participação de jurados impedidos"], "confidence": 0.8, "extracted_at": "2026-05-29T10:02:16.387331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=602", "doc_key": "5dd4414a6be0937f2e918621772ad803"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '16e91134d77e66495855a87a5d6fe102e87b6ba7d9e68ce3d8e625e41821503a'),
  ('cpiuris2025::df8f85a55ca7ed3ae879461f5319b379', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incomunicabilidade dos jurados', '## Incomunicabilidade dos jurados

A violação da incomunicabilidade dos jurados gera nulidade do tipo relativa, limitada ao momento e à demonstração do prejuízo.

### Conceitos
- **incomunicabilidade**: Falta de contato entre os jurados e a parte ou terceira pessoa
- **nulidade do tipo relativo**: Nulidade que se limita ao momento e à demonstração do prejuízo

### Referências legais
- Art. 564, III, k do CPP

### Jurisprudência
- RE 123456
- Súmula 376/STJ

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Importância da incomunicabilidade nos julgamentos do Tribunal do Júri', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.602 (2)", "page_number": 602, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, k do CPP"], "jurisprudence": ["RE 123456", "Súmula 376/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T10:02:56.864910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=602", "doc_key": "df8f85a55ca7ed3ae879461f5319b379"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4325e10e9044fd79036e9c58166a1f7997bd0aa6cc3aa6ffcf72a0436ad0a548'),
  ('cpiuris2025::5d83c95d7224c2ce637e9517b132932f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ausência do acusador e defensor no julgamento', '## Ausência do acusador e defensor no julgamento

A ausência do acusador e defensor no julgamento é considerada nula. A falta do advogado do querelante pode dar ensejo à perempção, extinguindo-se a punibilidade do agente.

### Conceitos
- **Nulidade**: Condição que invalida um ato ou processo
- **Perempção**: Extinção da punibilidade do agente
- **Ação penal exclusivamente privada ou personalíssima**: Tipo de ação penal iniciada por uma pessoa

### Referências legais
- Art. 326 do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar as consequências da falta do advogado do querelante e da ausência do órgão do Ministério Público
- Entender a importância da perempção na extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.603 (2)", "page_number": 603, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 326 do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:04:04.972363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=603", "doc_key": "5d83c95d7224c2ce637e9517b132932f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0b8c6544f6c610a2cb3ba962dba29e269977f792862a70a866cb5c6baca7326f'),
  ('cpiuris2025::ee8f0e2aa942ed9caae355d3d285786d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no julgamento do Tribunal do Júri', '## Nulidades no julgamento do Tribunal do Júri

Resumo objetivo: Nulidades no julgamento do Tribunal do Júri, incluindo a obrigação do juiz presidente de explicar os quesitos aos jurados e a preclusão que pode ocorrer se as nulidades não forem impugnadas no momento apropriado.

### Conceitos
- **Nulidade absoluta**: Nulidade do julgamento que não pode ser alegada após o trânsito em julgado
- **Nulidade relativa**: Nulidade que pode ser alegada após o trânsito em julgado, desde que impugnada no momento apropriado
- **Preclusão**: Oportunidade de impugnar uma nulidade após o trânsito em julgado

### Referências legais
- Art. 484, parágrafo único, do CPP
- Art. 564, parágrafo único, c/c art. 571, inciso VIII, do CPP
- Lima, 2017, p. 1622

### Jurisprudência
- Súmula nº 156 do STF
- Súmula n.º 162 do STF

### Dicas de prova
- Entenda a distinção entre nulidade absoluta e relativa
- Conheça o artigo 564, parágrafo único, c/c art. 571, inciso VIII, do CPP
- Lembre-se de que as nulidades podem ser impugnadas após o trânsito em julgado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.603 (1)", "page_number": 603, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 484, parágrafo único, do CPP", "Art. 564, parágrafo único, c/c art. 571, inciso VIII, do CPP", "Lima, 2017, p. 1622"], "jurisprudence": ["Súmula nº 156 do STF", "Súmula n.º 162 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:04:28.844289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=603", "doc_key": "ee8f0e2aa942ed9caae355d3d285786d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b4a9d2b8588639852bdd4431372533925ee8145ddbc094d4f7be85d97cc9d65a'),
  ('cpiuris2025::9071bc55683a2ef36726f10dcd50d428', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo', '## Nulidades no Processo

Resumo sobre as nulidades absolutas e relativas no processo penal, incluindo falta de sentença, recurso de ofício, intimação e negligência do advogado.

### Conceitos
- **Falta de sentença**: Nulidade absoluta que resulta da ausência de sentença
- **Recurso de ofício**: Mecanismo que permite o reexame da matéria pelo Tribunal ad quem
- **Intimação**: Notificação das partes sobre as decisões recorríveis
- **Negligência do advogado**: Omissão injustificada do advogado que pode permitir a retomada do processo pelo MP

### Referências legais
- Art. 60, III, do CPP; Art. 107, IV, do CP; Art. 29 do CPP; Art. 564, III, m, do CPP

### Jurisprudência
- Súmula n.º 423 do STF; Súmula n.º 431 do STF

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa no processo penal
- Conheça as condições para o recurso de ofício e sua importância
- Avalie a importância da intimação nas decisões recorríveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.604 (1)", "page_number": 604, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 60, III, do CPP; Art. 107, IV, do CP; Art. 29 do CPP; Art. 564, III, m, do CPP"], "jurisprudence": ["Súmula n.º 423 do STF; Súmula n.º 431 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:05:22.301231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=604", "doc_key": "9071bc55683a2ef36726f10dcd50d428"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bd0b4ceb45cc2506dc097f47fdd04924da38b5bc0ead2ecdc2109db0345e6a98'),
  ('cpiuris2025::9c02c2c809c8a02d676568e31f56e39d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ampla Defesa no Julgamento', '## Ampla Defesa no Julgamento

A não intimação previa da defesa sobre a data da sessão de julgamento pode resultar em nulidade absoluta do julgamento, devido à violação à ampla defesa.

### Conceitos
- **Ampla Defesa**: Direito ao contraditório e ao devido processo
- **Julgamento**: Procedimento pelo qual se decide o mérito da ação
- **Nulidade Absoluta**: Condição necessária para a anulação do processo

### Referências legais
- Art. 564, III, CPP

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Importância da ampla defesa no julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.604 (2)", "page_number": 604, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:05:39.563844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=604", "doc_key": "9c02c2c809c8a02d676568e31f56e39d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '256b1103e5f3fba8d14d195c245032ab986271a1deb8a368b76f847e26854c5a'),
  ('cpiuris2025::5209593680bb63ce84ea1fb6bc932442', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Omissão de formalidade que constitui elemento essencial do ato', '## Omissão de formalidade que constitui elemento essencial do ato

A nulidade por omissão de formalidade que constitui elemento essencial do ato é prevista no art. 564, IV, do CPP e pode ser absoluta ou relativa, dependendo da gravidade da violação ao devido processo legal.

### Conceitos
- **Omissão de formalidade**: Elemento essencial do ato que não foi cumprido
- **Nulidade absoluta**: Vício que impede a existência do ato ou da decisão
- **Nulidade relativa**: Vício que afeta a validade do ato, mas não a sua existência
- **Devido processo legal**: Princípio que exige que os procedimentos judiciais sejam justos e imparciais

### Referências legais
- Art. 564, IV, do CPP

### Jurisprudência
- HC nº 85.636/PI
- ...

### Dicas de prova
- Pergunte sobre a diferença entre nulidade absoluta e relativa
- Entenda o conceito de devido processo legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.605 (1)", "page_number": 605, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, IV, do CPP"], "jurisprudence": ["HC nº 85.636/PI", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:06:47.357927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=605", "doc_key": "5209593680bb63ce84ea1fb6bc932442"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '730f02d730706fca53601f17330992c9c7c3aa68461052d2af7f459b6fdb7942'),
  ('cpiuris2025::f400e30bda5d5e349d3a60302abb84c0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ausência de fundamentação e nulidade do processo', '## Ausência de fundamentação e nulidade do processo

A ausência de fundamentação na decisão carente de fundamentação pode ser alegada em qualquer momento, com presunção de prejuízo, devido à natureza constitucional do devido processo legal.

### Conceitos
- **inépcia**: ausência de argumentação ou fundamento suficiente
- **nulidade**: anulação total da decisão ou processo
- **fundamentação**: explicação lógica e justificativa das decisões tomadas
- **devido processo legal**: procedimento justo e razoável

### Referências legais
- Art. 564, V, CPP
- Art. 93, IX, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo do devido processo legal

### Dicas de prova
- Entenda a diferença entre inépcia e nulidade.
- Conheça o conceito de fundamentação e sua importância no processo judicial.
- Aprenda a aplicar a regra da ausência de fundamentação em decisões carentes de fundamentação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.605 (2)", "page_number": 605, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, V, CPP", "Art. 93, IX, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo do devido processo legal"], "confidence": 0.8, "extracted_at": "2026-05-29T10:07:27.570570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=605", "doc_key": "f400e30bda5d5e349d3a60302abb84c0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0d69b779b4d1c3a7dec84f6fcbcebf6776db8bd974b5736c81a818e5b3e3b0fc'),
  ('cpiuris2025::b91240169afbb9c930f56d856aa1c291', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Criminal', '## Nulidades no Processo Criminal

Resumo objetivo: Nulidades no processo criminal, definidas pelo Código de Processo Penal (CPP) e reforçadas pela Lei n.º 13.964/19, incluem decisões fundamentadas inadequadas ou ausentes.

### Conceitos
- **Decisão não fundamentada**: Decisão judicial que não explica claramente sua relação com a causa ou questão decidida.
- **Falta de intimação**: Omissão da intimação da expedição de precatória para inquirição de testemunha.
- **Nulidade do julgamento pelo júri**: Julgamento pelo júri que não segue os quesitos obrigatórios ou precedentes.

### Referências legais
- Art. 315, §2º, CPP

### Jurisprudência
- Súmula n.º 155, STF
- Súmula n.º 156, STF
- Súmula n.º 160, STF
- Súmula n.º 162, STF
- Súmula n.º 206, STF

### Dicas de prova
- Distinção entre decisões fundamentadas e não fundamentadas.
- Importância da intimação na ação penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.606 (1)", "page_number": 606, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 315, §2º, CPP"], "jurisprudence": ["Súmula n.º 155, STF", "Súmula n.º 156, STF", "Súmula n.º 160, STF", "Súmula n.º 162, STF", "Súmula n.º 206, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:08:10.344116+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=606", "doc_key": "b91240169afbb9c930f56d856aa1c291"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b57970dadb9f22c98d4ebcaab27593ee624c9f638198c7763b1c8112799aa506'),
  ('cpiuris2025::65945ef9790387461db4857258374671', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação por edital e intimação em processos criminais', '## Citação por edital e intimação em processos criminais

Resumo objetivo sobre a nulidade da citação por edital e a importância da intimação no processo penal.

### Conceitos
- **Citação por edital**: Método de notificação do réu para comparecer à audiência
- **Intimação**: Notificação formal do réu ou de terceiro sobre a decisão do juiz
- **Nulidade absoluta**: Condição em que uma atitude do juiz é considerada ilegal e deve ser corrigida
- **Falta de defesa**: Situação em que o réu não tem a oportunidade de defender-se adequadamente

### Referências legais
- Art. 557, Código de Processo Penal
- Súmula n.º 351, STF

### Jurisprudência
- RE 123456
- Súmula n.º 523, STF

### Dicas de prova
- Diferenciar entre citação por edital e intimação
- Entender a importância da intimação no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.606 (2)", "page_number": 606, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 557, Código de Processo Penal", "Súmula n.º 351, STF"], "jurisprudence": ["RE 123456", "Súmula n.º 523, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:08:36.409397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=606", "doc_key": "65945ef9790387461db4857258374671"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ff17d7d4921a1d828273e5ee04bef98cd7c4c87f49228cb73fdc12261b49fa18'),
  ('cpiuris2025::6f5391c68307d48d1a3861aeb78177ae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no processo penal', '## Nulidades no processo penal

Resumo do trecho: Discute-se a existência de nulidade em decisão que tranca a ação penal por ausência de prova da contrapartida oferecida pelo agente público ao corruptor. A Corte de origem decidiu a controvérsia de maneira fundamentada, enfrentando os aspectos relevantes da questão.

### Conceitos
- **Nulidade**: Condição que impede a validade de uma decisão ou ato processual
- **Competência penal**: A capacidade do juiz de julgar um caso
- **Intimação**: Notificação formal ao réu ou a seu advogado
- **Denúncia**: Ação processual que apresenta os fatos do crime à Justiça

### Referências legais
- Art. 619 do CPP
- Súmula n.º 706 da STF
- Súmula n.º 707 da STF
- Súmula n.º 708 da STF
- Súmula n.º 712 da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo do recurso especial

### Dicas de prova
- Entenda a noção de nulidade e sua importância no processo penal
- Conheça as regras de competência penal e intimação
- Aprenda com o caso para entender a aplicação prática da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.607 (1)", "page_number": 607, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 619 do CPP", "Súmula n.º 706 da STF", "Súmula n.º 707 da STF", "Súmula n.º 708 da STF", "Súmula n.º 712 da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo do recurso especial"], "confidence": 0.8, "extracted_at": "2026-05-29T10:09:01.824169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=607", "doc_key": "6f5391c68307d48d1a3861aeb78177ae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd604367442999c566c0b20f6ab8729ebb5c8420495fa0a0bf2d6c9fe401390bd'),
  ('cpiuris2025::9a311ad6c50abb2d2e964aef58bfc629', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incomunicabilidade dos jurados e nulidade', '## Incomunicabilidade dos jurados e nulidade

A quebra da incomunicabilidade dos jurados é considerada nulidade relativa, que deve ser argüida em momento oportuno e acompanhada de comprovação do real prejudício à defesa.

### Conceitos
- **nulidade**: anulação parcial ou total de um processo
- **incomunicabilidade dos jurados**: restrição ao contato entre os membros do júri
- **nulidade relativa**: anulação parcial de uma decisão

### Referências legais
- Art. 185 do Código de Processo Penal

### Jurisprudência
- HC 82.661/RR
- HC 36.678/PB

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa.
- Conheça o prazo para arguir a nulidade.
- Aprenda a comprovar o prejudício à defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.608 (2)", "page_number": 608, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185 do Código de Processo Penal"], "jurisprudence": ["HC 82.661/RR", "HC 36.678/PB"], "confidence": 0.8, "extracted_at": "2026-05-29T10:11:02.952828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=608", "doc_key": "9a311ad6c50abb2d2e964aef58bfc629"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '694fbccb04769d4a88fd02d7421b1d5afc00978fd47c7dfe6219c99b51738ba3'),
  ('cpiuris2025::7a160572aa976f90245e7eba46b6ce1c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Penal', '## Nulidades no Processo Penal

Resumo do texto sobre nulidades no processo penal, incluindo a vedação à dupla incriminação e a garantia contra a dupla incriminação.

### Conceitos
- **Dupla Incriminação**: Instituição de vedação à dupla incriminação por meio dos Decretos 678/1992 e 592/1992
- **Garantia contra a Dupla Incriminação**: Garantia constitucional que proíbe a aplicação de duas ações penais referentes aos mesmos fatos em diferentes instâncias
- **Tese de Independência entre Instâncias**: Não incide quando as demandas são de natureza criminal e tratam de imputações idênticas

### Referências legais
- Art. 127, §1º, da CF/1988
- Súmula 115 do STF
- Art. 350 do Código Eleitoral

### Jurisprudência
- REsp n. 1.847.488/SP
- Inquérito 4.435/DF

### Dicas de prova
- Entenda a vedação à dupla incriminação e a garantia contra a dupla incriminação no processo penal
- Identifique as nulidades que podem ser reconhecidas em um processo penal
- Aprenda com o caso Resp n. 1.847.488/SP para entender a aplicação da Súmula 115 do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.608 (1)", "page_number": 608, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 127, §1º, da CF/1988", "Súmula 115 do STF", "Art. 350 do Código Eleitoral"], "jurisprudence": ["REsp n. 1.847.488/SP", "Inquérito 4.435/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:12:00.492580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=608", "doc_key": "7a160572aa976f90245e7eba46b6ce1c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e8fa28cb797acb28a368c8f3f6f7566068a1a291ed970f0b4bd91acd952ed72c'),
  ('cpiuris2025::b7832c9b75ed16477bcb49d78dff4556', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Proteção contra a dupla incriminação', '## Proteção contra a dupla incriminação

A sentença da Justiça Especializada é um obstáculo para o prosseguimento da ação penal, devido à vedação à dupla incriminação.

### Conceitos
- **Ne bis in idem**: Garantia que proíbe a reincorporação de uma pessoa acusada por crime em processo para outro processo com o mesmo fato.
- **Double Jeopardy Clause**: Princípio que proíbe a reincorporação de uma pessoa acusada por crime em processo para outro processo com o mesmo fato.
- **Vedação à dupla incriminação**: Princípio que proíbe a reincorporação de uma pessoa acusada por crime em processo para outro processo com o mesmo fato.
- **Coisa julgada**: Conceito jurídico que se refere à decisão final e irrevogável do juiz em um processo.
- **Princípio da vedação à dupla incriminação**: Princípio que proíbe a reincorporação de uma pessoa acusada por crime em processo para outro processo com o mesmo fato.

### Referências legais
- Art. 5º, XXXVI; Art. 317, §1º, do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de coisa julgada e como ela se relaciona com a vedação à dupla incriminação.
- Identifique o princípio da vedação à dupla incriminação e como ele é aplicado na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.607 (2)", "page_number": 607, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXVI; Art. 317, §1º, do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:12:16.863718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=607", "doc_key": "b7832c9b75ed16477bcb49d78dff4556"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '82bbfc84ac923e0c105adf7678664cc2cbbb6fffd50b8847a4e39b7bbfd28b5f'),
  ('cpiuris2025::2b4782f6830b9558a88fca59f84ae19f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades processuais penais', '## Nulidades processuais penais

As nulidades processuais penais podem ser absolutas ou relativas e dependem do prejuízo para a acusação ou defesa.

### Conceitos
- **Prejuízo**: ocorrência necessária para decretação de nulidade
- **Nulidade absoluta**: não há prejuízo para a acusação ou defesa
- **Nulidade relativa**: há prejuízo, mas pode ser arguida
- **Instrumentalidade do processo**: influência na declaração de nulidade

### Referências legais
- Art. 585 do Código de Processo Penal

### Jurisprudência
- Súmula 387/STF

### Dicas de prova
- Distinção entre prejuízo para a acusação e defesa
- Importância da instrumentalidade do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.609", "page_number": 609, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do Código de Processo Penal"], "jurisprudence": ["Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:12:57.338174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=609", "doc_key": "2b4782f6830b9558a88fca59f84ae19f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cabb9e911aecdcb31a91d64a7d68c8eddf817e371fd03f13bcc407994306323a'),
  ('cpiuris2025::b90d69f2fb6e99206811ece82814f5f1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de nulidade de citação', '## Reconhecimento de nulidade de citação

O Ministério Público pode pleitear a reconhecimento da nulidade de citação, seja absoluta ou relativa, com base em deficiência de defesa.

### Conceitos
- **nulidade absoluta**: ocorrência que invalida toda a citação
- **nulidade relativa**: ocorrência que invalida apenas parte da citação
- **deficiência de defesa**: situação em que uma das partes não teve oportunidade igualitária de defender-se

### Referências legais
- Art. 571, inciso V, CPP

### Jurisprudência
- Súmula nº 366 do STF

### Dicas de prova
- Diferenciar entre nulidade absoluta e relativa
- Entender a importância da deficiência de defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.610 (2)", "page_number": 610, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 571, inciso V, CPP"], "jurisprudence": ["Súmula nº 366 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:13:55.260628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=610", "doc_key": "b90d69f2fb6e99206811ece82814f5f1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b9b2fcc2333188e144ca3f4acd52517bddc2c2e2ff0c13bdcb6f73319dcc20bc'),
  ('cpiuris2025::f41fbc667c98e45054bcdb036e2d9285', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Penal', '## Nulidades no Processo Penal

Resumo do texto sobre nulidades em processo penal, destacando as diferenças entre nulidade absoluta e relativa.

### Conceitos
- **nulidade absoluta**: ocorre independentemente de comprovação de prejuízo para o réu
- **nulidade relativa**: exige comprovação de efetivo prejuízo para a parte
- **pas de nulité sans grief**: princípio que exige comprovação de efetivo prejuízo para a declaração de nulidade
- **instrumentalidade das formas**: princípio que prioriza o resultado legalmente previsto sobre a forma do ato processual

### Referências legais
- Art. 563, CPP; Art. 566, CPP

### Jurisprudência
- AgRg no REsp 1814988/PR
- REYNALDO SOARES DA FONSECA

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça o princípio do pas de nulité sans grief
- Aprenda sobre a instrumentalidade das formas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.610 (1)", "page_number": 610, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563, CPP; Art. 566, CPP"], "jurisprudence": ["AgRg no REsp 1814988/PR", "REYNALDO SOARES DA FONSECA"], "confidence": 0.8, "extracted_at": "2026-05-29T10:14:26.000320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=610", "doc_key": "f41fbc667c98e45054bcdb036e2d9285"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e825cb8a1183880bac6b97c24a288315728b06e4d1479b86db8f437ec74f979'),
  ('cpiuris2025::ec157e005ec279ae0111d85cf7b94f4f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidades no Processo Penal', '## Nulidades no Processo Penal

Resumo do texto sobre nulidades no processo penal, incluindo competência do juiz, ilegitimidade do representante e citação.

### Conceitos
- **Competência do Juiz**: A competência do juiz é fundamental para a validade dos atos processuais.
- **Ilegitimidade do Representante**: A ilegitimidade do representante da parte pode ser sanada mediante ratificação dos atos processuais.
- **Citação**: O comparecimento espontâneo do réu é suficiente para sanar a falta ou nulidade da citação.

### Referências legais
- Art. 565 do CPP
- Art. 567 do CPP
- Art. 568 do CPP
- Art. 569 do CPP

### Jurisprudência
- Súmula n.º 523 da STF

### Dicas de prova
- Entenda a competência do juiz e a ilegitimidade do representante para evitar erros comuns.
- Conheça as regras sobre citação e comparecimento espontâneo para evitar nulidades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.611", "page_number": 611, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 565 do CPP", "Art. 567 do CPP", "Art. 568 do CPP", "Art. 569 do CPP"], "jurisprudence": ["Súmula n.º 523 da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:15:22.636503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=611", "doc_key": "ec157e005ec279ae0111d85cf7b94f4f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '634bfecbc084fe8d0cd93870a46768cff7e65a89033e2c84dfea83f2fd79003c'),
  ('cpiuris2025::65a6554e1ea5a07e148089f1567f3265', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal', '## Recurso Criminal

O recurso criminal é uma etapa adicional da ação penal, que pode ser interposto antes ou após a formação da preclusão ou da coisa julgada. A natureza jurídica do recurso é objeto de debate entre as correntes doutrinárias.

### Conceitos
- **Preclusão**: Condição que se forma quando não pode mais ser alegada uma questão de direito ou fato
- **Cosa julgada**: Decisão final do juiz que não pode mais ser objeto de recurso ou apelação
- **Desenvolvimento da relação jurídica processual**: O recurso não cria uma nova relação jurídica, mas sim desdobra a relação anterior em um órgão jurisdicional diverso e de hierarquia superior

### Referências legais
- Art. 574 do Código de Processo Penal
- Art. 646 do Código de Processo Penal

### Jurisprudência
- STF. 2ª Turma. Rcl 43007 AgR/DF
- TÁVORA; ALENCAR, 2017

### Dicas de prova
- Entenda a diferença entre recurso e impugnação
- Conheça as correntes doutrinárias sobre a natureza jurídica do recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.614", "page_number": 614, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do Código de Processo Penal", "Art. 646 do Código de Processo Penal"], "jurisprudence": ["STF. 2ª Turma. Rcl 43007 AgR/DF", "TÁVORA; ALENCAR, 2017"], "confidence": 0.8, "extracted_at": "2026-05-29T10:16:55.282697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=614", "doc_key": "65a6554e1ea5a07e148089f1567f3265"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '286e10d9f04f154a42c47c75d94f6a622a27150af1e0c31827eb04a14d8b3fbe'),
  ('cpiuris2025::7e7335ca5120430a3baf4964bf1a0240', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Duplo Grau de Jurisdição', '## Duplo Grau de Jurisdição

A dupla grau de jurisdição é a possibilidade de reexame integral da decisão do juiz a quo por um órgão jurisdicional diverso e hierarquicamente superior. É uma garantia constitucional implícita, inserida na garantia do devido processo legal e no direito à ampla defesa.

### Conceitos
- **Duplo Grau de Jurisdição**: Possibilidade de reexame integral da decisão do juiz a quo por um órgão jurisdicional diverso e hierarquicamente superior
- **Garantia Constitucional Implícita**: Garantia constitucional que não é expressa, mas está inserida na garantia do devido processo legal e no direito à ampla defesa
- **Devido Processo Legal**: Direito ao processo justo e imparcial
- **Ampla Defesa**: Direito à representação adequada e eficaz

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda que o duplo grau de jurisdição é uma garantia constitucional implícita e não expressa.
- Conheça as exceções em que não há recurso, como a negação da suspensão do processo ou a decisão sobre alegações de suspeição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.615 (1)", "page_number": 615, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:17:51.762415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=615", "doc_key": "7e7335ca5120430a3baf4964bf1a0240"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2ae2ec5d7d30c623480ee267c78032275677d75a2d6e30ae551f22571af77904'),
  ('cpiuris2025::774bf1be23373faccc341e2926960e58', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Crimininal', '## Recurso Crimininal

O recurso é um instrumento processual voluntário de impugnação de decisões judiciais, previsto em lei federal, utilizado antes da preclusão e na mesma relação jurídica processual, objetivando a reforma, a invalidação, a integração ou o esclarecimento da decisão judicial impugnada.

### Conceitos
- **Voluntariedade**: A existência de um recurso está condicionada à manifestação da vontade da parte.
- **Previsão Legal**: Para que um recurso possa ser conhecido, é indispensável a análise do cabimento, compreendido pela doutrina como a previsão legal da existência do recurso.
- **Duplo Grau de Jurisdição**: Garantia individual prevista implicitamente na Constituição Federal, voltada a assegurar que as decisões proferidas pelos órgãos de primeiro grau do Poder Judiciário não sejam únicas, mas sim, submetidas a um juízo de reavaliação por instância superior.
- **Recurso de Ofício**: Não tem natureza recursal, pois é gravado pela voluntariedade.
- **Defensor Público ou Dativo**: A característica da voluntariedade dos recursos também se aplica ao Defensor Público ou dativo.
- **Irrecorribilidade**: Se a lei não prevê recurso contra determinada decisão, significa dizer que tal decisão é irrecorrível.
- **Habeas Corpus ou Mandado de Segurança**: Pode ser utilizado para questionar a matéria em preliminar de futura e eventual apelação.
- **Preclusão**: É indispensável considerar a previsão legal da existência do recurso antes de interpor o recurso.

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de voluntariedade e previsão legal nos recursos criminais.
- Conheça o conceito de duplo grau de jurisdição e sua importância nos recursos criminais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.613", "page_number": 613, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:17:52.032265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=613", "doc_key": "774bf1be23373faccc341e2926960e58"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '837fcb13a8c148e35ba7ff05ac27224d55a416cb631949d41e832bf84e5493ce'),
  ('cpiuris2025::7a681a989f472f062ca9cd68ce5dedaa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Taxatividade dos recursos e cabimento do recurso em sentido estrito', '## Taxatividade dos recursos e cabimento do recurso em sentido estrito

Resumo objetivo: A taxatividade dos recursos é condição necessária para que a decisão seja recorrível. No entanto, não se pode concluir pela impossibilidade de interpretação extensiva da norma processual penal ou aplicação analógica.

### Conceitos
- **Taxatividade**: Condição necessária para que a decisão seja recorrível
- **Princípio da taxatividade**: Exige que o ordenamento jurídico preveja expressamente o recurso
- **Recurso inominado**: Não admitido no processo penal
- **Interpretação extensiva**: Acesso a normas não expressamente previstas, mas que podem ser aplicadas por analogia
- **Aplicação analógica**: Uso de regras ou princípios para resolver problemas não previstos pela lei

### Referências legais
- Art. 105 do CPP
- Art. 581 do CPP

### Dicas de prova
- Entenda a taxatividade dos recursos e o cabimento do recurso em sentido estrito
- Pergunte sobre a interpretação extensiva e aplicação analógica na legislação processual penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.615 (2)", "page_number": 615, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105 do CPP", "Art. 581 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:19:14.662068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=615", "doc_key": "7a681a989f472f062ca9cd68ce5dedaa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e087850175ad1e5e7e48d184e49800f2ff11118a3daec9dd692b313e18af57e9'),
  ('cpiuris2025::14edb642fc9bbafeb61047a23655083d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fungibilidade recursal e princípios de fungibilidade', '## Fungibilidade recursal e princípios de fungibilidade

O princípio da fungibilidade recursal determina que a parte não será prejudicada pela interposição de um recurso por outro, salvo hipótese de má-fé. A má-fé é presumida quando há erro manifesto ou intenção de enganar.

### Conceitos
- **Fungibilidade recursal**: Princípio que determina que a parte não será prejudicada pela interposição de um recurso por outro, salvo hipótese de má-fé.
- **Má-fé**: Presunção de intenção de enganar ou erro manifesto que impede a aplicação do princípio da fungibilidade recursal

### Referências legais
- Art. 579, caput, do CPP

### Dicas de prova
- Entenda o conceito de fungibilidade recursal e suas limitações.
- Identifique a hipótese de má-fé que impede a aplicação do princípio da fungibilidade recursal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.616 (2)", "page_number": 616, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 579, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:19:55.810650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=616", "doc_key": "14edb642fc9bbafeb61047a23655083d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0d31eb7e772197f563b7b215bb5c498c3a431eade7ffce529a2c359eb55f0197'),
  ('cpiuris2025::45836afc0127972a3d315f8e98bc0a25', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Unirrecorribilidade das Decisões', '## Unirrecorribilidade das Decisões

O princípio da unirrecorribilidade das decisões estabelece que cada espécie de decisão judicial comporta um único recurso, sendo ônus da parte escolher o recurso adequado. No entanto, existem exceções, como a interposição de embargos infringentes e de nulidade contra a parte não unânime de decisão.

### Conceitos
- **Unirrecorribilidade**: Princípio que estabelece que cada espécie de decisão judicial comporta um único recurso
- **Recurso**: Ato processual que visa impugnar uma decisão judicial
- **Interesse recursal**: Direito da parte de se valer do recurso
- **Princípio da unicidade recursal**: Cada espécie de decisão comporta um único recurso

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- TÁVORA; ALENCAR
- LIMA, 2020

### Dicas de prova
- Entenda o princípio da unirrecorribilidade e as exceções que existem para sua aplicação
- Conheça os diferentes tipos de recursos e seus respectivos termos de interposição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.616 (1)", "page_number": 616, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["TÁVORA; ALENCAR", "LIMA, 2020"], "confidence": 0.8, "extracted_at": "2026-05-29T10:20:25.560567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=616", "doc_key": "45836afc0127972a3d315f8e98bc0a25"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '11e07803baebded8335aa681844e26013d80cc4028653c56897b3c582d88915c'),
  ('cpiuris2025::63365aea4b7aca8753322d7690d70e9c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fungibilidade Recursal', '## Fungibilidade Recursal

Não for observado o prazo previsto em lei para o recurso adequado, a parte agiu de boa-fé se interpor o recurso errado no prazo legal do recurso adequado. Não há erro grosseiro quando há discussão doutrinária e/ou jurisprudencial acerca de qual é o recurso cabível.

### Conceitos
- **Fungibilidade Recursal**: Princípio que permite a aplicação do mesmo procedimento recursal em diferentes recursos
- **Erro Grosseiro**: Ignorância completa e injustificável da parte, que impede a aplicação do princípio da fungibilidade
- **Boa-fé**: Ação motivada por um motivo legítimo e honesto
- **Prazo Legal**: Prazo estabelecido pela lei para interpor recurso

### Referências legais
- Art. 574 do CPP
- Art. 593 do CPP
- Art. 579, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre boa-fé e má-fé na interposição de recurso
- Entender quando há erro grosseiro e quando não há discussão doutrinária e jurisprudencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.617 (1)", "page_number": 617, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 593 do CPP", "Art. 579, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:21:42.009591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=617", "doc_key": "63365aea4b7aca8753322d7690d70e9c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '87e335ff020e7f2dbe013ffbb7bb7289f47cd9c22de1ad82afd73393a23fe75a'),
  ('cpiuris2025::b1d382053ce86365a48748dd59569863', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fungibilidade Recursal', '## Fungibilidade Recursal

O princípio da fungibilidade recursal permite a aplicação de um recurso cabível em vez de outro inadequado, desde que o recurso seja interposto dentro do prazo e com os requisitos de admissibilidade adequados. No entanto, não se aplica quando há intuito manifestamente protelatório ou má-fé.

### Conceitos
- **Fungibilidade Recursal**: Princípio que permite a aplicação de um recurso cabível em vez de outro inadequado
- **Intuito Manifestamente Protelatório**: Condição que caracteriza má-fé e obsta a incidência da norma processual
- **Má-Fé**: Atitude ilícita que visa prejudicar o processo ou o adversário

### Referências legais
- Art. 574 do CPP
- Art. 579 do CPP
- Art. 80 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de fungibilidade recursal e suas limitações
- Identifique as condições para aplicação da fungibilidade recursal (temporaisidade, admissibilidade, intuito protelatório)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.618 (1)", "page_number": 618, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 579 do CPP", "Art. 80 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:22:12.105767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=618", "doc_key": "b1d382053ce86365a48748dd59569863"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fb570e522e64850a17196327c13f96b600775356de5c1aff60234084f2d4da79'),
  ('cpiuris2025::ecb7cc05b0fb2b36f9ff0379bb41a6f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Aplicação da Fungibilidade Recursal', '## Aplicação da Fungibilidade Recursal

A jurisprudência do STJ permite a aplicação da fungibilidade no uso do recurso de apelação em detrimento do recurso em sentido estrito, desde que demonstradas a ausência de má-fé e a tempestividade do instrumento processual.

### Conceitos
- **Fungibilidade Recursal**: Princípio que permite a aplicação da fungibilidade no uso do recurso de apelação em detrimento do recurso em sentido estrito
- **Má-fé**: Pressuposto para aplicação do princípio da fungibilidade, não sendo sinônimo de erro grosseiro
- **Tempestividade**: Critério estabelecido em lei sobre o que se considera litigância de má-fé
- **Litigância de Má-fé**: Conduzida pela parte com o objetivo de prejudicar o adversário
- **Erro Grosseiro**: Ocorrência de erro grave que pode ser considerado como má-fé
- **Princípio da Fungibilidade**: Permite a aplicação do mesmo princípio jurídico em diferentes casos
- **Recurso de Apelação**: Recurso apresentado contra decisão de primeira instância
- **Recurso em Sentido Estrito**: Recurso apresentado contra decisão de segunda instância

### Referências legais
- Art. 416 do CPP
- Art. 579 do CPP

### Jurisprudência
- AgRg no AREsp 1.541.008/MG
- RE n. 1.240.307/MT

### Dicas de prova
- Entenda a diferença entre recurso de apelação e recurso em sentido estrito
- Conheça o critério estabelecido para aplicação do princípio da fungibilidade
- Identifique a ausência de má-fé como pressuposto para aplicação do princípio da fungibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.617 (2)", "page_number": 617, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 416 do CPP", "Art. 579 do CPP"], "jurisprudence": ["AgRg no AREsp 1.541.008/MG", "RE n. 1.240.307/MT"], "confidence": 0.8, "extracted_at": "2026-05-29T10:22:27.450300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=617", "doc_key": "ecb7cc05b0fb2b36f9ff0379bb41a6f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f986f8ee5001150999728385ceba7ef51f261d66911d69d4153bb6b899a763e7'),
  ('cpiuris2025::8c4ae5c758444693a1b7da148e2eed86', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reexame necessário e arquivamento de inquérito policial', '## Reexame necessário e arquivamento de inquérito policial

Acusados em crime contra a economia popular ou saúde pública: reexame necessário não é aplicável à sentença condenatória; o arquivamento do inquérito policial não requer homologação judicial, desde que não seja declarada a inconstitucionalidade do art. 28 do CPP.

### Conceitos
- **Reexame necessário**: processo em que o juiz revisa a sentença condenatória
- **Arquivamento de inquérito policial**: decisão do juiz para encerrar o inquérito policial sem prosseguir com as investigações

### Referências legais
- Art. 7º, segunda parte, da Lei n.º 1.521/51
- Art. 28, caput, do CPP

### Jurisprudência
- Súmula n.º 160 do STF

### Dicas de prova
- Diferenciar reexame necessário de outros recursos
- Entender a diferença entre arquivamento e homologação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.619 (2)", "page_number": 619, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, segunda parte, da Lei n.º 1.521/51", "Art. 28, caput, do CPP"], "jurisprudence": ["Súmula n.º 160 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:24:30.142345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=619", "doc_key": "8c4ae5c758444693a1b7da148e2eed86"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '92a90d190d19ef2bdf365c527e3042f8983307c8cc1bfb450e1045c609759233'),
  ('cpiuris2025::6fa95a7d229f8230e51af3a74b669f9e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso de Ofício em Sentenças Criminais', '## Recurso de Ofício em Sentenças Criminais

Resumo do texto sobre recursos de ofício em sentenças criminais, incluindo hipóteses e regras para o reexame necessário.

### Conceitos
- **Recurso de Ofício**: Procedimento que não requer intervenção da parte para ser interposto
- **Sentença Concessiva de Habeas Corpus**: Sentença que concede liberdade ao réu
- **Reexame Necessário**: Obrigatório reexame da sentença por um tribunal superior
- **Absolvição Sumária**: Decisão do juiz que absolvia o acusado sem julgamento pelos jurados

### Referências legais
- Art. 574, I e II, CPP; Súmula n.º 423, STF

### Jurisprudência
- RE 123456
- Súmula n.º 344, STF

### Dicas de prova
- Entenda a diferença entre reexame necessário e absolvição sumária
- Conheça as hipóteses de recurso de ofício previstas no Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.619 (1)", "page_number": 619, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, I e II, CPP; Súmula n.º 423, STF"], "jurisprudence": ["RE 123456", "Súmula n.º 344, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:24:50.102796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=619", "doc_key": "6fa95a7d229f8230e51af3a74b669f9e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb533998f0580d2efda16ef16b76e25c43e3856d893a58c73c18251c4854fad2'),
  ('cpiuris2025::12da8227522f697f43f8983c046de09c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Voluntariedade nos recursos', '## Voluntariedade nos recursos

A voluntariedade é característica e princípio atinente às espécies recursais, sendo um ônus processual que não há obrigatoriedade de recorrer, mas pode sofrer consequências desfavoráveis se não for exercida.

### Conceitos
- **Voluntariedade**: Característica e princípio atinente às espécies recursais
- **Ônus processual**: Não há obrigatoriedade de recorrer, mas pode sofrer consequências desfavoráveis se não for exercida
- **Recurso de ofício**: Recurso obrigatório, necessário ou anômalo, somente cabível contra decisões proferidas por juiz singular

### Referências legais
- Art. 574, primeira parte, do CPP
- Súmula N STF

### Jurisprudência
- REsp n. 2.082.481/MG

### Dicas de prova
- Entenda a noção de voluntariedade e ônus processual nos recursos
- Conheça as espécies recursais, incluindo o recurso de ofício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.618 (2)", "page_number": 618, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, primeira parte, do CPP", "Súmula N STF"], "jurisprudence": ["REsp n. 2.082.481/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T10:24:50.795818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=618", "doc_key": "12da8227522f697f43f8983c046de09c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f9943d0422989370cade816e9e462cb1467862456e9fad7b4a45c3aec059e8a5')
